    async def _get_server_acceptance_openclaw_provider_readiness(self, *, workspace_id: str) -> dict[str, Any]:
        """Inspect the registered customer-machine OpenClaw provider without executing platform actions."""

        settings = get_settings()
        contract = "server_acceptance_openclaw_provider_readiness_gate"
        provider_name = str(settings.openclaw_provider or "mock").strip() or "mock"
        if not settings.openclaw_enabled:
            return {
                "ready": False,
                "success": False,
                "enabled": False,
                "reachable": False,
                "provider": provider_name,
                "mock": provider_name.lower() in {"mock", "disabled"},
                "worker_id": None,
                "worker_name": None,
                "real_publish_submit": False,
                "publish_submit_guarded": False,
                "capabilities": {},
                "actions": [],
                "readiness_status": "openclaw_disabled",
                "blocking_reasons": ["real_publish_provider_not_configured"],
                "error": "openclaw_disabled",
                "contract": contract,
                "server_side_external_execution": False,
            }

        worker = await BrowserWorkerSelector(self.session).select_worker(
            workspace_id=workspace_id,
            capability="openclaw",
        )
        if worker is None:
            return {
                "ready": False,
                "success": False,
                "enabled": True,
                "reachable": False,
                "provider": provider_name,
                "mock": provider_name.lower() in {"", "mock", "disabled"},
                "worker_id": None,
                "worker_name": None,
                "real_publish_submit": False,
                "publish_submit_guarded": False,
                "capabilities": {},
                "actions": [],
                "readiness_status": "openclaw_worker_unavailable",
                "blocking_reasons": ["real_publish_provider_not_configured", "openclaw_worker_unavailable"],
                "error": "No available OpenClaw worker",
                "contract": contract,
                "server_side_external_execution": False,
            }

        secret = BrowserWorkerAuthService.get_cached_secret(worker.id) or settings.browser_worker_shared_secret
        client = OpenClawWorkerClient(
            base_url=worker.base_url,
            timeout_seconds=min(float(settings.openclaw_action_timeout_seconds), 10.0),
            retry_count=0,
            retry_backoff_seconds=0.0,
            worker_id=str(worker.id),
            worker_secret=secret,
        )
        result = await client.capabilities()
        payload = result.data if isinstance(result.data, dict) else {}
        capabilities = payload.get("capabilities") if isinstance(payload.get("capabilities"), dict) else {}
        actions = [str(action) for action in payload.get("actions", []) if str(action or "").strip()]
        resolved_provider = str(payload.get("provider") or provider_name)
        mock = bool(payload.get("mock", True))
        real_publish_submit = bool(capabilities.get("real_publish_submit"))
        publish_submit_guarded = bool(capabilities.get("publish_submit_guarded")) or "publish_submit_guarded" in actions
        ready = bool(result.success and not mock and real_publish_submit and publish_submit_guarded)
        blocking_reasons: list[str] = []
        if not ready:
            blocking_reasons.append("real_publish_provider_not_configured")
            if not result.success:
                blocking_reasons.append("openclaw_provider_capabilities_unreachable")
            if mock:
                blocking_reasons.append("openclaw_provider_is_mock")
            if not real_publish_submit:
                blocking_reasons.append("real_publish_submit_capability_missing")
            if not publish_submit_guarded:
                blocking_reasons.append("publish_submit_guarded_action_missing")

        return {
            "ready": ready,
            "success": bool(result.success),
            "enabled": True,
            "reachable": bool(result.success),
            "provider": resolved_provider,
            "mock": mock,
            "worker_id": str(worker.id),
            "worker_name": worker.worker_name,
            "real_publish_submit": real_publish_submit,
            "publish_submit_guarded": publish_submit_guarded,
            "capabilities": capabilities,
            "actions": actions,
            "readiness_status": "real_publish_provider_ready" if ready else "real_publish_provider_not_configured",
            "blocking_reasons": blocking_reasons,
            "error": result.error,
            "contract": contract,
            "server_side_external_execution": False,
        }

    async def create_operation(
        self,
        *,
        workspace_id: str,
        user_id: str | None,
        title: str,
        objective: str,
        target_audience: str | None = None,
        channels: list[str] | None = None,
        status: str = CommercialOperationStatus.DRAFT.value,
        priority: str = "normal",
        risk_level: str = "medium",
        budget_amount: Decimal | None = None,
        budget_currency: str = "CNY",
        start_at: datetime | None = None,
        end_at: datetime | None = None,
        knowledge_collection: str | None = None,
        success_metrics: list[str] | None = None,
        constraints: list[str] | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> CommercialOperation:
        self._validate_date_range(start_at=start_at, end_at=end_at)
        clean_title = self._clean_required_text(title, "title")
        clean_objective = self._clean_required_text(objective, "objective")
        clean_channels = self._clean_list(channels)
        clean_metrics = self._clean_list(success_metrics)
        clean_constraints = self._clean_list(constraints)
        operation = CommercialOperation(
            workspace_id=workspace_id,
            user_id=user_id,
            title=clean_title,
            objective=clean_objective,
            target_audience=target_audience.strip() if target_audience else None,
            channels=clean_channels,
            status=status,
            priority=priority,
            risk_level=risk_level,
            budget_amount=budget_amount,
            budget_currency=budget_currency.strip() or "CNY",
            start_at=start_at,
            end_at=end_at,
            knowledge_collection=knowledge_collection.strip() if knowledge_collection else None,
            success_metrics=clean_metrics,
            constraints=clean_constraints,
            operation_metadata=metadata or {},
        )
        operation.plan_outline = self.build_plan_outline(operation)
        self.session.add(operation)
        await self.session.commit()
        await self.session.refresh(operation)
        return operation

    async def list_operations(
        self,
        *,
        workspace_id: str,
        status: str | None = None,
        limit: int = 100,
    ) -> list[CommercialOperation]:
        statement = select(CommercialOperation).where(CommercialOperation.workspace_id == workspace_id)
        if status is not None:
            statement = statement.where(CommercialOperation.status == status)
        else:
            statement = statement.where(CommercialOperation.status != CommercialOperationStatus.ARCHIVED.value)
        result = await self.session.execute(statement.order_by(CommercialOperation.updated_at.desc()).limit(limit))
        return list(result.scalars().all())

    async def archive_operation(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None = None,
    ) -> CommercialOperation:
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        metadata = dict(operation.operation_metadata or {})
        metadata["archived_by"] = actor_user_id
        metadata["archived_at"] = datetime.now(UTC).isoformat()
        metadata["archive_reason"] = "operator_deleted_from_project_workspace"
        operation.operation_metadata = metadata
        operation.status = CommercialOperationStatus.ARCHIVED.value
        await self.session.commit()
        await self.session.refresh(operation)
        return operation

    def production_closed_loop_action_audit_summary_for_operation(
        self,
        operation: CommercialOperation,
        *,
        generated_at: datetime | None = None,
    ) -> dict[str, Any]:
        """Build the list-level closed-loop action-audit summary without mutating records."""

        records = self._production_closed_loop_action_audit_history(operation)
        latest_record = records[-1] if records else None
        operator_checklist = self._production_closed_loop_action_operator_checklist(latest_record)
        primary_step = next((item for item in operator_checklist if item.get("status") == "next"), None)
        generated = generated_at or datetime.now(UTC)
        primary_step_staleness = self._production_closed_loop_action_primary_step_staleness(
            primary_step=primary_step,
            latest_record=latest_record,
            operation_created_at=operation.created_at,
            generated_at=generated,
        )
        return {
            "audit_count": len(records),
            "latest_audit_id": str(latest_record.get("audit_id")) if latest_record and latest_record.get("audit_id") else None,
            "latest_action_key": str(latest_record.get("action_key")) if latest_record and latest_record.get("action_key") else None,
            "primary_step": primary_step,
            "primary_step_staleness": primary_step_staleness,
            "operator_checklist_contract": "production_closed_loop_action_audit_operator_checklist",
            "primary_step_contract": "production_closed_loop_action_audit_primary_step",
            "primary_step_staleness_contract": "production_closed_loop_action_audit_primary_step_staleness",
            "server_side_external_execution": False,
            "generated_at": generated.isoformat(),
        }

    async def get_production_closed_loop_intervention_queue(
        self,
        *,
        workspace_id: str,
        statuses: list[str] | None = None,
        limit: int = 50,
        scan_limit: int = 500,
    ) -> dict[str, Any]:
        """Return workspace-level stale/watch operations without executing any target action."""

        clean_statuses = [
            str(status).strip().lower()
            for status in (statuses or ["stale", "watch"])
            if str(status).strip()
        ]
        if not clean_statuses:
            clean_statuses = ["stale", "watch"]
        clean_limit = max(1, min(int(limit or 50), 100))
        clean_scan_limit = max(clean_limit, min(max(1, int(scan_limit or 500)), 500))
        generated = datetime.now(UTC)
        operations = await self.list_operations(workspace_id=workspace_id, limit=clean_scan_limit)
        items: list[dict[str, Any]] = []
        scanned_operation_count = 0
        for operation in operations:
            scanned_operation_count += 1
            summary = self.production_closed_loop_action_audit_summary_for_operation(
                operation,
                generated_at=generated,
            )
            staleness = summary.get("primary_step_staleness") if isinstance(summary.get("primary_step_staleness"), dict) else {}
            staleness_status = str(staleness.get("status") or "none").lower()
            if staleness_status not in clean_statuses:
                continue
            primary_step = summary.get("primary_step") if isinstance(summary.get("primary_step"), dict) else None
            waiting_seconds = int(staleness.get("waiting_seconds") or 0)
            priority_score = self._production_closed_loop_intervention_priority_score(
                staleness_status=staleness_status,
                waiting_seconds=waiting_seconds,
                operation=operation,
            )
            latest_acknowledgement = self._production_closed_loop_intervention_acknowledgement_latest(operation)
            acknowledgement_sla = self._production_closed_loop_intervention_acknowledgement_sla(
                latest_acknowledgement=latest_acknowledgement,
                generated_at=generated,
            )
            latest_reminder_dispatch = self._production_closed_loop_intervention_reminder_dispatch_latest(operation)
            reminder_dispatch_cooldown = self._production_closed_loop_intervention_reminder_dispatch_cooldown(
                latest_reminder_dispatch=latest_reminder_dispatch,
                acknowledgement_sla=acknowledgement_sla,
                generated_at=generated,
            )
            items.append(
                {
                    "operation": operation,
                    "operation_id": operation.id,
                    "workspace_id": operation.workspace_id,
                    "operation_title": operation.title,
                    "operation_status": operation.status,
                    "operation_priority": operation.priority,
                    "operation_risk_level": operation.risk_level,
                    "action_audit_summary": summary,
                    "primary_step": primary_step,
                    "primary_step_key": str(primary_step.get("step_key")) if primary_step else None,
                    "primary_step_label": str(primary_step.get("label")) if primary_step and primary_step.get("label") else None,
                    "staleness_status": staleness_status,
                    "waiting_seconds": waiting_seconds,
                    "escalation_recommended": bool(staleness.get("escalation_recommended")),
                    "priority_score": priority_score,
                    "recommended_action_key": self._production_closed_loop_intervention_recommended_action_key(primary_step),
                    "latest_intervention_acknowledgement": latest_acknowledgement or {},
                    "acknowledgement_status": (
                        str(latest_acknowledgement.get("acknowledgement_status"))
                        if latest_acknowledgement and latest_acknowledgement.get("acknowledgement_status")
                        else None
                    ),
                    "acknowledgement_assignee": (
                        str(latest_acknowledgement.get("assignee"))
                        if latest_acknowledgement and latest_acknowledgement.get("assignee")
                        else None
                    ),
                    "acknowledgement_sla": acknowledgement_sla,
                    "latest_intervention_reminder_dispatch": latest_reminder_dispatch or {},
                    "reminder_dispatch_status": (
                        str(latest_reminder_dispatch.get("reminder_status"))
                        if latest_reminder_dispatch and latest_reminder_dispatch.get("reminder_status")
                        else None
                    ),
                    "reminder_dispatch_channel": (
                        str(latest_reminder_dispatch.get("reminder_channel"))
                        if latest_reminder_dispatch and latest_reminder_dispatch.get("reminder_channel")
                        else None
                    ),
                    "reminder_dispatch_cooldown": reminder_dispatch_cooldown,
                    "reminder_follow_up_recommended": bool(
                        reminder_dispatch_cooldown.get("follow_up_recommended")
                    ),
                    "reminder_next_allowed_at": reminder_dispatch_cooldown.get("next_allowed_at"),
                    "reason": (
                        str(staleness.get("escalation_reason"))
                        if staleness.get("escalation_reason")
                        else str(primary_step.get("detail") or primary_step.get("blocking_reason"))
                        if primary_step
                        else None
                    ),
                }
            )

        items.sort(key=lambda item: (int(item["priority_score"]), int(item["waiting_seconds"])), reverse=True)
        limited_items = items[:clean_limit]
        stale_count = sum(1 for item in limited_items if item["staleness_status"] == "stale")
        watch_count = sum(1 for item in limited_items if item["staleness_status"] == "watch")
        acknowledgement_sla_status_counts: dict[str, int] = {}
        reminder_dispatch_status_counts: dict[str, int] = {}
        reminder_cooldown_status_counts: dict[str, int] = {}
        for item in limited_items:
            acknowledgement_sla = item.get("acknowledgement_sla") if isinstance(item.get("acknowledgement_sla"), dict) else {}
            acknowledgement_sla_status = str(acknowledgement_sla.get("status") or "unknown").lower()
            acknowledgement_sla_status_counts[acknowledgement_sla_status] = (
                acknowledgement_sla_status_counts.get(acknowledgement_sla_status, 0) + 1
            )
            reminder_dispatch_status = str(item.get("reminder_dispatch_status") or "none").lower()
            reminder_dispatch_status_counts[reminder_dispatch_status] = (
                reminder_dispatch_status_counts.get(reminder_dispatch_status, 0) + 1
            )
            reminder_cooldown = (
                item.get("reminder_dispatch_cooldown")
                if isinstance(item.get("reminder_dispatch_cooldown"), dict)
                else {}
            )
            reminder_cooldown_status = str(reminder_cooldown.get("status") or "unknown").lower()
            reminder_cooldown_status_counts[reminder_cooldown_status] = (
                reminder_cooldown_status_counts.get(reminder_cooldown_status, 0) + 1
            )
        acknowledgement_overdue_count = sum(
            acknowledgement_sla_status_counts.get(status, 0)
            for status in ("due_soon", "overdue", "unknown", "unassigned")
        )
        reminder_follow_up_count = sum(1 for item in limited_items if bool(item.get("reminder_follow_up_recommended")))
        recommended_action = self._production_closed_loop_intervention_queue_recommended_action(limited_items)
        queue_summary = {
            "contract": "production_closed_loop_intervention_queue_summary",
            "phase": "69S",
            "queue_count": len(limited_items),
            "stale_count": stale_count,
            "watch_count": watch_count,
            "acknowledgement_sla_status_counts": acknowledgement_sla_status_counts,
            "reminder_dispatch_status_counts": reminder_dispatch_status_counts,
            "reminder_cooldown_status_counts": reminder_cooldown_status_counts,
            "acknowledgement_overdue_count": acknowledgement_overdue_count,
            "reminder_follow_up_count": reminder_follow_up_count,
            "recommended_action": recommended_action,
            "server_side_external_execution": False,
            "server_read_only_no_openclaw_no_playwright_no_publish": True,
        }
        return {
            "workspace_id": workspace_id,
            "queue_status": "requires_operator_intervention" if limited_items else "empty",
            "statuses": clean_statuses,
            "queue_count": len(limited_items),
            "stale_count": stale_count,
            "watch_count": watch_count,
            "acknowledgement_sla_status_counts": acknowledgement_sla_status_counts,
            "reminder_dispatch_status_counts": reminder_dispatch_status_counts,
            "reminder_cooldown_status_counts": reminder_cooldown_status_counts,
            "acknowledgement_overdue_count": acknowledgement_overdue_count,
            "reminder_follow_up_count": reminder_follow_up_count,
            "queue_summary": queue_summary,
            "recommended_action": recommended_action,
            "scanned_operation_count": scanned_operation_count,
            "scan_limit": clean_scan_limit,
            "limit": clean_limit,
            "items": limited_items,
            "generated_at": generated,
            "boundaries": [
                "read_only_queue_only",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_accounts",
                "does_not_bypass_operator_approval",
            ],
            "metadata": {
                "phase": "69N",
                "contract": "production_closed_loop_intervention_queue",
                "primary_step_staleness_contract": "production_closed_loop_action_audit_primary_step_staleness",
                "server_side_external_execution": False,
                "server_read_only_no_openclaw_no_playwright_no_publish": True,
            },
        }

    async def get_production_closed_loop_acceptance_summary(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
    ) -> dict[str, Any]:
        """Aggregate workspace production closed-loop acceptance without executing external actions."""

        clean_limit = max(1, min(int(limit or 25), 50))
        clean_scan_limit = max(clean_limit, min(max(1, int(scan_limit or 50)), 100))
        clean_platform = platform.strip().lower() if platform and platform.strip() else None
        generated = datetime.now(UTC)
        operations = await self.list_operations(workspace_id=workspace_id, limit=clean_scan_limit)
        intervention_queue = await self.get_production_closed_loop_intervention_queue(
            workspace_id=workspace_id,
            statuses=["stale", "watch"],
            limit=clean_scan_limit,
            scan_limit=clean_scan_limit,
        )
        intervention_operation_ids = {
            str(item.get("operation_id"))
            for item in intervention_queue.get("items", [])
            if isinstance(item, dict) and item.get("operation_id")
        }
        openclaw_provider_readiness = await self._get_server_acceptance_openclaw_provider_readiness(
            workspace_id=workspace_id,
        )
        openclaw_provider_ready = bool(openclaw_provider_readiness.get("ready"))

        readiness_status_counts: dict[str, int] = {}
        current_stage_counts: dict[str, int] = {}
        staleness_status_counts: dict[str, int] = {}
        rows: list[dict[str, Any]] = []
        accepted_statuses = {
            "ready_for_customer_machine_execution",
            "ready_for_metric_feedback",
            "ready_for_next_cycle",
        }

        def count_value(bucket: dict[str, int], value: str | None) -> None:
            key = str(value or "none").strip().lower() or "none"
            bucket[key] = bucket.get(key, 0) + 1

        def add_unique(target: list[str], value: Any) -> None:
            text = str(value or "").strip()
            if text and text not in target:
                target.append(text)

        for operation in operations:
            readiness = await self.get_production_closed_loop_readiness(
                workspace_id=workspace_id,
                operation_id=operation.id,
                platform=clean_platform,
                force_metric_due=force_metric_due,
            )
            stages = readiness.get("stages") if isinstance(readiness.get("stages"), list) else []
            stage_by_key = {
                str(stage.get("stage_key")): stage
                for stage in stages
                if isinstance(stage, dict) and stage.get("stage_key")
            }
            current_stage_key = readiness.get("current_stage_key")
            current_stage = stage_by_key.get(str(current_stage_key)) if current_stage_key else None
            if current_stage is None:
                current_stage = next(
                    (
                        stage
                        for stage in stages
                        if isinstance(stage, dict)
                        and stage.get("required")
                        and str(stage.get("status") or "") != "complete"
                    ),
                    None,
                )
            action_summary = self.production_closed_loop_action_audit_summary_for_operation(
                operation,
                generated_at=generated,
            )
            staleness = (
                action_summary.get("primary_step_staleness")
                if isinstance(action_summary.get("primary_step_staleness"), dict)
                else {}
            )
            staleness_status = str(staleness.get("status") or "none").strip().lower() or "none"
            try:
                waiting_seconds = int(staleness.get("waiting_seconds") or 0)
            except (TypeError, ValueError):
                waiting_seconds = 0
            escalation_recommended = bool(staleness.get("escalation_recommended"))
            readiness_status = str(readiness.get("readiness_status") or "needs_operator_action").strip().lower()
            resolved_current_stage_key = str(
                readiness.get("current_stage_key")
                or (current_stage or {}).get("stage_key")
                or "closed_loop_complete"
            )
            blocking_reasons: list[str] = []
            if current_stage:
                for reason in (current_stage.get("blocking_reasons") or [])[:5]:
                    add_unique(blocking_reasons, reason)
                current_stage_status = str(current_stage.get("status") or "").strip().lower()
                if current_stage_status == "review_required":
                    add_unique(blocking_reasons, f"{resolved_current_stage_key}_requires_operator_review")
                elif current_stage_status == "missing":
                    add_unique(blocking_reasons, f"{resolved_current_stage_key}_missing")
            if readiness_status in {"blocked", "review_required", "needs_operator_action"}:
                add_unique(blocking_reasons, readiness_status)
            if staleness_status in {"stale", "watch"}:
                add_unique(blocking_reasons, f"primary_step_{staleness_status}")
            if escalation_recommended:
                add_unique(blocking_reasons, "primary_step_escalation_recommended")
            if str(operation.id) in intervention_operation_ids:
                add_unique(blocking_reasons, "operation_in_intervention_queue")

            operator_next_actions = [
                str(item)
                for item in readiness.get("operator_next_actions", [])
                if str(item or "").strip()
            ][:5]
            row = {
                "operation_id": operation.id,
                "title": operation.title,
                "status": operation.status,
                "readiness_status": readiness_status,
                "completion_ratio": float(readiness.get("completion_ratio") or 0),
                "current_stage_key": resolved_current_stage_key,
                "next_action": str(readiness.get("next_action") or ""),
                "ready_for_customer_machine_execution": bool(readiness.get("ready_for_customer_machine_execution")),
                "ready_for_metric_feedback": bool(readiness.get("ready_for_metric_feedback")),
                "ready_for_next_cycle": bool(readiness.get("ready_for_next_cycle")),
                "staleness_status": staleness_status,
                "waiting_seconds": waiting_seconds,
                "escalation_recommended": escalation_recommended,
                "blocking_reasons": blocking_reasons,
                "operator_next_actions": operator_next_actions,
            }
            rows.append(row)
            count_value(readiness_status_counts, row["readiness_status"])
            count_value(current_stage_counts, row["current_stage_key"])
            count_value(staleness_status_counts, row["staleness_status"])

        accepted_count = sum(1 for row in rows if row["readiness_status"] in accepted_statuses)
        ready_for_customer_machine_execution_count = sum(
            1 for row in rows if row["ready_for_customer_machine_execution"]
        )
        ready_for_metric_feedback_count = sum(1 for row in rows if row["ready_for_metric_feedback"])
        ready_for_next_cycle_count = sum(1 for row in rows if row["ready_for_next_cycle"])
        blocked_rows = [
            row
            for row in rows
            if row["blocking_reasons"]
            or row["readiness_status"] in {"blocked", "review_required", "needs_operator_action"}
            or row["staleness_status"] in {"stale", "watch"}
            or row["escalation_recommended"]
        ]
        blocked_count = len(blocked_rows)
        operation_count = len(rows)
        intervention_queue_count = int(intervention_queue.get("queue_count") or 0)
        if not operation_count:
            acceptance_status = "empty"
        elif intervention_queue_count:
            acceptance_status = "requires_intervention"
        elif not openclaw_provider_ready and accepted_count == operation_count and blocked_count == 0:
            acceptance_status = "requires_runtime_provider"
        elif accepted_count == operation_count and blocked_count == 0:
            acceptance_status = "accepted"
        elif accepted_count > 0 and blocked_count > 0:
            acceptance_status = "partially_ready_with_blockers"
        elif accepted_count > 0:
            acceptance_status = "partially_ready"
        else:
            acceptance_status = "requires_operator_action"

        if operation_count:
            accepted_ratio = accepted_count / operation_count
            customer_machine_ratio = ready_for_customer_machine_execution_count / operation_count
            metric_feedback_ratio = ready_for_metric_feedback_count / operation_count
            next_cycle_ratio = ready_for_next_cycle_count / operation_count
            blocker_clear_ratio = max(0.0, 1.0 - (blocked_count / operation_count))
            score_breakdown = {
                "operation_presence": 10,
                "accepted_readiness": round(accepted_ratio * 25),
                "customer_machine_execution_ready": round(customer_machine_ratio * 15),
                "metric_feedback_ready": round(metric_feedback_ratio * 15),
                "next_cycle_ready": round(next_cycle_ratio * 10),
                "blocker_clear": round(blocker_clear_ratio * 10),
                "intervention_queue_clear": 5 if intervention_queue_count == 0 else 0,
                "real_publish_provider_ready": 10 if openclaw_provider_ready else 0,
            }
        else:
            score_breakdown = {
                "operation_presence": 0,
                "accepted_readiness": 0,
                "customer_machine_execution_ready": 0,
                "metric_feedback_ready": 0,
                "next_cycle_ready": 0,
                "blocker_clear": 0,
                "intervention_queue_clear": 0,
                "real_publish_provider_ready": 0,
            }
        completion_percent = max(0, min(100, sum(score_breakdown.values())))
        if not operation_count:
            completion_level = "empty"
        elif completion_percent >= 100:
            completion_level = "closed_loop_ready"
        elif completion_percent >= 85 and blocked_count == 0 and intervention_queue_count == 0:
            completion_level = "production_ready"
        elif completion_percent >= 65:
            completion_level = "operable"
        elif completion_percent >= 35:
            completion_level = "building"
        else:
            completion_level = "not_ready"
        remaining_gates: list[str] = []
        if not operation_count:
            remaining_gates.append("create_or_import_operation_project")
        if operation_count and accepted_count < operation_count:
            remaining_gates.append("close_operation_readiness_gaps")
        if operation_count and ready_for_customer_machine_execution_count < operation_count:
            remaining_gates.append("prepare_customer_machine_execution_handoff")
        if operation_count and ready_for_metric_feedback_count < operation_count:
            remaining_gates.append("complete_metric_feedback_setup")
        if operation_count and ready_for_next_cycle_count < operation_count:
            remaining_gates.append("approve_analysis_and_next_cycle_decision")
        if blocked_count:
            remaining_gates.append("clear_blocking_reasons")
        if operation_count and not openclaw_provider_ready:
            remaining_gates.append("configure_real_openclaw_publish_provider")
        if intervention_queue_count:
            remaining_gates.append("resolve_or_acknowledge_intervention_queue")

        def release_gate(
            *,
            gate_key: str,
            title: str,
            owner: str,
            ready: bool,
            blocking_reasons: list[str],
            evidence: list[str],
            next_action: str,
            verification_commands: list[str] | None = None,
        ) -> dict[str, Any]:
            status = "ready" if ready else "blocked"
            return {
                "gate_key": gate_key,
                "title": title,
                "owner": owner,
                "required": True,
                "ready": ready,
                "status": status,
                "blocking_reasons": blocking_reasons,
                "evidence": evidence,
                "next_action": next_action,
                "verification_commands": verification_commands or [
                    "python scripts/check_production_closed_loop.py --report-only"
                ],
            }

        operation_project_ready = bool(operation_count and accepted_count == operation_count and blocked_count == 0)
        customer_machine_handoff_ready = bool(
            operation_count and ready_for_customer_machine_execution_count == operation_count
        )
        publish_result_ready = bool(operation_count and ready_for_metric_feedback_count == operation_count)
        next_cycle_ready = bool(operation_count and ready_for_next_cycle_count == operation_count)
        release_gate_checklist = [
            release_gate(
                gate_key="operation_project_readiness",
                title="Operation projects are accepted and unblocked",
                owner="operation_owner",
                ready=operation_project_ready,
                blocking_reasons=[
                    *([] if operation_count else ["create_or_import_operation_project"]),
                    *([] if accepted_count == operation_count else ["close_operation_readiness_gaps"]),
                    *([] if blocked_count == 0 else ["clear_blocking_reasons"]),
                ],
                evidence=[
                    f"operation_count={operation_count}",
                    f"accepted_count={accepted_count}",
                    f"blocked_count={blocked_count}",
                ],
                next_action="close_operation_readiness_gaps",
            ),
            release_gate(
                gate_key="customer_machine_execution_handoff",
                title="Customer-machine execution handoff is ready",
                owner="customer_machine_operator",
                ready=customer_machine_handoff_ready,
                blocking_reasons=[] if customer_machine_handoff_ready else ["prepare_customer_machine_execution_handoff"],
                evidence=[
                    f"ready_for_customer_machine_execution_count={ready_for_customer_machine_execution_count}",
                    f"operation_count={operation_count}",
                ],
                next_action="prepare_customer_machine_execution_handoff",
            ),
            release_gate(
                gate_key="real_openclaw_publish_provider",
                title="Real OpenClaw publish provider is configured and smoke-verified",
                owner="server_operator",
                ready=openclaw_provider_ready,
                blocking_reasons=list(openclaw_provider_readiness.get("blocking_reasons") or [])
                or ([] if openclaw_provider_ready else ["configure_real_openclaw_publish_provider"]),
                evidence=[
                    f"readiness_status={openclaw_provider_readiness.get('readiness_status', 'unknown')}",
                    f"provider={openclaw_provider_readiness.get('provider', 'unknown')}",
                    f"mock={openclaw_provider_readiness.get('mock', 'unknown')}",
                ],
                next_action="configure_real_openclaw_publish_provider",
                verification_commands=[
                    "python scripts/check_production_config.py --require-production",
                    "python scripts/check_openclaw_provider.py",
                ],
            ),
            release_gate(
                gate_key="customer_machine_publish_result_evidence",
                title="Customer-machine publish result evidence has returned",
                owner="customer_machine_operator",
                ready=publish_result_ready,
                blocking_reasons=[] if publish_result_ready else ["complete_customer_machine_publish_result_evidence"],
                evidence=[
                    f"ready_for_metric_feedback_count={ready_for_metric_feedback_count}",
                    f"operation_count={operation_count}",
                ],
                next_action="record_customer_machine_publish_result_and_metrics",
            ),
            release_gate(
                gate_key="metric_feedback_and_next_cycle",
                title="Metric feedback is approved and next cycle is ready",
                owner="operations_analyst",
                ready=next_cycle_ready,
                blocking_reasons=[] if next_cycle_ready else ["approve_analysis_and_next_cycle_decision"],
                evidence=[
                    f"ready_for_next_cycle_count={ready_for_next_cycle_count}",
                    f"operation_count={operation_count}",
                ],
                next_action="approve_analysis_and_next_cycle_decision",
            ),
            release_gate(
                gate_key="intervention_queue_clear",
                title="Intervention queue is clear",
                owner="operation_owner",
                ready=intervention_queue_count == 0,
                blocking_reasons=[] if intervention_queue_count == 0 else ["resolve_or_acknowledge_intervention_queue"],
                evidence=[f"intervention_queue_count={intervention_queue_count}"],
                next_action="resolve_or_acknowledge_intervention_queue",
            ),
        ]
        release_gate_status_counts: dict[str, int] = {}
        for gate in release_gate_checklist:
            status = str(gate.get("status") or "unknown")
            release_gate_status_counts[status] = release_gate_status_counts.get(status, 0) + 1
        release_gate_ready_count = release_gate_status_counts.get("ready", 0)
        release_gate_total_count = len(release_gate_checklist)
        release_ready = bool(release_gate_total_count and release_gate_ready_count == release_gate_total_count)
        next_focus = remaining_gates[0] if remaining_gates else "maintain_closed_loop_or_prepare_next_cycle"

        def blocker_priority(row: dict[str, Any]) -> tuple[int, int, int, int, float]:
            staleness_rank = 2 if row["staleness_status"] == "stale" else 1 if row["staleness_status"] == "watch" else 0
            return (
                1 if row["escalation_recommended"] else 0,
                staleness_rank,
                len(row["blocking_reasons"]),
                int(row["waiting_seconds"] or 0),
                1.0 - float(row["completion_ratio"] or 0),
            )

        top_blockers = sorted(blocked_rows, key=blocker_priority, reverse=True)[:10]
        return {
            "workspace_id": workspace_id,
            "acceptance_status": acceptance_status,
            "operation_count": operation_count,
            "accepted_count": accepted_count,
            "ready_for_customer_machine_execution_count": ready_for_customer_machine_execution_count,
            "ready_for_metric_feedback_count": ready_for_metric_feedback_count,
            "ready_for_next_cycle_count": ready_for_next_cycle_count,
            "blocked_count": blocked_count,
            "intervention_queue_count": intervention_queue_count,
            "completion_percent": completion_percent,
            "completion_level": completion_level,
            "score_breakdown": score_breakdown,
            "remaining_gates": remaining_gates,
            "next_focus": next_focus,
            "readiness_status_counts": readiness_status_counts,
            "current_stage_counts": current_stage_counts,
            "staleness_status_counts": staleness_status_counts,
            "operations": rows[:clean_limit],
            "top_blockers": top_blockers,
            "openclaw_provider_readiness": openclaw_provider_readiness,
            "release_ready": release_ready,
            "release_gate_ready_count": release_gate_ready_count,
            "release_gate_total_count": release_gate_total_count,
            "release_gate_status_counts": release_gate_status_counts,
            "release_gate_checklist": release_gate_checklist,
            "acceptance_gates": [
                "production_closed_loop_e2e_readiness",
                "workspace_acceptance_summary_is_server_aggregated",
                "production_release_gate_checklist_is_machine_readable",
                "real_openclaw_publish_provider_ready_for_customer_machine_submit",
                "operator_approval_required_before_external_execution",
                "customer_machine_executes_openclaw_playwright_after_approval",
                "metric_feedback_returns_with_evidence_before_next_cycle",
            ],
            "boundaries": [
                "acceptance_summary_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_submit_comfyui_prompts",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_collect_credentials_or_verification_codes",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": generated,
            "metadata": {
                "phase": "70E",
                "contract": "production_closed_loop_acceptance_summary",
                "completion_score_contract": "production_closed_loop_completion_score",
                "source_readiness_contract": "production_closed_loop_e2e_readiness",
                "source_intervention_queue_contract": "production_closed_loop_intervention_queue",
                "provider_readiness_contract": "server_acceptance_openclaw_provider_readiness_gate",
                "openclaw_provider_readiness_status": openclaw_provider_readiness.get("readiness_status"),
                "openclaw_provider_ready": openclaw_provider_ready,
                "platform_filter": clean_platform,
                "force_metric_due": force_metric_due,
                "limit": clean_limit,
                "scan_limit": clean_scan_limit,
                "scanned_operation_count": len(operations),
                "returned_operation_count": min(len(rows), clean_limit),
                "server_side_external_execution": False,
                "server_read_only_no_openclaw_no_playwright_no_publish": True,
            },
        }

    async def get_production_closed_loop_delivery_plan(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
    ) -> dict[str, Any]:
        """Translate the workspace acceptance summary into an actionable delivery plan."""

        summary = await self.get_production_closed_loop_acceptance_summary(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        remaining_gates = {
            str(gate).strip()
            for gate in summary.get("remaining_gates", [])
            if str(gate or "").strip()
        }
        catalog = self._production_closed_loop_delivery_gate_catalog()
        provider = summary.get("openclaw_provider_readiness") if isinstance(summary.get("openclaw_provider_readiness"), dict) else {}
        operations = [row for row in summary.get("operations", []) if isinstance(row, dict)]
        top_blockers = [row for row in summary.get("top_blockers", []) if isinstance(row, dict)]

        def related_operation_ids(gate_key: str) -> list[Any]:
            if gate_key == "close_operation_readiness_gaps":
                return [row["operation_id"] for row in operations if str(row.get("readiness_status") or "") not in {"ready_for_customer_machine_execution", "ready_for_metric_feedback", "ready_for_next_cycle"} and row.get("operation_id")]
            if gate_key == "prepare_customer_machine_execution_handoff":
                return [row["operation_id"] for row in operations if not row.get("ready_for_customer_machine_execution") and row.get("operation_id")]
            if gate_key == "complete_metric_feedback_setup":
                return [row["operation_id"] for row in operations if not row.get("ready_for_metric_feedback") and row.get("operation_id")]
            if gate_key == "approve_analysis_and_next_cycle_decision":
                return [row["operation_id"] for row in operations if not row.get("ready_for_next_cycle") and row.get("operation_id")]
            if gate_key in {"clear_blocking_reasons", "resolve_or_acknowledge_intervention_queue"}:
                return [row["operation_id"] for row in top_blockers if row.get("operation_id")]
            return []

        def gate_blocking_reasons(gate_key: str) -> list[str]:
            reasons: list[str] = []
            if gate_key == "configure_real_openclaw_publish_provider":
                reasons.extend(str(item) for item in provider.get("blocking_reasons", []) if str(item or "").strip())
            if gate_key == "clear_blocking_reasons":
                for row in top_blockers:
                    reasons.extend(str(item) for item in row.get("blocking_reasons", []) if str(item or "").strip())
            if gate_key == "resolve_or_acknowledge_intervention_queue":
                for row in top_blockers:
                    if str(row.get("staleness_status") or "") in {"stale", "watch"}:
                        reasons.append(f"primary_step_{row.get('staleness_status')}")
            if gate_key in remaining_gates and not reasons:
                reasons.append(gate_key)
            unique: list[str] = []
            for reason in reasons:
                if reason not in unique:
                    unique.append(reason)
            return unique[:10]

        gate_plan: list[dict[str, Any]] = []
        for gate_key, template in catalog.items():
            is_open = gate_key in remaining_gates
            priority = int(template.get("priority") or 0)
            gate_status = "complete"
            if is_open:
                gate_status = "critical" if priority >= 90 else "open"
            gate_plan.append(
                {
                    **template,
                    "gate_key": gate_key,
                    "gate_status": gate_status,
                    "blocking_reasons": gate_blocking_reasons(gate_key) if is_open else [],
                    "related_operation_ids": related_operation_ids(gate_key) if is_open else [],
                    "external_execution_allowed": False,
                }
            )

        next_focus = str(summary.get("next_focus") or "create_or_import_operation_project")
        open_gate_plan = [gate for gate in gate_plan if gate["gate_status"] != "complete"]
        open_gate_plan.sort(key=lambda item: (0 if item["gate_key"] == next_focus else 1, -int(item.get("priority") or 0)))
        open_gate_count = len(open_gate_plan)
        critical_gate_count = sum(1 for gate in open_gate_plan if int(gate.get("priority") or 0) >= 90)
        ready_for_handoff = (
            summary.get("acceptance_status") == "accepted"
            and summary.get("completion_level") == "closed_loop_ready"
            and int(summary.get("completion_percent") or 0) >= 100
            and open_gate_count == 0
            and bool(provider.get("ready"))
        )
        if ready_for_handoff:
            delivery_status = "ready_for_customer_machine_handoff"
        elif not int(summary.get("operation_count") or 0):
            delivery_status = "not_started"
        elif critical_gate_count:
            delivery_status = "blocked_by_critical_gate"
        elif open_gate_count:
            delivery_status = "operator_action_required"
        else:
            delivery_status = "review_required"

        return {
            "workspace_id": workspace_id,
            "delivery_status": delivery_status,
            "acceptance_status": str(summary.get("acceptance_status") or "unknown"),
            "completion_percent": int(summary.get("completion_percent") or 0),
            "completion_level": str(summary.get("completion_level") or "not_ready"),
            "next_focus": next_focus,
            "ready_for_handoff": ready_for_handoff,
            "gate_count": len(gate_plan),
            "open_gate_count": open_gate_count,
            "critical_gate_count": critical_gate_count,
            "gate_plan": gate_plan,
            "immediate_actions": open_gate_plan[:3],
            "score_breakdown": dict(summary.get("score_breakdown") or {}),
            "openclaw_provider_readiness": provider,
            "acceptance_summary": summary,
            "acceptance_gates": [
                "production_closed_loop_acceptance_summary",
                "delivery_plan_is_derived_from_remaining_gates",
                "human_approval_required_before_external_execution",
                "real_openclaw_provider_required_before_publish_submit",
            ],
            "boundaries": [
                "delivery_plan_only_no_external_execution",
                "does_not_submit_comfyui_prompts",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "70U",
                "contract": "production_closed_loop_delivery_plan",
                "source_contract": "production_closed_loop_acceptance_summary",
                "provider_readiness_contract": "server_acceptance_openclaw_provider_readiness_gate",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "limit": max(1, min(int(limit or 25), 50)),
                "scan_limit": max(max(1, int(limit or 25)), min(max(1, int(scan_limit or 50)), 100)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
                "server_read_only_no_openclaw_no_playwright_no_publish": True,
            },
        }

    async def get_production_closed_loop_delivery_action_packages(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
    ) -> dict[str, Any]:
        """Package delivery gates into manual server/customer-console action steps."""

        delivery_plan = await self.get_production_closed_loop_delivery_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        gate_packages = [
            self._production_closed_loop_delivery_action_package(
                workspace_id=workspace_id,
                gate=gate,
                immediate=False,
            )
            for gate in delivery_plan.get("gate_plan", [])
            if isinstance(gate, dict)
        ]
        immediate_keys = {
            str(gate.get("gate_key") or "")
            for gate in delivery_plan.get("immediate_actions", [])
            if isinstance(gate, dict)
        }
        immediate_action_packages = [
            {**package, "immediate": True}
            for package in gate_packages
            if package["gate_key"] in immediate_keys and package["gate_status"] != "complete"
        ]
        open_packages = [package for package in gate_packages if package["gate_status"] != "complete"]
        step_count = sum(int(package.get("action_count") or 0) for package in open_packages)
        if bool(delivery_plan.get("ready_for_handoff")):
            action_package_status = "ready_for_customer_machine_handoff"
        elif any(package["gate_status"] == "critical" for package in open_packages):
            action_package_status = "blocked_by_critical_gate"
        elif open_packages:
            action_package_status = "operator_action_required"
        else:
            action_package_status = "all_delivery_actions_clear"

        return {
            "workspace_id": workspace_id,
            "action_package_status": action_package_status,
            "delivery_status": str(delivery_plan.get("delivery_status") or "unknown"),
            "acceptance_status": str(delivery_plan.get("acceptance_status") or "unknown"),
            "completion_percent": int(delivery_plan.get("completion_percent") or 0),
            "next_focus": str(delivery_plan.get("next_focus") or "create_or_import_operation_project"),
            "package_count": len(open_packages),
            "step_count": step_count,
            "immediate_package_count": len(immediate_action_packages),
            "gate_packages": gate_packages,
            "immediate_action_packages": immediate_action_packages,
            "delivery_plan": delivery_plan,
            "acceptance_gates": [
                "production_closed_loop_delivery_plan",
                "delivery_action_packages_are_derived_from_gates",
                "operator_confirmation_required_before_mutation",
                "customer_machine_executes_external_actions_only",
            ],
            "boundaries": [
                "delivery_action_packages_only_no_external_execution",
                "does_not_submit_comfyui_prompts",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "70W",
                "contract": "production_closed_loop_delivery_action_packages",
                "source_contract": "production_closed_loop_delivery_plan",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "limit": max(1, min(int(limit or 25), 50)),
                "scan_limit": max(max(1, int(limit or 25)), min(max(1, int(scan_limit or 50)), 100)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
                "server_read_only_no_openclaw_no_playwright_no_publish": True,
            },
        }

    async def get_production_closed_loop_delivery_remediation_map(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
    ) -> dict[str, Any]:
        """Map open delivery gates to the existing safe remediation workflows."""

        action_packages = await self.get_production_closed_loop_delivery_action_packages(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        evidence_records = await self.list_production_closed_loop_delivery_action_evidence(
            workspace_id=workspace_id,
            limit=200,
        )
        latest_evidence_by_gate: dict[str, dict[str, Any]] = {}
        for record in evidence_records.get("records", []):
            if not isinstance(record, dict):
                continue
            gate_key = str(record.get("gate_key") or "").strip()
            if gate_key and gate_key not in latest_evidence_by_gate:
                latest_evidence_by_gate[gate_key] = record

        remediations = [
            self._production_closed_loop_delivery_remediation(
                package=package,
                latest_evidence=latest_evidence_by_gate.get(str(package.get("gate_key") or "")),
            )
            for package in action_packages.get("gate_packages", [])
            if isinstance(package, dict) and str(package.get("gate_status") or "open") != "complete"
        ]
        immediate_keys = {
            str(package.get("gate_key") or "")
            for package in action_packages.get("immediate_action_packages", [])
            if isinstance(package, dict)
        }
        immediate_remediations = [
            remediation
            for remediation in remediations
            if str(remediation.get("gate_key") or "") in immediate_keys
        ]
        if str(action_packages.get("delivery_status") or "") == "ready_for_customer_machine_handoff":
            remediation_status = "ready_for_customer_machine_handoff"
        elif any(str(item.get("gate_status") or "") == "critical" for item in remediations):
            remediation_status = "blocked_by_critical_remediation"
        elif remediations:
            remediation_status = "operator_remediation_required"
        else:
            remediation_status = "all_remediations_clear"

        return {
            "workspace_id": workspace_id,
            "remediation_status": remediation_status,
            "delivery_status": str(action_packages.get("delivery_status") or "unknown"),
            "acceptance_status": str(action_packages.get("acceptance_status") or "unknown"),
            "completion_percent": int(action_packages.get("completion_percent") or 0),
            "next_focus": str(action_packages.get("next_focus") or "create_or_import_operation_project"),
            "remediation_count": len(remediations),
            "immediate_remediation_count": len(immediate_remediations),
            "remediations": remediations,
            "immediate_remediations": immediate_remediations,
            "action_packages": action_packages,
            "evidence_records": {
                "record_count": evidence_records.get("record_count", 0),
                "latest_record": evidence_records.get("latest_record"),
            },
            "acceptance_gates": [
                "production_closed_loop_delivery_action_packages",
                "production_closed_loop_delivery_action_evidence_list",
                "delivery_remediation_map_is_derived_from_current_gate_contracts",
                "operator_selects_and_executes_remediation_workflow",
            ],
            "boundaries": [
                "delivery_remediation_map_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_submit_comfyui_prompts",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "70Z",
                "contract": "production_closed_loop_delivery_remediation_map",
                "source_contract": "production_closed_loop_delivery_action_packages",
                "evidence_source_contract": "production_closed_loop_delivery_action_evidence_list",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "limit": max(1, min(int(limit or 25), 50)),
                "scan_limit": max(max(1, int(limit or 25)), min(max(1, int(scan_limit or 50)), 100)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
                "server_read_only_no_openclaw_no_playwright_no_publish": True,
            },
        }

    async def record_production_closed_loop_delivery_remediation_work_order(
        self,
        *,
        workspace_id: str,
        remediation_key: str | None = None,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        work_order_status: str = "in_progress",
        assignee: str | None = None,
        operator_confirmed: bool = False,
        evidence_links: list[dict[str, Any]] | None = None,
        work_summary: str | None = None,
        operator_notes: str | None = None,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Record operator ownership/status for a delivery remediation without executing it."""

        clean_remediation_key = str(remediation_key or "").strip() or None
        clean_gate_key = str(gate_key or "").strip() or None
        if not clean_remediation_key and not clean_gate_key:
            raise ValueError("remediation_key or gate_key is required")
        clean_status = str(work_order_status or "in_progress").strip().lower()
        allowed_statuses = {"assigned", "in_progress", "blocked", "completed", "needs_follow_up", "dismissed"}
        if clean_status not in allowed_statuses:
            raise ValueError("work_order_status must be assigned, in_progress, blocked, completed, needs_follow_up, or dismissed")
        clean_assignee = str(assignee or created_by or "").strip() or None
        if clean_status in {"assigned", "in_progress"} and not clean_assignee:
            raise ValueError("assignee is required for assigned or in_progress remediation work orders")
        if clean_status in {"assigned", "in_progress", "completed", "dismissed"} and not operator_confirmed:
            raise ValueError("operator_confirmed is required for assigned, in_progress, completed, or dismissed remediation work orders")
        clean_evidence_links = [dict(item) for item in evidence_links or [] if isinstance(item, dict)]
        clean_summary = str(work_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        if clean_status == "completed" and not clean_evidence_links and not clean_summary:
            raise ValueError("evidence_links or work_summary is required when completing a remediation work order")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "evidence_links": clean_evidence_links,
                "work_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"remediation work order payload contains sensitive key or value: {sensitive_paths[0]}")

        remediation_map = await self.get_production_closed_loop_delivery_remediation_map(
            workspace_id=workspace_id,
            platform=(metadata or {}).get("platform") if isinstance((metadata or {}).get("platform"), str) else None,
            force_metric_due=bool((metadata or {}).get("force_metric_due", False)),
        )
        remediation = next(
            (
                item
                for item in remediation_map.get("remediations", [])
                if isinstance(item, dict)
                and (
                    (clean_remediation_key and str(item.get("remediation_key") or "") == clean_remediation_key)
                    or (clean_gate_key and str(item.get("gate_key") or "") == clean_gate_key)
                )
            ),
            None,
        )
        if remediation is None:
            raise ValueError("remediation_key or gate_key is not present in the current delivery remediation map")

        clean_remediation_key = str(remediation.get("remediation_key") or clean_remediation_key or "")
        clean_gate_key = str(remediation.get("gate_key") or clean_gate_key or "")
        related_operation_ids = [
            str(item)
            for item in remediation.get("related_operation_ids", [])
            if str(item or "").strip()
        ]
        anchor_operation_id = operation_id
        if anchor_operation_id is None and related_operation_ids:
            anchor_operation_id = UUID(related_operation_ids[0])
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before recording remediation work orders")
            anchor_operation_id = operations[0].id
        if operation_id is not None and related_operation_ids and str(operation_id) not in related_operation_ids:
            raise ValueError("operation_id must match one of the remediation related_operation_ids")
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)

        now = datetime.now(UTC)
        record = self._json_safe_dict(
            {
                "work_order_id": str(uuid4()),
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "remediation_key": clean_remediation_key,
                "gate_key": clean_gate_key,
                "work_order_status": clean_status,
                "assignee": clean_assignee,
                "operator_confirmed": operator_confirmed,
                "target_console": str(remediation.get("target_console") or "server_operator_console"),
                "primary_endpoint": str(remediation.get("primary_endpoint") or "") or None,
                "completion_gate": str(remediation.get("completion_gate") or f"{clean_gate_key}_resolved"),
                "evidence_links": clean_evidence_links,
                "work_summary": clean_summary,
                "operator_notes": clean_notes,
                "contract_snapshot": {
                    "contract": "production_closed_loop_delivery_remediation_map",
                    "remediation_status": remediation_map.get("remediation_status"),
                    "delivery_status": remediation_map.get("delivery_status"),
                    "next_focus": remediation_map.get("next_focus"),
                    "remediation": {
                        "remediation_key": remediation.get("remediation_key"),
                        "gate_key": remediation.get("gate_key"),
                        "gate_status": remediation.get("gate_status"),
                        "title": remediation.get("title"),
                        "target_console": remediation.get("target_console"),
                        "primary_endpoint": remediation.get("primary_endpoint"),
                        "completion_gate": remediation.get("completion_gate"),
                        "expected_evidence": remediation.get("expected_evidence", []),
                        "existing_records_needed": remediation.get("existing_records_needed", []),
                    },
                },
                "boundary_checks": [
                    "delivery_remediation_map_contract_matched",
                    "server_side_external_execution_false",
                    "operator_approval_boundary_preserved",
                    "external_execution_not_performed",
                ],
                "created_by": created_by,
                "created_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "71A",
                    "contract": "production_closed_loop_delivery_remediation_work_order",
                    "source_contract": "production_closed_loop_delivery_remediation_map",
                    "workspace_gate_record": operation_id is None,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_remediation_work_order_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_bypass_operator_approval",
                ],
            }
        )

        operation_metadata = dict(operation.operation_metadata or {})
        history = self._production_closed_loop_delivery_remediation_work_order_history(operation)
        history = [*history, record][-100:]
        operation_metadata["production_closed_loop_delivery_remediation_work_orders"] = history
        operation_metadata["production_closed_loop_delivery_remediation_work_order_latest"] = record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)
        return record

    async def list_production_closed_loop_delivery_remediation_work_orders(
        self,
        *,
        workspace_id: str,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        work_order_status: str | None = None,
        limit: int = 50,
    ) -> dict[str, Any]:
        """List delivery remediation work-order records across a workspace."""

        clean_gate_key = str(gate_key or "").strip() or None
        clean_status = str(work_order_status or "").strip().lower() or None
        clean_limit = max(1, min(int(limit or 50), 200))
        if operation_id is not None:
            operations = [await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)]
        else:
            operations = await self.list_operations(workspace_id=workspace_id, limit=500)
        records: list[dict[str, Any]] = []
        for operation in operations:
            for record in self._production_closed_loop_delivery_remediation_work_order_history(operation):
                if clean_gate_key and str(record.get("gate_key") or "") != clean_gate_key:
                    continue
                if clean_status and str(record.get("work_order_status") or "").lower() != clean_status:
                    continue
                records.append(record)
        records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
        records = records[:clean_limit]
        latest_record = records[0] if records else None
        return {
            "workspace_id": workspace_id,
            "work_order_count": len(records),
            "latest_record": latest_record,
            "records": records,
            "acceptance_gates": [
                "production_closed_loop_delivery_remediation_map",
                "remediation_work_order_is_operator_supplied",
                "operator_confirmation_required_for_active_or_completed_status",
            ],
            "boundaries": [
                "delivery_remediation_work_order_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71A",
                "contract": "production_closed_loop_delivery_remediation_work_order_list",
                "source_contract": "production_closed_loop_delivery_remediation_work_order",
                "storage": "commercial_operations.operation_metadata.production_closed_loop_delivery_remediation_work_orders",
                "gate_filter": clean_gate_key,
                "operation_filter": str(operation_id) if operation_id else None,
                "status_filter": clean_status,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def _list_production_closed_loop_delivery_remediation_work_order_readiness_refresh_records(
        self,
        *,
        workspace_id: str,
        operation_id: UUID | None = None,
        limit: int = 500,
    ) -> list[dict[str, Any]]:
        """Return audited remediation work-order readiness refresh records across a workspace."""

        clean_limit = max(1, min(int(limit or 500), 500))
        if operation_id is not None:
            operations = [await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)]
        else:
            operations = await self.list_operations(workspace_id=workspace_id, limit=500)
        records: list[dict[str, Any]] = []
        for operation in operations:
            records.extend(
                self._production_closed_loop_delivery_remediation_work_order_readiness_refresh_history(operation)
            )
        records.sort(key=lambda item: str(item.get("refreshed_at") or ""), reverse=True)
        return records[:clean_limit]

    async def get_production_closed_loop_delivery_remediation_work_order_coverage(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
    ) -> dict[str, Any]:
        """Summarize which remediation items have operator work-order ownership."""

        remediation_map = await self.get_production_closed_loop_delivery_remediation_map(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        work_order_list = await self.list_production_closed_loop_delivery_remediation_work_orders(
            workspace_id=workspace_id,
            limit=work_order_limit,
        )
        work_orders = [item for item in work_order_list.get("records", []) if isinstance(item, dict)]
        readiness_refresh_records = (
            await self._list_production_closed_loop_delivery_remediation_work_order_readiness_refresh_records(
                workspace_id=workspace_id,
                limit=work_order_limit,
            )
        )

        def latest_readiness_refresh_for(
            *,
            latest_order: dict[str, Any] | None,
            remediation_key: str,
            gate_key: str,
        ) -> dict[str, Any] | None:
            if latest_order is None:
                return None
            work_order_id = str(latest_order.get("work_order_id") or "")
            work_order_created_at = str(latest_order.get("created_at") or "")
            for refresh_record in readiness_refresh_records:
                completed_work_order_ids = {
                    str(item)
                    for item in refresh_record.get("completed_work_order_ids", [])
                    if str(item or "").strip()
                }
                gate_keys = {
                    str(item)
                    for item in refresh_record.get("gate_keys", [])
                    if str(item or "").strip()
                }
                remediation_keys = {
                    str(item)
                    for item in refresh_record.get("remediation_keys", [])
                    if str(item or "").strip()
                }
                refreshed_at = str(refresh_record.get("refreshed_at") or "")
                if work_order_id and work_order_id in completed_work_order_ids:
                    return refresh_record
                if work_order_created_at and refreshed_at and refreshed_at < work_order_created_at:
                    continue
                if gate_key and gate_key in gate_keys:
                    return refresh_record
                if remediation_key and remediation_key in remediation_keys:
                    return refresh_record
            return None

        items: list[dict[str, Any]] = []
        unassigned_items: list[dict[str, Any]] = []
        in_progress_items: list[dict[str, Any]] = []
        work_ordered_count = 0
        in_progress_count = 0
        completed_count = 0
        readiness_refreshed_count = 0
        blocked_count = 0

        for remediation in remediation_map.get("remediations", []):
            if not isinstance(remediation, dict):
                continue
            remediation_key = str(remediation.get("remediation_key") or "")
            gate_key = str(remediation.get("gate_key") or "")
            matching_orders = [
                record
                for record in work_orders
                if str(record.get("remediation_key") or "") == remediation_key
                or str(record.get("gate_key") or "") == gate_key
            ]
            latest_order = matching_orders[0] if matching_orders else None
            latest_status = str(latest_order.get("work_order_status") or "").lower() if latest_order else None
            latest_readiness_refresh = latest_readiness_refresh_for(
                latest_order=latest_order,
                remediation_key=remediation_key,
                gate_key=gate_key,
            )
            gate_status = str(remediation.get("gate_status") or "open")
            work_order_required = gate_status != "complete"
            if not work_order_required:
                coverage_status = "gate_complete"
                next_action = "no_work_order_required"
            elif latest_order is None:
                coverage_status = "unassigned"
                next_action = f"assign_remediation_work_order:{gate_key}"
            elif latest_status in {"assigned", "in_progress"}:
                coverage_status = latest_status
                next_action = f"continue_remediation_work_order:{gate_key}"
            elif latest_status == "completed" and latest_readiness_refresh is not None:
                coverage_status = "completed_readiness_refreshed"
                next_action = str(
                    latest_readiness_refresh.get("next_action_key")
                    or f"review_refreshed_readiness:{gate_key}"
                )
            elif latest_status == "completed":
                coverage_status = "completed_pending_readiness_refresh"
                next_action = f"refresh_readiness_after_work_order:{gate_key}"
            elif latest_status in {"blocked", "needs_follow_up"}:
                coverage_status = latest_status
                next_action = f"resolve_blocked_remediation_work_order:{gate_key}"
            elif latest_status == "dismissed":
                coverage_status = "dismissed_needs_review"
                next_action = f"review_dismissed_remediation_work_order:{gate_key}"
            else:
                coverage_status = "unknown_work_order_status"
                next_action = f"review_remediation_work_order:{gate_key}"

            if latest_order is not None:
                work_ordered_count += 1
            if latest_status in {"assigned", "in_progress"}:
                in_progress_count += 1
            if latest_status == "completed":
                completed_count += 1
            if latest_status == "completed" and latest_readiness_refresh is not None:
                readiness_refreshed_count += 1
            if latest_status in {"blocked", "needs_follow_up"}:
                blocked_count += 1

            item = self._json_safe_dict(
                {
                    "remediation_key": remediation_key,
                    "gate_key": gate_key,
                    "gate_status": gate_status,
                    "title": str(remediation.get("title") or gate_key or remediation_key),
                    "owner": str(remediation.get("owner") or "operator"),
                    "priority": int(remediation.get("priority") or 0),
                    "target_console": str(remediation.get("target_console") or "server_operator_console"),
                    "coverage_status": coverage_status,
                    "work_order_required": work_order_required,
                    "work_order_count": len(matching_orders),
                    "latest_work_order_id": latest_order.get("work_order_id") if latest_order else None,
                    "latest_work_order_status": latest_status,
                    "latest_work_order_assignee": latest_order.get("assignee") if latest_order else None,
                    "latest_work_order_operator_confirmed": bool(latest_order.get("operator_confirmed")) if latest_order else False,
                    "latest_work_order_created_at": latest_order.get("created_at") if latest_order else None,
                    "latest_readiness_refresh_id": (
                        latest_readiness_refresh.get("refresh_id") if latest_readiness_refresh else None
                    ),
                    "latest_readiness_refresh_status": (
                        latest_readiness_refresh.get("refresh_status") if latest_readiness_refresh else None
                    ),
                    "latest_readiness_refresh_next_action": (
                        latest_readiness_refresh.get("next_action_key") if latest_readiness_refresh else None
                    ),
                    "current_evidence_status": str(remediation.get("current_evidence_status") or "no_evidence_record"),
                    "completion_gate": str(remediation.get("completion_gate") or f"{gate_key}_resolved"),
                    "next_action": next_action,
                    "blocking_reasons": [str(reason) for reason in remediation.get("blocking_reasons", [])],
                    "boundaries": [
                        "delivery_remediation_work_order_coverage_only_no_external_execution",
                        "does_not_execute_target_endpoint",
                        "operator_work_order_required_before_gate_mutation",
                    ],
                }
            )
            items.append(item)
            if coverage_status == "unassigned":
                unassigned_items.append(item)
            if latest_status in {"assigned", "in_progress"}:
                in_progress_items.append(item)

        remediation_count = len(items)
        unassigned_count = len(unassigned_items)
        coverage_percent = int(round((work_ordered_count / remediation_count) * 100)) if remediation_count else 100
        if remediation_count == 0:
            coverage_status = "all_remediations_clear"
            next_focus = "no_remediation_work_orders_required"
        elif unassigned_count:
            coverage_status = "remediation_ownership_required"
            next_focus = unassigned_items[0]["next_action"]
        elif blocked_count:
            coverage_status = "remediation_work_orders_blocked"
            next_focus = next(
                (item["next_action"] for item in items if item["coverage_status"] in {"blocked", "needs_follow_up"}),
                "resolve_blocked_remediation_work_orders",
            )
        elif in_progress_count:
            coverage_status = "remediation_work_orders_in_progress"
            next_focus = in_progress_items[0]["next_action"] if in_progress_items else "continue_remediation_work_orders"
        elif remediation_count and readiness_refreshed_count >= completed_count >= remediation_count:
            coverage_status = "remediation_work_orders_completed_readiness_refreshed"
            next_focus = "review_production_closed_loop_next_action"
        elif completed_count == remediation_count:
            coverage_status = "remediation_work_orders_completed_pending_readiness_refresh"
            next_focus = "refresh_production_closed_loop_readiness"
        else:
            coverage_status = "remediation_work_orders_tracked"
            next_focus = str(remediation_map.get("next_focus") or "review_remediation_work_order_coverage")

        return {
            "workspace_id": workspace_id,
            "coverage_status": coverage_status,
            "remediation_status": str(remediation_map.get("remediation_status") or "unknown"),
            "completion_percent": int(remediation_map.get("completion_percent") or 0),
            "coverage_percent": coverage_percent,
            "remediation_count": remediation_count,
            "work_ordered_count": work_ordered_count,
            "unassigned_count": unassigned_count,
            "in_progress_count": in_progress_count,
            "completed_count": completed_count,
            "readiness_refreshed_count": readiness_refreshed_count,
            "blocked_count": blocked_count,
            "next_focus": next_focus,
            "items": items,
            "unassigned_items": unassigned_items,
            "in_progress_items": in_progress_items,
            "acceptance_gates": [
                "production_closed_loop_delivery_remediation_map",
                "production_closed_loop_delivery_remediation_work_order_list",
                "every_open_remediation_has_operator_work_order",
                "completed_work_orders_require_readiness_refresh_or_gate_evidence",
            ],
            "boundaries": [
                "delivery_remediation_work_order_coverage_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71B",
                "contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "source_contract": "production_closed_loop_delivery_remediation_map",
                "work_order_source_contract": "production_closed_loop_delivery_remediation_work_order_list",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "limit": max(1, min(int(limit or 25), 50)),
                "scan_limit": max(max(1, int(limit or 25)), min(max(1, int(scan_limit or 50)), 100)),
                "work_order_limit": max(1, min(int(work_order_limit or 200), 500)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def assign_missing_production_closed_loop_delivery_remediation_work_orders(
        self,
        *,
        workspace_id: str,
        assignee: str,
        operator_confirmed: bool = False,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_summary: str | None = None,
        operator_notes: str | None = None,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Create assigned work orders for remediation coverage gaps without executing remediations."""

        clean_assignee = str(assignee or "").strip()
        if not clean_assignee:
            raise ValueError("assignee is required")
        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before assigning missing remediation work orders")
        clean_summary = str(work_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "assignee": clean_assignee,
                "work_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"remediation assignment payload contains sensitive key or value: {sensitive_paths[0]}")

        coverage_before = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        unassigned_items = [item for item in coverage_before.get("unassigned_items", []) if isinstance(item, dict)]
        records: list[dict[str, Any]] = []
        for item in unassigned_items:
            gate_key = str(item.get("gate_key") or "")
            record = await self.record_production_closed_loop_delivery_remediation_work_order(
                workspace_id=workspace_id,
                remediation_key=str(item.get("remediation_key") or "") or None,
                gate_key=gate_key or None,
                work_order_status="assigned",
                assignee=clean_assignee,
                operator_confirmed=True,
                work_summary=clean_summary or f"Remediation work order assigned for {gate_key}.",
                operator_notes=clean_notes or "Assigned from Phase 71C missing remediation work-order control.",
                created_by=created_by,
                metadata={
                    **(metadata or {}),
                    "source_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                    "assignment_phase": "71C",
                    "assignment_control": "assign_missing_remediation_work_orders",
                    "platform": platform,
                    "force_metric_due": force_metric_due,
                },
            )
            records.append(record)

        coverage_after = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        created_count = len(records)
        requested_count = len(unassigned_items)
        return {
            "workspace_id": workspace_id,
            "assignment_status": "missing_remediation_work_orders_assigned" if created_count else "no_missing_remediation_work_orders",
            "requested_count": requested_count,
            "created_count": created_count,
            "skipped_count": max(0, requested_count - created_count),
            "assignee": clean_assignee,
            "records": records,
            "coverage_after": coverage_after,
            "acceptance_gates": [
                "production_closed_loop_delivery_remediation_work_order_coverage",
                "operator_confirmation_required_before_assignment",
                "assigned_work_orders_are_metadata_records_only",
                "remediation_execution_requires_separate_approved_workflow",
            ],
            "boundaries": [
                "delivery_remediation_work_order_assignment_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71C",
                "contract": "production_closed_loop_delivery_remediation_work_order_assignment",
                "source_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "record_contract": "production_closed_loop_delivery_remediation_work_order",
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def get_production_closed_loop_delivery_remediation_work_order_execution_prep(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
    ) -> dict[str, Any]:
        """Build read-only execution-prep packages for delivery remediation work orders."""

        remediation_map = await self.get_production_closed_loop_delivery_remediation_map(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        coverage = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        work_order_list = await self.list_production_closed_loop_delivery_remediation_work_orders(
            workspace_id=workspace_id,
            limit=work_order_limit,
        )
        work_orders = [record for record in work_order_list.get("records", []) if isinstance(record, dict)]
        remediations = [item for item in remediation_map.get("remediations", []) if isinstance(item, dict)]
        remediation_by_key = {
            str(item.get("remediation_key") or ""): item
            for item in remediations
            if str(item.get("remediation_key") or "").strip()
        }
        remediation_by_gate = {
            str(item.get("gate_key") or ""): item
            for item in remediations
            if str(item.get("gate_key") or "").strip()
        }

        items: list[dict[str, Any]] = []
        ready_items: list[dict[str, Any]] = []
        waiting_assignment_items: list[dict[str, Any]] = []
        blocked_count = 0
        completed_count = 0
        readiness_refreshed_count = 0
        customer_machine_count = 0
        server_operator_count = 0

        for coverage_item in coverage.get("items", []):
            if not isinstance(coverage_item, dict):
                continue
            remediation_key = str(coverage_item.get("remediation_key") or "")
            gate_key = str(coverage_item.get("gate_key") or "")
            remediation = remediation_by_key.get(remediation_key) or remediation_by_gate.get(gate_key) or {}
            matching_orders = [
                record
                for record in work_orders
                if str(record.get("remediation_key") or "") == remediation_key
                or str(record.get("gate_key") or "") == gate_key
            ]
            latest_order = matching_orders[0] if matching_orders else None
            latest_status = str(latest_order.get("work_order_status") or "").lower() if latest_order else None
            latest_readiness_refresh_id = str(coverage_item.get("latest_readiness_refresh_id") or "") or None
            latest_readiness_refresh_status = (
                str(coverage_item.get("latest_readiness_refresh_status") or "") or None
            )
            latest_readiness_refresh_next_action = (
                str(coverage_item.get("latest_readiness_refresh_next_action") or "") or None
            )
            work_order_required = bool(coverage_item.get("work_order_required", True))
            target_console = str(remediation.get("target_console") or coverage_item.get("target_console") or "server_operator_console")
            target_method = str(remediation.get("primary_method") or "GET")
            target_endpoint = str(remediation.get("primary_endpoint") or coverage_item.get("primary_endpoint") or "") or None
            completion_gate = str(remediation.get("completion_gate") or coverage_item.get("completion_gate") or f"{gate_key}_resolved")
            related_operation_ids = [
                str(item)
                for item in remediation.get("related_operation_ids", [])
                if str(item or "").strip()
            ]
            operation_id = (
                str(latest_order.get("operation_id"))
                if latest_order and latest_order.get("operation_id")
                else related_operation_ids[0]
                if related_operation_ids
                else None
            )
            requires_customer_machine = bool(remediation.get("can_be_started_from_customer_machine")) or target_console in {
                "customer_machine_console",
                "technical_operator_console",
            }
            requires_server_operator = bool(remediation.get("can_be_started_from_server")) or target_console == "server_operator_console"
            latest_operator_confirmed = bool(latest_order.get("operator_confirmed")) if latest_order else False

            if not work_order_required:
                prep_status = "gate_complete_no_execution_required"
                next_action = "no_remediation_execution_required"
            elif latest_order is None:
                prep_status = "waiting_for_assignment"
                next_action = f"assign_remediation_work_order:{gate_key}"
            elif latest_status in {"assigned", "in_progress"} and latest_operator_confirmed:
                prep_status = "ready_for_operator_execution_review"
                next_action = f"review_remediation_execution_prep:{gate_key}"
            elif latest_status in {"assigned", "in_progress"}:
                prep_status = "assigned_requires_operator_confirmation"
                next_action = f"confirm_remediation_work_order:{gate_key}"
            elif latest_status == "completed" and latest_readiness_refresh_id:
                prep_status = "completed_readiness_refreshed"
                next_action = latest_readiness_refresh_next_action or f"review_refreshed_readiness:{gate_key}"
            elif latest_status == "completed":
                prep_status = "completed_pending_readiness_refresh"
                next_action = f"refresh_readiness_after_work_order:{gate_key}"
            elif latest_status in {"blocked", "needs_follow_up"}:
                prep_status = "blocked_needs_follow_up"
                next_action = f"resolve_blocked_remediation_work_order:{gate_key}"
            elif latest_status == "dismissed":
                prep_status = "dismissed_needs_review"
                next_action = f"review_dismissed_remediation_work_order:{gate_key}"
            else:
                prep_status = "unknown_work_order_status"
                next_action = f"review_remediation_work_order:{gate_key}"

            expected_evidence = [
                str(item)
                for item in remediation.get("expected_evidence", [])
                if str(item or "").strip()
            ]
            existing_records_needed = [
                str(item)
                for item in remediation.get("existing_records_needed", [])
                if str(item or "").strip()
            ]
            recommended_sequence = [
                str(item)
                for item in remediation.get("recommended_sequence", [])
                if str(item or "").strip()
            ]
            evidence_requirements = self._dedupe_texts(
                [
                    *expected_evidence,
                    f"completion gate: {completion_gate}",
                    "latest remediation work-order summary or evidence links",
                ]
            )
            prerequisites = self._dedupe_texts(
                [
                    *existing_records_needed,
                    "assigned remediation work order",
                    "operator confirmation before any mutating follow-up",
                ]
            )
            operator_checklist = self._dedupe_texts(
                [
                    "Open the target console and verify the current gate state.",
                    *recommended_sequence,
                    "Prepare evidence before requesting readiness refresh.",
                    "Submit or link evidence through the approved delivery evidence path.",
                    "Do not execute external automation from this preparation endpoint.",
                ]
                + (["Assign this remediation before execution review."] if latest_order is None else [])
                + (["Resolve the blocked work-order status before execution review."] if prep_status == "blocked_needs_follow_up" else [])
            )
            boundary_checks = [
                "delivery_remediation_map_contract_matched",
                "work_order_coverage_contract_matched",
                "server_side_external_execution_false",
                "external_execution_not_performed",
                "operator_approval_boundary_preserved",
            ]
            item = self._json_safe_dict(
                {
                    "prep_key": f"execution_prep:{gate_key}",
                    "remediation_key": remediation_key,
                    "gate_key": gate_key,
                    "gate_status": str(coverage_item.get("gate_status") or remediation.get("gate_status") or "open"),
                    "title": str(remediation.get("title") or coverage_item.get("title") or gate_key or remediation_key),
                    "owner": str(remediation.get("owner") or coverage_item.get("owner") or "operator"),
                    "priority": int(remediation.get("priority") or coverage_item.get("priority") or 0),
                    "operation_id": operation_id,
                    "prep_status": prep_status,
                    "coverage_status": str(coverage_item.get("coverage_status") or "unknown"),
                    "work_order_required": work_order_required,
                    "work_order_count": len(matching_orders),
                    "latest_work_order_id": latest_order.get("work_order_id") if latest_order else None,
                    "latest_work_order_status": latest_status,
                    "latest_work_order_assignee": latest_order.get("assignee") if latest_order else None,
                    "latest_work_order_operator_confirmed": latest_operator_confirmed,
                    "latest_work_order": latest_order,
                    "latest_readiness_refresh_id": latest_readiness_refresh_id,
                    "latest_readiness_refresh_status": latest_readiness_refresh_status,
                    "latest_readiness_refresh_next_action": latest_readiness_refresh_next_action,
                    "target_console": target_console,
                    "target_method": target_method,
                    "target_endpoint": target_endpoint,
                    "completion_gate": completion_gate,
                    "source_action_key": remediation.get("source_action_key"),
                    "current_evidence_status": str(
                        remediation.get("current_evidence_status")
                        or coverage_item.get("current_evidence_status")
                        or "no_evidence_record"
                    ),
                    "requires_customer_machine": requires_customer_machine,
                    "requires_server_operator": requires_server_operator,
                    "operator_approval_required": True,
                    "operator_confirmed": latest_operator_confirmed,
                    "external_execution_allowed": False,
                    "server_side_external_execution": False,
                    "evidence_requirements": evidence_requirements,
                    "prerequisites": prerequisites,
                    "operator_checklist": operator_checklist,
                    "execution_payload_template": {
                        "remediation_key": remediation_key,
                        "gate_key": gate_key,
                        "operation_id": operation_id,
                        "work_order_id": latest_order.get("work_order_id") if latest_order else None,
                        "target_method": target_method,
                        "target_endpoint": target_endpoint,
                        "completion_gate": completion_gate,
                        "operator_confirmed": False,
                        "evidence_links": [],
                        "notes": "Fill after approved manual execution; this endpoint does not submit or execute the payload.",
                    },
                    "runbook_references": [
                        str(item)
                        for item in remediation.get("runbook_references", [])
                        if str(item or "").strip()
                    ],
                    "guardrails": self._dedupe_texts(
                        [
                            *[
                                str(item)
                                for item in remediation.get("guardrails", [])
                                if str(item or "").strip()
                            ],
                            "delivery_remediation_work_order_execution_prep_only_no_external_execution",
                            "does_not_execute_target_endpoint",
                            "does_not_run_openclaw_or_playwright_on_server",
                            "does_not_submit_comfyui_prompt",
                        ]
                    ),
                    "blocking_reasons": [
                        str(reason)
                        for reason in remediation.get("blocking_reasons", coverage_item.get("blocking_reasons", []))
                        if str(reason or "").strip()
                    ],
                    "next_action": next_action,
                    "boundary_checks": boundary_checks,
                    "boundaries": [
                        "delivery_remediation_work_order_execution_prep_only_no_external_execution",
                        "does_not_execute_target_endpoint",
                        "does_not_run_openclaw_or_playwright_on_server",
                        "does_not_publish_or_control_real_accounts",
                        "does_not_submit_comfyui_prompt",
                        "does_not_bypass_operator_approval",
                    ],
                    "metadata": {
                        "phase": "71D",
                        "contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                        "source_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                        "remediation_map_contract": "production_closed_loop_delivery_remediation_map",
                        "work_order_source_contract": "production_closed_loop_delivery_remediation_work_order_list",
                        "server_side_external_execution": False,
                        "actual_publish_performed": False,
                    },
                }
            )
            items.append(item)
            if prep_status == "ready_for_operator_execution_review":
                ready_items.append(item)
            if prep_status == "waiting_for_assignment":
                waiting_assignment_items.append(item)
            if prep_status in {"blocked_needs_follow_up", "dismissed_needs_review"}:
                blocked_count += 1
            if prep_status == "completed_pending_readiness_refresh":
                completed_count += 1
            if prep_status == "completed_readiness_refreshed":
                completed_count += 1
                readiness_refreshed_count += 1
            if requires_customer_machine:
                customer_machine_count += 1
            if requires_server_operator:
                server_operator_count += 1

        prep_count = len(items)
        ready_count = len(ready_items)
        waiting_assignment_count = len(waiting_assignment_items)
        if prep_count == 0:
            prep_status = "all_remediations_clear"
            next_focus = "no_remediation_execution_prep_required"
        elif waiting_assignment_count:
            prep_status = "execution_prep_waiting_for_assignment"
            next_focus = waiting_assignment_items[0]["next_action"]
        elif blocked_count:
            prep_status = "execution_prep_blocked"
            next_focus = next(
                (item["next_action"] for item in items if item["prep_status"] in {"blocked_needs_follow_up", "dismissed_needs_review"}),
                "resolve_blocked_remediation_work_orders",
            )
        elif ready_count:
            prep_status = "execution_prep_ready_for_operator_review"
            next_focus = ready_items[0]["next_action"]
        elif prep_count and readiness_refreshed_count >= completed_count >= prep_count:
            prep_status = "execution_prep_completed_readiness_refreshed"
            next_focus = "review_production_closed_loop_next_action"
        elif completed_count == prep_count:
            prep_status = "execution_prep_completed_pending_readiness_refresh"
            next_focus = "refresh_production_closed_loop_readiness"
        else:
            prep_status = "execution_prep_tracked"
            next_focus = str(coverage.get("next_focus") or "review_remediation_execution_prep")

        return {
            "workspace_id": workspace_id,
            "prep_status": prep_status,
            "coverage_status": str(coverage.get("coverage_status") or "unknown"),
            "remediation_status": str(remediation_map.get("remediation_status") or "unknown"),
            "completion_percent": int(remediation_map.get("completion_percent") or 0),
            "coverage_percent": int(coverage.get("coverage_percent") or 0),
            "remediation_count": int(coverage.get("remediation_count") or len(items)),
            "prep_count": prep_count,
            "ready_count": ready_count,
            "waiting_assignment_count": waiting_assignment_count,
            "blocked_count": blocked_count,
            "completed_count": completed_count,
            "readiness_refreshed_count": readiness_refreshed_count,
            "customer_machine_count": customer_machine_count,
            "server_operator_count": server_operator_count,
            "next_focus": next_focus,
            "items": items,
            "ready_items": ready_items,
            "waiting_assignment_items": waiting_assignment_items,
            "acceptance_gates": [
                "production_closed_loop_delivery_remediation_work_order_coverage",
                "assigned_work_order_required_before_execution_review",
                "operator_confirmation_required_before_mutating_follow_up",
                "evidence_requirements_present_before_readiness_refresh",
            ],
            "boundaries": [
                "delivery_remediation_work_order_execution_prep_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71D",
                "contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "source_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "remediation_map_contract": "production_closed_loop_delivery_remediation_map",
                "work_order_source_contract": "production_closed_loop_delivery_remediation_work_order_list",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "limit": max(1, min(int(limit or 25), 50)),
                "scan_limit": max(max(1, int(limit or 25)), min(max(1, int(scan_limit or 50)), 100)),
                "work_order_limit": max(1, min(int(work_order_limit or 200), 500)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def complete_production_closed_loop_delivery_remediation_work_order(
        self,
        *,
        workspace_id: str,
        work_order_id: UUID | None = None,
        remediation_key: str | None = None,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        completed_by: str | None = None,
        operator_confirmed: bool = False,
        evidence_links: list[dict[str, Any]] | None = None,
        completion_summary: str | None = None,
        operator_notes: str | None = None,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Complete an assigned remediation work order from execution prep without running target endpoints."""

        clean_work_order_id = str(work_order_id) if work_order_id else None
        clean_remediation_key = str(remediation_key or "").strip() or None
        clean_gate_key = str(gate_key or "").strip() or None
        if not clean_work_order_id and not clean_remediation_key and not clean_gate_key:
            raise ValueError("work_order_id, remediation_key, or gate_key is required")
        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before completing a remediation work order")
        clean_evidence_links = [dict(item) for item in evidence_links or [] if isinstance(item, dict)]
        clean_summary = str(completion_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        if not clean_evidence_links and not clean_summary:
            raise ValueError("evidence_links or completion_summary is required before completing a remediation work order")
        clean_completed_by = str(completed_by or created_by or "").strip() or None
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "work_order_id": clean_work_order_id,
                "remediation_key": clean_remediation_key,
                "gate_key": clean_gate_key,
                "completed_by": clean_completed_by,
                "evidence_links": clean_evidence_links,
                "completion_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"remediation work-order completion payload contains sensitive key or value: {sensitive_paths[0]}")

        prep_before = await self.get_production_closed_loop_delivery_remediation_work_order_execution_prep(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        prep_items = [item for item in prep_before.get("items", []) if isinstance(item, dict)]
        matched_prep = next(
            (
                item
                for item in prep_items
                if (
                    clean_work_order_id
                    and str(item.get("latest_work_order_id") or "") == clean_work_order_id
                )
                or (
                    clean_remediation_key
                    and str(item.get("remediation_key") or "") == clean_remediation_key
                )
                or (clean_gate_key and str(item.get("gate_key") or "") == clean_gate_key)
            ),
            None,
        )
        if matched_prep is None:
            raise ValueError("matching remediation execution prep item was not found")
        latest_order = matched_prep.get("latest_work_order") if isinstance(matched_prep.get("latest_work_order"), dict) else None
        if latest_order is None:
            raise ValueError("assigned remediation work order is required before completion")
        latest_status = str(latest_order.get("work_order_status") or "").lower()
        if latest_status not in {"assigned", "in_progress"}:
            raise ValueError("only assigned or in_progress remediation work orders can be completed from execution prep")
        prep_status = str(matched_prep.get("prep_status") or "")
        if prep_status != "ready_for_operator_execution_review":
            raise ValueError("remediation work order must be ready_for_operator_execution_review before completion")

        anchor_operation_id = operation_id
        if anchor_operation_id is None and matched_prep.get("operation_id"):
            anchor_operation_id = UUID(str(matched_prep.get("operation_id")))
        completed_record = await self.record_production_closed_loop_delivery_remediation_work_order(
            workspace_id=workspace_id,
            remediation_key=str(matched_prep.get("remediation_key") or clean_remediation_key or "") or None,
            gate_key=str(matched_prep.get("gate_key") or clean_gate_key or "") or None,
            operation_id=anchor_operation_id,
            work_order_status="completed",
            assignee=clean_completed_by or str(latest_order.get("assignee") or "") or None,
            operator_confirmed=True,
            evidence_links=clean_evidence_links,
            work_summary=clean_summary or f"Completed remediation work order for {matched_prep.get('gate_key')}.",
            operator_notes=clean_notes or "Completed from Phase 71E remediation execution-prep completion control.",
            created_by=created_by,
            metadata={
                **(metadata or {}),
                "source_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "completion_phase": "71E",
                "completion_control": "complete_remediation_work_order_from_execution_prep",
                "previous_work_order_id": str(latest_order.get("work_order_id") or ""),
                "previous_work_order_status": latest_status,
                "platform": platform,
                "force_metric_due": force_metric_due,
            },
        )
        coverage_after = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        execution_prep_after = await self.get_production_closed_loop_delivery_remediation_work_order_execution_prep(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        gate = str(completed_record.get("gate_key") or matched_prep.get("gate_key") or clean_gate_key or "")
        completed_count = int(coverage_after.get("completed_count") or 0)
        remediation_count = int(coverage_after.get("remediation_count") or 0)
        completion_status = (
            "all_remediation_work_orders_completed_pending_readiness_refresh"
            if remediation_count and completed_count >= remediation_count
            else "remediation_work_order_completed_pending_readiness_refresh"
        )
        return {
            "workspace_id": workspace_id,
            "completion_status": completion_status,
            "completed_record": completed_record,
            "coverage_after": coverage_after,
            "execution_prep_after": execution_prep_after,
            "readiness_refresh_required": True,
            "readiness_refresh_next_action": f"refresh_readiness_after_work_order:{gate}",
            "acceptance_gates": [
                "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "operator_confirmation_required_before_completion",
                "completion_evidence_required_before_work_order_close",
                "completed_work_order_requires_readiness_refresh",
            ],
            "boundaries": [
                "delivery_remediation_work_order_completion_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71E",
                "contract": "production_closed_loop_delivery_remediation_work_order_completion",
                "source_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "record_contract": "production_closed_loop_delivery_remediation_work_order",
                "coverage_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "execution_prep_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def refresh_production_closed_loop_delivery_remediation_work_order_readiness(
        self,
        *,
        workspace_id: str,
        operation_id: UUID | None = None,
        remediation_key: str | None = None,
        gate_key: str | None = None,
        platform: str | None = None,
        force_metric_due: bool = False,
        operator_confirmed: bool = False,
        refresh_notes: str | None = None,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        refreshed_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Audit a readiness refresh after completed remediation work orders."""

        clean_remediation_key = str(remediation_key or "").strip() or None
        clean_gate_key = str(gate_key or "").strip() or None
        clean_notes = str(refresh_notes or "").strip() or None
        clean_refreshed_by = str(refreshed_by or "").strip() or None
        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before refreshing remediation work-order readiness")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "operation_id": str(operation_id) if operation_id else None,
                "remediation_key": clean_remediation_key,
                "gate_key": clean_gate_key,
                "refresh_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"remediation readiness refresh payload contains sensitive key or value: {sensitive_paths[0]}")

        execution_prep_before = await self.get_production_closed_loop_delivery_remediation_work_order_execution_prep(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        completed_items: list[dict[str, Any]] = []
        for item in execution_prep_before.get("items", []):
            if not isinstance(item, dict):
                continue
            if str(item.get("prep_status") or "") != "completed_pending_readiness_refresh":
                continue
            if clean_remediation_key and str(item.get("remediation_key") or "") != clean_remediation_key:
                continue
            if clean_gate_key and str(item.get("gate_key") or "") != clean_gate_key:
                continue
            if operation_id and str(item.get("operation_id") or "") != str(operation_id):
                continue
            completed_items.append(item)
        if not completed_items:
            raise ValueError("completed remediation work order is required before readiness refresh")

        anchor_operation_id = operation_id
        if anchor_operation_id is None:
            for item in completed_items:
                raw_operation_id = item.get("operation_id")
                if not raw_operation_id and isinstance(item.get("latest_work_order"), dict):
                    raw_operation_id = item["latest_work_order"].get("operation_id")
                if raw_operation_id:
                    try:
                        anchor_operation_id = raw_operation_id if isinstance(raw_operation_id, UUID) else UUID(str(raw_operation_id))
                        break
                    except ValueError:
                        continue
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before refreshing remediation work-order readiness")
            anchor_operation_id = operations[0].id

        readiness = await self.get_production_closed_loop_readiness(
            workspace_id=workspace_id,
            operation_id=anchor_operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        next_action = await self.get_production_closed_loop_next_action(
            workspace_id=workspace_id,
            operation_id=anchor_operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        selected_action_key = str(next_action.get("selected_action_key") or readiness.get("next_action") or "")
        readiness_status = str(readiness.get("readiness_status") or "unknown")
        current_stage_key = str(readiness.get("current_stage_key") or "") or None
        current_stage_status = None
        for stage in readiness.get("stages", []):
            if isinstance(stage, dict) and str(stage.get("stage_key") or "") == str(current_stage_key or ""):
                current_stage_status = str(stage.get("status") or "") or None
                break

        now = datetime.now(UTC)
        refresh_id = str(uuid4())
        work_order_ids = self._dedupe_texts(
            [
                str(item.get("latest_work_order_id") or "")
                for item in completed_items
                if str(item.get("latest_work_order_id") or "").strip()
            ]
        )
        remediation_keys = self._dedupe_texts(
            [
                str(item.get("remediation_key") or "")
                for item in completed_items
                if str(item.get("remediation_key") or "").strip()
            ]
        )
        gate_keys = self._dedupe_texts(
            [
                str(item.get("gate_key") or "")
                for item in completed_items
                if str(item.get("gate_key") or "").strip()
            ]
        )
        initial_completed_count = int(execution_prep_before.get("completed_count") or 0)
        initial_prep_count = int(execution_prep_before.get("prep_count") or 0)
        initial_refresh_status = (
            "all_remediation_work_orders_completed_readiness_refreshed"
            if initial_prep_count and initial_completed_count >= initial_prep_count and len(completed_items) >= initial_prep_count
            else "completed_remediation_work_order_readiness_refreshed"
        )
        refresh_record = self._json_safe_dict(
            {
                "refresh_id": refresh_id,
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "remediation_key": clean_remediation_key,
                "gate_key": clean_gate_key,
                "completed_work_order_ids": work_order_ids,
                "remediation_keys": remediation_keys,
                "gate_keys": gate_keys,
                "refresh_status": initial_refresh_status,
                "readiness_status": readiness_status,
                "current_stage_key": current_stage_key,
                "current_stage_status": current_stage_status,
                "next_action_key": selected_action_key,
                "operator_confirmed": True,
                "refresh_notes": clean_notes,
                "refreshed_by": clean_refreshed_by,
                "refreshed_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "71F",
                    "contract": "production_closed_loop_delivery_remediation_work_order_readiness_refresh",
                    "source_contract": "production_closed_loop_delivery_remediation_work_order_completion",
                    "readiness_contract": "production_closed_loop_e2e_readiness",
                    "next_action_contract": "production_closed_loop_next_action",
                    "platform": platform,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_remediation_work_order_readiness_refresh_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_bypass_operator_approval",
                ],
            }
        )
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)
        operation_metadata = dict(operation.operation_metadata or {})
        refresh_history = self._production_closed_loop_delivery_remediation_work_order_readiness_refresh_history(operation)
        refresh_history = [*refresh_history, refresh_record][-100:]
        operation_metadata["production_closed_loop_delivery_remediation_work_order_readiness_refreshes"] = refresh_history
        operation_metadata["production_closed_loop_delivery_remediation_work_order_readiness_refresh_latest"] = refresh_record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)

        coverage_after = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        execution_prep_after = await self.get_production_closed_loop_delivery_remediation_work_order_execution_prep(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        completed_count = int(coverage_after.get("completed_count") or 0)
        remediation_count = int(coverage_after.get("remediation_count") or 0)
        readiness_refreshed_count = int(coverage_after.get("readiness_refreshed_count") or 0)
        refresh_status = (
            "all_remediation_work_orders_completed_readiness_refreshed"
            if remediation_count and readiness_refreshed_count >= completed_count >= remediation_count
            else "completed_remediation_work_order_readiness_refreshed"
        )
        refresh_record["refresh_status"] = refresh_status
        return self._json_safe_dict(
            {
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "refresh_id": refresh_id,
                "refresh_status": refresh_status,
                "coverage_status": str(coverage_after.get("coverage_status") or "unknown"),
                "execution_prep_status": str(execution_prep_after.get("prep_status") or "unknown"),
                "readiness_status": readiness_status,
                "current_stage_key": current_stage_key,
                "current_stage_status": current_stage_status,
                "next_action_key": selected_action_key,
                "completed_work_order_count": len(completed_items),
                "readiness_refreshed_count": readiness_refreshed_count,
                "completed_items": completed_items,
                "coverage_after": coverage_after,
                "execution_prep_after": execution_prep_after,
                "readiness": readiness,
                "next_action": next_action,
                "refresh_record": refresh_record,
                "readiness_refresh_required": False,
                "operator_confirmed": True,
                "refresh_notes": clean_notes,
                "acceptance_gates": [
                    "production_closed_loop_delivery_remediation_work_order_completion",
                    "completed_remediation_work_order_required_before_refresh",
                    "operator_confirmation_required_before_readiness_refresh",
                    "readiness_refresh_uses_current_production_closed_loop_readiness",
                    "next_action_recomputed_after_completion",
                ],
                "boundaries": [
                    "delivery_remediation_work_order_readiness_refresh_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_bypass_operator_approval",
                ],
                "generated_at": now,
                "metadata": {
                    "phase": "71F",
                    "contract": "production_closed_loop_delivery_remediation_work_order_readiness_refresh",
                    "source_contract": "production_closed_loop_delivery_remediation_work_order_completion",
                    "coverage_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                    "execution_prep_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                    "readiness_contract": "production_closed_loop_e2e_readiness",
                    "next_action_contract": "production_closed_loop_next_action",
                    "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
            }
        )

    async def get_production_closed_loop_delivery_audit_blocker_clearance_plan(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
    ) -> dict[str, Any]:
        """Translate production delivery audit blockers into operator-clearance work."""

        settings = get_settings()
        config_findings = settings.production_config_findings(require_production=True)
        acceptance_summary = await self.get_production_closed_loop_acceptance_summary(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        remediation_map = await self.get_production_closed_loop_delivery_remediation_map(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        coverage = await self.get_production_closed_loop_delivery_remediation_work_order_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        execution_prep = await self.get_production_closed_loop_delivery_remediation_work_order_execution_prep(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        remediations = [item for item in remediation_map.get("remediations", []) if isinstance(item, dict)]
        remediation_by_gate = {
            str(item.get("gate_key") or ""): item
            for item in remediations
            if str(item.get("gate_key") or "").strip()
        }
        coverage_by_gate = {
            str(item.get("gate_key") or ""): item
            for item in coverage.get("items", [])
            if isinstance(item, dict) and str(item.get("gate_key") or "").strip()
        }
        prep_by_gate = {
            str(item.get("gate_key") or ""): item
            for item in execution_prep.get("items", [])
            if isinstance(item, dict) and str(item.get("gate_key") or "").strip()
        }

        def blocker_gate_key(source: str, key: str) -> str | None:
            clean_key = key.strip()
            if "openclaw" in clean_key.lower():
                return "configure_real_openclaw_publish_provider"
            if source == "remaining_gate":
                return clean_key
            if source == "operation_blocker":
                return "close_operation_readiness_gaps"
            if source == "production_config":
                return "close_operation_readiness_gaps"
            return None

        def blocker_title(source: str, key: str) -> str:
            if source == "production_config":
                return f"Production config finding: {key}"
            if source == "remaining_gate":
                return f"Remaining acceptance gate: {key}"
            if source == "operation_blocker":
                return f"Operation blocker: {key}"
            if source == "openclaw_provider":
                return f"OpenClaw provider blocker: {key}"
            return key

        blocker_items: list[dict[str, Any]] = []
        seen_blockers: set[str] = set()

        def add_blocker(
            *,
            source: str,
            key: str,
            severity: str = "error",
            message: str | None = None,
            operation_id: str | None = None,
            operation_title: str | None = None,
            expected: str | None = None,
            actual: str | None = None,
        ) -> None:
            clean_key = str(key or "").strip()
            if not clean_key:
                return
            blocker_key = f"{source}:{clean_key}"
            if blocker_key in seen_blockers:
                return
            seen_blockers.add(blocker_key)
            gate_key = blocker_gate_key(source, clean_key)
            remediation = remediation_by_gate.get(gate_key or "") if gate_key else None
            coverage_item = coverage_by_gate.get(gate_key or "") if gate_key else None
            prep_item = prep_by_gate.get(gate_key or "") if gate_key else None
            target_console = str(
                (remediation or {}).get("target_console")
                or (coverage_item or {}).get("target_console")
                or (prep_item or {}).get("target_console")
                or ("technical_operator_console" if "openclaw" in clean_key.lower() else "server_operator_console")
            )
            current_state = str(
                (prep_item or {}).get("prep_status")
                or (coverage_item or {}).get("coverage_status")
                or "not_mapped_to_work_order"
            )
            next_action = str(
                (prep_item or {}).get("next_action")
                or (coverage_item or {}).get("next_action")
                or (remediation or {}).get("next_action")
                or ("configure_real_openclaw_provider_in_environment" if "openclaw" in clean_key.lower() else "review_production_closed_loop_next_action")
            )
            external_dependency_required = source in {"production_config", "openclaw_provider"} or "openclaw" in clean_key.lower()
            item = self._json_safe_dict(
                {
                    "blocker_key": blocker_key,
                    "source": source,
                    "severity": severity,
                    "title": blocker_title(source, clean_key),
                    "message": message or blocker_title(source, clean_key),
                    "operation_id": operation_id,
                    "operation_title": operation_title,
                    "gate_key": gate_key,
                    "remediation_key": (remediation or {}).get("remediation_key"),
                    "target_console": target_console,
                    "target_endpoint": (remediation or {}).get("primary_endpoint") or (prep_item or {}).get("target_endpoint"),
                    "owner": (remediation or {}).get("owner") or "operator",
                    "priority": int((remediation or {}).get("priority") or (2 if severity == "error" else 1)),
                    "current_state": current_state,
                    "coverage_status": (coverage_item or {}).get("coverage_status"),
                    "prep_status": (prep_item or {}).get("prep_status"),
                    "latest_work_order_id": (prep_item or coverage_item or {}).get("latest_work_order_id"),
                    "latest_work_order_status": (prep_item or coverage_item or {}).get("latest_work_order_status"),
                    "latest_readiness_refresh_status": (prep_item or coverage_item or {}).get("latest_readiness_refresh_status"),
                    "recommended_action": next_action,
                    "expected": expected,
                    "actual": actual,
                    "can_be_resolved_by_ui": not external_dependency_required,
                    "external_dependency_required": external_dependency_required,
                    "operator_approval_required": True,
                    "runbook_references": self._dedupe_texts(
                        [
                            *[
                                str(item)
                                for item in (remediation or {}).get("runbook_references", [])
                                if str(item or "").strip()
                            ],
                            "scripts/check_production_closed_loop.py",
                            "scripts/check_production_config.py" if source == "production_config" else "",
                            "scripts/check_openclaw_provider.py" if "openclaw" in clean_key.lower() else "",
                        ]
                    ),
                    "boundaries": [
                        "delivery_audit_blocker_clearance_plan_only_no_external_execution",
                        "does_not_execute_target_endpoint",
                        "does_not_run_openclaw_or_playwright_on_server",
                        "does_not_publish_or_control_real_accounts",
                        "does_not_submit_comfyui_prompt",
                        "does_not_bypass_operator_approval",
                    ],
                }
            )
            blocker_items.append(item)

        for finding in config_findings:
            if not isinstance(finding, dict) or str(finding.get("severity") or "") != "error":
                continue
            add_blocker(
                source="production_config",
                key=str(finding.get("key") or "unknown"),
                severity=str(finding.get("severity") or "error"),
                message=str(finding.get("message") or ""),
                expected=str(finding.get("expected") or ""),
                actual=str(finding.get("actual") or ""),
            )
        for gate in acceptance_summary.get("remaining_gates", []) or []:
            add_blocker(source="remaining_gate", key=str(gate), severity="error")
        for operation in acceptance_summary.get("top_blockers", []) or []:
            if not isinstance(operation, dict):
                continue
            for reason in operation.get("blocking_reasons") or []:
                add_blocker(
                    source="operation_blocker",
                    key=str(reason),
                    severity="error",
                    operation_id=str(operation.get("operation_id") or "") or None,
                    operation_title=str(operation.get("title") or "") or None,
                )
        provider = acceptance_summary.get("openclaw_provider_readiness")
        if isinstance(provider, dict) and provider.get("ready") is not True:
            for reason in provider.get("blocking_reasons") or ["openclaw_provider_not_ready"]:
                add_blocker(source="openclaw_provider", key=str(reason), severity="error")

        blocker_items.sort(key=lambda item: (int(item.get("priority") or 0), str(item.get("blocker_key") or "")), reverse=True)
        external_dependency_count = sum(1 for item in blocker_items if item.get("external_dependency_required"))
        ui_clearable_count = sum(1 for item in blocker_items if item.get("can_be_resolved_by_ui"))
        work_ordered_count = sum(1 for item in blocker_items if item.get("latest_work_order_id"))
        ready_for_execution_count = sum(1 for item in blocker_items if item.get("prep_status") == "ready_for_operator_execution_review")
        refreshed_count = sum(1 for item in blocker_items if item.get("prep_status") == "completed_readiness_refreshed")
        if not blocker_items:
            clearance_status = "production_closed_loop_clear"
            next_focus = "no_delivery_audit_blocker_clearance_required"
        elif ready_for_execution_count:
            clearance_status = "blocker_clearance_ready_for_operator_execution"
            next_focus = next(
                str(item.get("recommended_action") or "")
                for item in blocker_items
                if item.get("prep_status") == "ready_for_operator_execution_review"
            )
        elif external_dependency_count:
            clearance_status = "blocker_clearance_external_dependency_required"
            next_focus = next(
                str(item.get("recommended_action") or "")
                for item in blocker_items
                if item.get("external_dependency_required")
            )
        elif work_ordered_count < len(blocker_items):
            clearance_status = "blocker_clearance_work_order_assignment_required"
            next_focus = "assign_delivery_remediation_work_orders"
        elif refreshed_count:
            clearance_status = "blocker_clearance_readiness_refreshed_review_next_action"
            next_focus = "review_production_closed_loop_next_action"
        else:
            clearance_status = "blocker_clearance_in_progress"
            next_focus = str(coverage.get("next_focus") or remediation_map.get("next_focus") or "review_delivery_audit_blockers")

        return {
            "workspace_id": workspace_id,
            "clearance_status": clearance_status,
            "production_config_ready": not any(
                isinstance(item, dict) and item.get("severity") == "error"
                for item in config_findings
            ),
            "acceptance_summary_ready": bool(acceptance_summary.get("acceptance_status") == "accepted")
            and not acceptance_summary.get("remaining_gates"),
            "blocker_count": len(blocker_items),
            "external_dependency_count": external_dependency_count,
            "ui_clearable_count": ui_clearable_count,
            "work_ordered_count": work_ordered_count,
            "ready_for_execution_count": ready_for_execution_count,
            "readiness_refreshed_count": refreshed_count,
            "next_focus": next_focus,
            "items": blocker_items,
            "production_config_findings": config_findings,
            "acceptance_summary": acceptance_summary,
            "remediation_map": remediation_map,
            "work_order_coverage": coverage,
            "execution_prep": execution_prep,
            "acceptance_gates": [
                "production_closed_loop_delivery_audit",
                "production_config_errors_mapped_to_clearance_items",
                "acceptance_remaining_gates_mapped_to_clearance_items",
                "delivery_remediation_work_order_state_joined",
                "operator_approval_required_before_mutating_follow_up",
            ],
            "boundaries": [
                "delivery_audit_blocker_clearance_plan_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71G",
                "contract": "production_closed_loop_delivery_audit_blocker_clearance_plan",
                "source_contract": "production_closed_loop_delivery_audit",
                "acceptance_summary_contract": "production_closed_loop_acceptance_summary",
                "remediation_map_contract": "production_closed_loop_delivery_remediation_map",
                "work_order_coverage_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "execution_prep_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def assign_production_closed_loop_delivery_audit_blocker_clearance_work_orders(
        self,
        *,
        workspace_id: str,
        assignee: str,
        operator_confirmed: bool = False,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        include_external_dependencies: bool = True,
        work_summary: str | None = None,
        operator_notes: str | None = None,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Assign remediation work orders directly from production audit blockers."""

        clean_assignee = str(assignee or "").strip()
        if not clean_assignee:
            raise ValueError("assignee is required")
        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before assigning delivery audit blocker work orders")
        clean_summary = str(work_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        clean_metadata = dict(metadata or {})
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "assignee": clean_assignee,
                "work_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": clean_metadata,
            }
        )
        if sensitive_paths:
            raise ValueError(f"delivery audit blocker assignment payload contains sensitive key or value: {sensitive_paths[0]}")

        clearance_plan_before = await self.get_production_closed_loop_delivery_audit_blocker_clearance_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        blocker_items = [item for item in clearance_plan_before.get("items", []) if isinstance(item, dict)]
        gate_to_blockers: dict[str, list[dict[str, Any]]] = {}
        skipped_items: list[dict[str, Any]] = []

        def skip_item(item: dict[str, Any], reason: str) -> None:
            skipped_items.append(
                self._json_safe_dict(
                    {
                        "blocker_key": item.get("blocker_key"),
                        "source": item.get("source"),
                        "gate_key": item.get("gate_key"),
                        "remediation_key": item.get("remediation_key"),
                        "reason": reason,
                        "external_dependency_required": bool(item.get("external_dependency_required")),
                    }
                )
            )

        for item in blocker_items:
            gate_key = str(item.get("gate_key") or "").strip()
            remediation_key = str(item.get("remediation_key") or "").strip()
            if item.get("latest_work_order_id"):
                skip_item(item, "already_has_work_order")
                continue
            if item.get("external_dependency_required") and not include_external_dependencies:
                skip_item(item, "external_dependency_excluded")
                continue
            if not gate_key or not remediation_key:
                skip_item(item, "not_mapped_to_delivery_remediation")
                continue
            gate_to_blockers.setdefault(gate_key, []).append(item)

        records: list[dict[str, Any]] = []
        failed_gate_keys: list[str] = []
        for gate_key, blockers in gate_to_blockers.items():
            primary_item = blockers[0]
            blocker_keys = self._dedupe_texts(
                [str(item.get("blocker_key") or "") for item in blockers if str(item.get("blocker_key") or "").strip()]
            )
            try:
                record = await self.record_production_closed_loop_delivery_remediation_work_order(
                    workspace_id=workspace_id,
                    remediation_key=str(primary_item.get("remediation_key") or "") or None,
                    gate_key=gate_key,
                    work_order_status="assigned",
                    assignee=clean_assignee,
                    operator_confirmed=True,
                    work_summary=clean_summary or f"Delivery audit blocker work order assigned for {gate_key}.",
                    operator_notes=clean_notes
                    or "Assigned from Phase 71H production delivery audit blocker clearance control.",
                    created_by=created_by,
                    metadata={
                        **clean_metadata,
                        "source_contract": "production_closed_loop_delivery_audit_blocker_clearance_plan",
                        "assignment_phase": "71H",
                        "assignment_control": "assign_delivery_audit_blocker_work_orders",
                        "blocker_keys": blocker_keys,
                        "blocker_sources": self._dedupe_texts(
                            [str(item.get("source") or "") for item in blockers if str(item.get("source") or "").strip()]
                        ),
                        "external_dependency_required": any(
                            bool(item.get("external_dependency_required")) for item in blockers
                        ),
                        "include_external_dependencies": include_external_dependencies,
                        "platform": platform,
                        "force_metric_due": force_metric_due,
                    },
                )
                records.append(record)
            except ValueError:
                failed_gate_keys.append(gate_key)
                for item in blockers:
                    skip_item(item, "work_order_record_rejected")

        clearance_plan_after = await self.get_production_closed_loop_delivery_audit_blocker_clearance_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        requested_gate_count = len(gate_to_blockers)
        created_count = len(records)
        blocker_count = len(blocker_items)
        if blocker_count == 0:
            assignment_status = "no_delivery_audit_blockers"
        elif requested_gate_count == 0:
            assignment_status = "no_assignable_delivery_audit_blocker_work_orders"
        elif created_count == requested_gate_count:
            assignment_status = "delivery_audit_blocker_work_orders_assigned"
        elif created_count:
            assignment_status = "delivery_audit_blocker_work_orders_partially_assigned"
        else:
            assignment_status = "delivery_audit_blocker_work_orders_not_assigned"

        return {
            "workspace_id": workspace_id,
            "assignment_status": assignment_status,
            "blocker_count": blocker_count,
            "assignable_blocker_count": sum(len(items) for items in gate_to_blockers.values()),
            "requested_gate_count": requested_gate_count,
            "created_count": created_count,
            "skipped_count": len(skipped_items),
            "assignee": clean_assignee,
            "include_external_dependencies": include_external_dependencies,
            "assigned_gate_keys": [str(record.get("gate_key") or "") for record in records],
            "failed_gate_keys": failed_gate_keys,
            "skipped_items": skipped_items,
            "records": records,
            "clearance_plan_before": clearance_plan_before,
            "clearance_plan_after": clearance_plan_after,
            "coverage_after": clearance_plan_after.get("work_order_coverage"),
            "execution_prep_after": clearance_plan_after.get("execution_prep"),
            "acceptance_gates": [
                "production_closed_loop_delivery_audit_blocker_clearance_plan",
                "operator_confirmation_required_before_blocker_work_order_assignment",
                "assigned_work_orders_are_metadata_records_only",
                "external_dependency_items_remain_manual_until_operator_evidence",
            ],
            "boundaries": [
                "delivery_audit_blocker_work_order_assignment_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71H",
                "contract": "production_closed_loop_delivery_audit_blocker_work_order_assignment",
                "source_contract": "production_closed_loop_delivery_audit_blocker_clearance_plan",
                "record_contract": "production_closed_loop_delivery_remediation_work_order",
                "coverage_contract": "production_closed_loop_delivery_remediation_work_order_coverage",
                "execution_prep_contract": "production_closed_loop_delivery_remediation_work_order_execution_prep",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "work_order_limit": max(1, min(int(work_order_limit or 200), 500)),
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def get_production_closed_loop_delivery_audit_blocker_runbook_packages(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
    ) -> dict[str, Any]:
        """Build operator runbook handoff packages for production audit blockers."""

        clearance_plan = await self.get_production_closed_loop_delivery_audit_blocker_clearance_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        blocker_items = [item for item in clearance_plan.get("items", []) if isinstance(item, dict)]
        execution_prep = clearance_plan.get("execution_prep") if isinstance(clearance_plan.get("execution_prep"), dict) else {}
        prep_by_gate = {
            str(item.get("gate_key") or ""): item
            for item in execution_prep.get("items", [])
            if isinstance(item, dict) and str(item.get("gate_key") or "").strip()
        }
        grouped: dict[str, list[dict[str, Any]]] = {}
        for item in blocker_items:
            gate_key = str(item.get("gate_key") or "").strip()
            blocker_key = str(item.get("blocker_key") or "").strip()
            group_key = gate_key or blocker_key
            if not group_key:
                continue
            grouped.setdefault(group_key, []).append(item)

        def package_required_inputs(items: list[dict[str, Any]]) -> list[str]:
            candidates: list[str] = []
            for item in items:
                key = str(item.get("blocker_key") or item.get("title") or "")
                expected = str(item.get("expected") or "").strip()
                actual = str(item.get("actual") or "").strip()
                if "OPENCLAW_PROVIDER" in key:
                    candidates.extend(
                        [
                            "OPENCLAW_PROVIDER",
                            "WORKER_CLIENT_OPENCLAW_PROVIDER",
                            "WORKER_CLIENT_OPENCLAW_BASE_URL",
                            "WORKER_CLIENT_OPENCLAW_API_KEY",
                        ]
                    )
                elif "openclaw" in key.lower():
                    candidates.extend(
                        [
                            "WORKER_CLIENT_OPENCLAW_PROVIDER",
                            "WORKER_CLIENT_OPENCLAW_BASE_URL",
                            "WORKER_CLIENT_OPENCLAW_API_KEY",
                        ]
                    )
                if "approved_operation_plan_missing" in key:
                    candidates.append("approved_operation_plan")
                if "operation_in_intervention_queue" in key or "intervention" in key:
                    candidates.append("intervention_acknowledgement_or_resolution")
                if "primary_step" in key:
                    candidates.append("fresh_primary_step_evidence")
                if expected:
                    candidates.append(f"expected:{expected}")
                if actual:
                    candidates.append(f"current:{actual}")
            return self._dedupe_texts(candidates)

        def package_verification_commands(items: list[dict[str, Any]]) -> list[str]:
            commands = [
                "python scripts/check_production_closed_loop.py",
            ]
            if any(item.get("source") == "production_config" for item in items):
                commands.insert(0, "python scripts/check_production_config.py")
            if any("openclaw" in str(item.get("blocker_key") or "").lower() for item in items):
                commands.insert(0, "python scripts/check_openclaw_provider.py")
            return self._dedupe_texts(commands)

        def package_manual_steps(items: list[dict[str, Any]], prep_item: dict[str, Any] | None) -> list[str]:
            openclaw_related = any("openclaw" in str(item.get("blocker_key") or "").lower() for item in items)
            steps = [
                "Review the assigned remediation work order and blocker list before changing any external system.",
            ]
            if openclaw_related:
                steps.extend(
                    [
                        "Configure a real non-mock OpenClaw provider in the server and customer-machine worker environment.",
                        "Restart only the affected runtime processes after configuration is saved by the operator.",
                        "Run provider diagnostics and smoke checks without clicking publish or controlling live accounts.",
                    ]
                )
            else:
                steps.append("Complete the missing approval, evidence, intervention acknowledgement, or readiness record in the target console.")
            if prep_item:
                steps.extend(
                    [
                        str(step)
                        for step in prep_item.get("operator_checklist", [])
                        if str(step or "").strip()
                    ]
                )
            steps.extend(
                [
                    "Attach verification evidence to the remediation work order before marking it completed.",
                    "Run the production closed-loop audit again and refresh readiness after completed work-order evidence.",
                ]
            )
            return self._dedupe_texts(steps)

        packages: list[dict[str, Any]] = []
        for group_key, items in grouped.items():
            first_item = items[0]
            gate_key = str(first_item.get("gate_key") or "").strip() or None
            prep_item = prep_by_gate.get(gate_key or "")
            blocker_keys = self._dedupe_texts(
                [str(item.get("blocker_key") or "") for item in items if str(item.get("blocker_key") or "").strip()]
            )
            runbook_references = self._dedupe_texts(
                [
                    *[
                        str(reference)
                        for item in items
                        for reference in item.get("runbook_references", [])
                        if str(reference or "").strip()
                    ],
                    "docs/PHASE_71G_PRODUCTION_DELIVERY_AUDIT_BLOCKER_CLEARANCE_PLAN.md",
                    "docs/PHASE_71H_PRODUCTION_DELIVERY_AUDIT_BLOCKER_WORK_ORDER_ASSIGNMENT.md",
                ]
            )
            evidence_requirements = self._dedupe_texts(
                [
                    *[
                        str(requirement)
                        for requirement in (prep_item or {}).get("evidence_requirements", [])
                        if str(requirement or "").strip()
                    ],
                    "operator work-order completion summary",
                    "production closed-loop audit output after remediation",
                ]
            )
            latest_work_order_id = (prep_item or first_item).get("latest_work_order_id")
            latest_work_order_status = (prep_item or first_item).get("latest_work_order_status")
            package = self._json_safe_dict(
                {
                    "package_key": f"delivery_audit_blocker_runbook:{group_key}",
                    "title": f"Runbook handoff: {gate_key or str(first_item.get('title') or group_key)}",
                    "blocker_keys": blocker_keys,
                    "sources": self._dedupe_texts(
                        [str(item.get("source") or "") for item in items if str(item.get("source") or "").strip()]
                    ),
                    "severity": "error" if any(str(item.get("severity") or "") == "error" for item in items) else "warning",
                    "gate_key": gate_key,
                    "remediation_key": first_item.get("remediation_key"),
                    "target_console": str(first_item.get("target_console") or "server_operator_console"),
                    "target_endpoint": first_item.get("target_endpoint"),
                    "owner": str(first_item.get("owner") or "operator"),
                    "priority": max(int(item.get("priority") or 0) for item in items),
                    "external_dependency_required": any(bool(item.get("external_dependency_required")) for item in items),
                    "can_be_resolved_by_ui": all(bool(item.get("can_be_resolved_by_ui")) for item in items),
                    "operator_approval_required": True,
                    "current_state": str((prep_item or first_item).get("prep_status") or first_item.get("current_state") or "unknown"),
                    "coverage_status": (prep_item or first_item).get("coverage_status"),
                    "prep_status": (prep_item or first_item).get("prep_status"),
                    "latest_work_order_id": latest_work_order_id,
                    "latest_work_order_status": latest_work_order_status,
                    "recommended_actions": self._dedupe_texts(
                        [
                            str(item.get("recommended_action") or "")
                            for item in items
                            if str(item.get("recommended_action") or "").strip()
                        ]
                    ),
                    "required_inputs": package_required_inputs(items),
                    "manual_steps": package_manual_steps(items, prep_item),
                    "verification_commands": package_verification_commands(items),
                    "evidence_requirements": evidence_requirements,
                    "runbook_references": runbook_references,
                    "handoff_notes": [
                        "This package is operator guidance only; it does not execute remediation automatically.",
                        "External dependency blockers remain blocked until real configuration and evidence are supplied.",
                    ],
                    "boundaries": [
                        "delivery_audit_blocker_runbook_handoff_only_no_external_execution",
                        "does_not_execute_target_endpoint",
                        "does_not_run_openclaw_or_playwright_on_server",
                        "does_not_publish_or_control_real_accounts",
                        "does_not_submit_comfyui_prompt",
                        "does_not_store_or_print_secrets",
                        "does_not_bypass_operator_approval",
                    ],
                }
            )
            packages.append(package)

        packages.sort(key=lambda item: (int(item.get("priority") or 0), str(item.get("package_key") or "")), reverse=True)
        external_dependency_package_count = sum(1 for item in packages if item.get("external_dependency_required"))
        work_ordered_package_count = sum(1 for item in packages if item.get("latest_work_order_id"))
        if not packages:
            handoff_status = "no_delivery_audit_blocker_runbook_required"
            next_focus = "no_delivery_audit_blockers"
        elif work_ordered_package_count < len(packages):
            handoff_status = "runbook_handoff_waiting_for_work_order_assignment"
            next_focus = "assign_delivery_audit_blocker_work_orders"
        elif external_dependency_package_count:
            handoff_status = "runbook_handoff_external_dependency_required"
            next_focus = "execute_external_dependency_runbooks"
        else:
            handoff_status = "runbook_handoff_ready_for_operator_execution"
            next_focus = "execute_operator_runbooks_and_attach_evidence"

        return {
            "workspace_id": workspace_id,
            "handoff_status": handoff_status,
            "package_count": len(packages),
            "external_dependency_package_count": external_dependency_package_count,
            "work_ordered_package_count": work_ordered_package_count,
            "next_focus": next_focus,
            "packages": packages,
            "clearance_plan": clearance_plan,
            "acceptance_gates": [
                "production_closed_loop_delivery_audit_blocker_clearance_plan",
                "delivery_audit_blockers_have_operator_runbook_handoff",
                "external_dependency_runbooks_require_operator_evidence",
            ],
            "boundaries": [
                "delivery_audit_blocker_runbook_handoff_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_store_or_print_secrets",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71I",
                "contract": "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                "source_contract": "production_closed_loop_delivery_audit_blocker_clearance_plan",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def record_production_closed_loop_delivery_audit_blocker_runbook_evidence(
        self,
        *,
        workspace_id: str,
        package_key: str | None = None,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        evidence_status: str = "submitted",
        operator_confirmed: bool = False,
        evidence_links: list[dict[str, Any]] | None = None,
        evidence_summary: str | None = None,
        operator_notes: str | None = None,
        platform: str | None = None,
        force_metric_due: bool = False,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Record operator evidence against a delivery audit blocker runbook package."""

        clean_package_key = str(package_key or "").strip() or None
        clean_gate_key = str(gate_key or "").strip() or None
        if not clean_package_key and not clean_gate_key:
            raise ValueError("package_key or gate_key is required")
        clean_status = str(evidence_status or "submitted").strip().lower()
        allowed_statuses = {"submitted", "blocked", "resolved", "needs_follow_up", "dismissed"}
        if clean_status not in allowed_statuses:
            raise ValueError("evidence_status must be submitted, blocked, resolved, needs_follow_up, or dismissed")
        if clean_status in {"submitted", "resolved"} and not operator_confirmed:
            raise ValueError("operator_confirmed is required for submitted and resolved runbook evidence")
        clean_evidence_links = [dict(item) for item in evidence_links or [] if isinstance(item, dict)]
        clean_summary = str(evidence_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        if clean_status == "resolved" and not clean_evidence_links and not clean_summary:
            raise ValueError("evidence_links or evidence_summary is required when resolving runbook evidence")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"runbook evidence payload contains sensitive key or value: {sensitive_paths[0]}")

        runbooks = await self.get_production_closed_loop_delivery_audit_blocker_runbook_packages(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        packages = [item for item in runbooks.get("packages", []) if isinstance(item, dict)]
        runbook_package = next(
            (
                item
                for item in packages
                if (clean_package_key and str(item.get("package_key") or "") == clean_package_key)
                or (clean_gate_key and str(item.get("gate_key") or "") == clean_gate_key)
            ),
            None,
        )
        if runbook_package is None:
            raise ValueError("package_key or gate_key is not present in the current blocker runbook handoff")
        clean_package_key = str(runbook_package.get("package_key") or clean_package_key or "")
        clean_gate_key = str(runbook_package.get("gate_key") or clean_gate_key or "")

        anchor_operation_id = operation_id
        if anchor_operation_id is None and clean_gate_key:
            work_orders = await self.list_production_closed_loop_delivery_remediation_work_orders(
                workspace_id=workspace_id,
                gate_key=clean_gate_key,
                limit=1,
            )
            latest_work_order = work_orders.get("latest_record") if isinstance(work_orders.get("latest_record"), dict) else None
            if latest_work_order and latest_work_order.get("operation_id"):
                anchor_operation_id = UUID(str(latest_work_order["operation_id"]))
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before recording runbook evidence")
            anchor_operation_id = operations[0].id
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)

        now = datetime.now(UTC)
        record = self._json_safe_dict(
            {
                "evidence_record_id": str(uuid4()),
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "package_key": clean_package_key,
                "gate_key": clean_gate_key or None,
                "remediation_key": runbook_package.get("remediation_key"),
                "evidence_status": clean_status,
                "operator_confirmed": operator_confirmed,
                "target_console": str(runbook_package.get("target_console") or "server_operator_console"),
                "current_state": str(runbook_package.get("current_state") or "unknown"),
                "latest_work_order_id": runbook_package.get("latest_work_order_id"),
                "latest_work_order_status": runbook_package.get("latest_work_order_status"),
                "external_dependency_required": bool(runbook_package.get("external_dependency_required")),
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "verification_commands": [
                    str(item)
                    for item in runbook_package.get("verification_commands", [])
                    if str(item or "").strip()
                ],
                "required_inputs": [
                    str(item)
                    for item in runbook_package.get("required_inputs", [])
                    if str(item or "").strip()
                ],
                "evidence_requirements": [
                    str(item)
                    for item in runbook_package.get("evidence_requirements", [])
                    if str(item or "").strip()
                ],
                "runbook_references": [
                    str(item)
                    for item in runbook_package.get("runbook_references", [])
                    if str(item or "").strip()
                ],
                "contract_snapshot": {
                    "contract": "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                    "handoff_status": runbooks.get("handoff_status"),
                    "next_focus": runbooks.get("next_focus"),
                    "runbook_package": {
                        "package_key": runbook_package.get("package_key"),
                        "title": runbook_package.get("title"),
                        "blocker_keys": runbook_package.get("blocker_keys", []),
                        "gate_key": runbook_package.get("gate_key"),
                        "target_console": runbook_package.get("target_console"),
                        "current_state": runbook_package.get("current_state"),
                        "verification_commands": runbook_package.get("verification_commands", []),
                        "evidence_requirements": runbook_package.get("evidence_requirements", []),
                    },
                },
                "boundary_checks": [
                    "delivery_audit_blocker_runbook_contract_matched",
                    "server_side_external_execution_false",
                    "operator_approval_boundary_preserved",
                    "external_execution_not_performed",
                    "secret_values_not_required_or_stored",
                ],
                "created_by": created_by,
                "created_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "71J",
                    "contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence",
                    "source_contract": "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                    "workspace_gate_record": operation_id is None,
                    "platform": platform,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_audit_blocker_runbook_evidence_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_bypass_operator_approval",
                ],
            }
        )

        operation_metadata = dict(operation.operation_metadata or {})
        history = self._production_closed_loop_delivery_audit_blocker_runbook_evidence_history(operation)
        history = [*history, record][-100:]
        operation_metadata["production_closed_loop_delivery_audit_blocker_runbook_evidence_records"] = history
        operation_metadata["production_closed_loop_delivery_audit_blocker_runbook_evidence_latest"] = record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)
        return record

    async def list_production_closed_loop_delivery_audit_blocker_runbook_evidence(
        self,
        *,
        workspace_id: str,
        package_key: str | None = None,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        evidence_status: str | None = None,
        limit: int = 50,
    ) -> dict[str, Any]:
        """List recorded delivery audit blocker runbook evidence across a workspace."""

        clean_package_key = str(package_key or "").strip() or None
        clean_gate_key = str(gate_key or "").strip() or None
        clean_status = str(evidence_status or "").strip().lower() or None
        clean_limit = max(1, min(int(limit or 50), 200))
        if operation_id is not None:
            operations = [await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)]
        else:
            operations = await self.list_operations(workspace_id=workspace_id, limit=500)
        records: list[dict[str, Any]] = []
        for operation in operations:
            for record in self._production_closed_loop_delivery_audit_blocker_runbook_evidence_history(operation):
                if clean_package_key and str(record.get("package_key") or "") != clean_package_key:
                    continue
                if clean_gate_key and str(record.get("gate_key") or "") != clean_gate_key:
                    continue
                if clean_status and str(record.get("evidence_status") or "").lower() != clean_status:
                    continue
                records.append(record)
        records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
        records = records[:clean_limit]
        latest_record = records[0] if records else None
        return {
            "workspace_id": workspace_id,
            "record_count": len(records),
            "latest_record": latest_record,
            "records": records,
            "acceptance_gates": [
                "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                "runbook_evidence_is_operator_supplied",
                "operator_confirmation_required_for_submitted_or_resolved_status",
                "external_dependency_evidence_does_not_execute_from_server",
            ],
            "boundaries": [
                "delivery_audit_blocker_runbook_evidence_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_store_or_print_secrets",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71J",
                "contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_list",
                "source_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence",
                "storage": (
                    "commercial_operations.operation_metadata."
                    "production_closed_loop_delivery_audit_blocker_runbook_evidence_records"
                ),
                "package_filter": clean_package_key,
                "gate_filter": clean_gate_key,
                "operation_filter": str(operation_id) if operation_id else None,
                "status_filter": clean_status,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def get_production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        evidence_limit: int = 200,
    ) -> dict[str, Any]:
        """Summarize evidence coverage for production audit blocker runbook packages."""

        runbook_packages = await self.get_production_closed_loop_delivery_audit_blocker_runbook_packages(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        evidence_records = await self.list_production_closed_loop_delivery_audit_blocker_runbook_evidence(
            workspace_id=workspace_id,
            limit=evidence_limit,
        )
        records = [item for item in evidence_records.get("records", []) if isinstance(item, dict)]
        records_by_package: dict[str, list[dict[str, Any]]] = {}
        records_by_gate: dict[str, list[dict[str, Any]]] = {}
        for record in records:
            package_key = str(record.get("package_key") or "").strip()
            gate_key = str(record.get("gate_key") or "").strip()
            if package_key:
                records_by_package.setdefault(package_key, []).append(record)
            if gate_key:
                records_by_gate.setdefault(gate_key, []).append(record)

        items: list[dict[str, Any]] = []
        missing_evidence_count = 0
        evidenced_count = 0
        resolved_count = 0
        blocked_count = 0
        needs_follow_up_count = 0
        dismissed_count = 0
        for package in runbook_packages.get("packages", []):
            if not isinstance(package, dict):
                continue
            package_key = str(package.get("package_key") or "")
            gate_key = str(package.get("gate_key") or "")
            matching_records = records_by_package.get(package_key, [])
            if not matching_records and gate_key:
                matching_records = records_by_gate.get(gate_key, [])
            latest_record = matching_records[0] if matching_records else None
            latest_status = str(latest_record.get("evidence_status") or "").lower() if latest_record else None
            if latest_record is None:
                coverage_status = "missing_runbook_evidence"
                next_action = f"record_runbook_evidence:{package_key}"
                missing_evidence_count += 1
            elif latest_status == "resolved":
                coverage_status = "runbook_evidence_resolved"
                next_action = f"refresh_readiness_after_runbook_evidence:{gate_key or package_key}"
                evidenced_count += 1
                resolved_count += 1
            elif latest_status == "blocked":
                coverage_status = "runbook_evidence_blocked"
                next_action = f"resolve_runbook_blocker:{gate_key or package_key}"
                evidenced_count += 1
                blocked_count += 1
            elif latest_status == "needs_follow_up":
                coverage_status = "runbook_evidence_needs_follow_up"
                next_action = f"follow_up_runbook_evidence:{gate_key or package_key}"
                evidenced_count += 1
                needs_follow_up_count += 1
            elif latest_status == "dismissed":
                coverage_status = "runbook_evidence_dismissed_needs_review"
                next_action = f"review_dismissed_runbook_evidence:{gate_key or package_key}"
                evidenced_count += 1
                dismissed_count += 1
            else:
                coverage_status = "runbook_evidence_submitted"
                next_action = f"review_runbook_evidence:{gate_key or package_key}"
                evidenced_count += 1

            items.append(
                self._json_safe_dict(
                    {
                        "package_key": package_key,
                        "title": package.get("title"),
                        "gate_key": gate_key or None,
                        "remediation_key": package.get("remediation_key"),
                        "target_console": package.get("target_console"),
                        "owner": package.get("owner"),
                        "priority": int(package.get("priority") or 0),
                        "external_dependency_required": bool(package.get("external_dependency_required")),
                        "latest_work_order_id": package.get("latest_work_order_id"),
                        "latest_work_order_status": package.get("latest_work_order_status"),
                        "evidence_record_count": len(matching_records),
                        "latest_evidence_record_id": latest_record.get("evidence_record_id") if latest_record else None,
                        "latest_evidence_status": latest_status,
                        "latest_evidence_summary": latest_record.get("evidence_summary") if latest_record else None,
                        "latest_evidence_created_at": latest_record.get("created_at") if latest_record else None,
                        "latest_evidence_operator_confirmed": (
                            bool(latest_record.get("operator_confirmed")) if latest_record else False
                        ),
                        "coverage_status": coverage_status,
                        "next_action": next_action,
                        "verification_commands": package.get("verification_commands", []),
                        "evidence_requirements": package.get("evidence_requirements", []),
                        "boundaries": [
                            "delivery_audit_blocker_runbook_evidence_coverage_only_no_external_execution",
                            "does_not_execute_target_endpoint",
                            "does_not_run_openclaw_or_playwright_on_server",
                            "does_not_publish_or_control_real_accounts",
                            "does_not_submit_comfyui_prompt",
                            "does_not_store_or_print_secrets",
                            "does_not_bypass_operator_approval",
                        ],
                    }
                )
            )

        package_count = len(items)
        coverage_percent = int(round((evidenced_count / package_count) * 100)) if package_count else 100
        if package_count == 0:
            coverage_status = "no_runbook_evidence_required"
            next_focus = "no_delivery_audit_blockers"
        elif missing_evidence_count:
            coverage_status = "runbook_evidence_missing"
            next_focus = next(
                (item["next_action"] for item in items if item["coverage_status"] == "missing_runbook_evidence"),
                "record_runbook_evidence",
            )
        elif blocked_count:
            coverage_status = "runbook_evidence_blocked"
            next_focus = next(
                (item["next_action"] for item in items if item["coverage_status"] == "runbook_evidence_blocked"),
                "resolve_runbook_blockers",
            )
        elif needs_follow_up_count:
            coverage_status = "runbook_evidence_needs_follow_up"
            next_focus = "follow_up_runbook_evidence"
        elif dismissed_count:
            coverage_status = "runbook_evidence_dismissed_needs_review"
            next_focus = "review_dismissed_runbook_evidence"
        elif resolved_count >= package_count:
            coverage_status = "runbook_evidence_resolved"
            next_focus = "refresh_readiness_after_runbook_evidence"
        else:
            coverage_status = "runbook_evidence_submitted_for_review"
            next_focus = "review_runbook_evidence"

        return {
            "workspace_id": workspace_id,
            "coverage_status": coverage_status,
            "coverage_percent": coverage_percent,
            "package_count": package_count,
            "evidenced_count": evidenced_count,
            "missing_evidence_count": missing_evidence_count,
            "resolved_count": resolved_count,
            "blocked_count": blocked_count,
            "needs_follow_up_count": needs_follow_up_count,
            "dismissed_count": dismissed_count,
            "next_focus": next_focus,
            "items": items,
            "missing_items": [item for item in items if item["coverage_status"] == "missing_runbook_evidence"],
            "blocked_items": [item for item in items if item["coverage_status"] == "runbook_evidence_blocked"],
            "runbook_packages": runbook_packages,
            "evidence_records": evidence_records,
            "acceptance_gates": [
                "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                "production_closed_loop_delivery_audit_blocker_runbook_evidence",
                "every_runbook_package_has_operator_evidence",
                "resolved_runbook_evidence_requires_readiness_refresh",
            ],
            "boundaries": [
                "delivery_audit_blocker_runbook_evidence_coverage_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_store_or_print_secrets",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71K",
                "contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                "source_contract": "production_closed_loop_delivery_audit_blocker_runbook_handoff",
                "evidence_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_list",
                "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                "force_metric_due": force_metric_due,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def refresh_production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness(
        self,
        *,
        workspace_id: str,
        operation_id: UUID | None = None,
        platform: str | None = None,
        force_metric_due: bool = False,
        operator_confirmed: bool = False,
        refresh_notes: str | None = None,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        evidence_limit: int = 200,
        refreshed_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Audit a readiness refresh after all blocker runbook evidence is resolved."""

        clean_notes = str(refresh_notes or "").strip() or None
        clean_refreshed_by = str(refreshed_by or "").strip() or None
        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before refreshing runbook evidence readiness")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "operation_id": str(operation_id) if operation_id else None,
                "refresh_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"runbook evidence readiness refresh payload contains sensitive key or value: {sensitive_paths[0]}")

        coverage_before = await self.get_production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
            evidence_limit=evidence_limit,
        )
        package_count = int(coverage_before.get("package_count") or 0)
        resolved_count = int(coverage_before.get("resolved_count") or 0)
        missing_evidence_count = int(coverage_before.get("missing_evidence_count") or 0)
        blocked_count = int(coverage_before.get("blocked_count") or 0)
        needs_follow_up_count = int(coverage_before.get("needs_follow_up_count") or 0)
        dismissed_count = int(coverage_before.get("dismissed_count") or 0)
        evidenced_count = int(coverage_before.get("evidenced_count") or 0)
        submitted_or_review_count = max(
            0,
            evidenced_count - resolved_count - blocked_count - needs_follow_up_count - dismissed_count,
        )
        blocking_reasons: list[str] = []
        if missing_evidence_count:
            blocking_reasons.append(f"missing_evidence_count={missing_evidence_count}")
        if blocked_count:
            blocking_reasons.append(f"blocked_count={blocked_count}")
        if needs_follow_up_count:
            blocking_reasons.append(f"needs_follow_up_count={needs_follow_up_count}")
        if dismissed_count:
            blocking_reasons.append(f"dismissed_count={dismissed_count}")
        if submitted_or_review_count:
            blocking_reasons.append(f"submitted_or_review_count={submitted_or_review_count}")
        if package_count and resolved_count < package_count:
            blocking_reasons.append(f"resolved_count={resolved_count}/{package_count}")
        if blocking_reasons:
            raise ValueError(
                "all runbook evidence must be resolved before readiness refresh: "
                + ", ".join(self._dedupe_texts(blocking_reasons))
            )

        anchor_operation_id = operation_id
        evidence_records = coverage_before.get("evidence_records") if isinstance(coverage_before.get("evidence_records"), dict) else {}
        latest_evidence = evidence_records.get("latest_record") if isinstance(evidence_records.get("latest_record"), dict) else None
        if anchor_operation_id is None and latest_evidence and latest_evidence.get("operation_id"):
            try:
                anchor_operation_id = UUID(str(latest_evidence["operation_id"]))
            except ValueError:
                anchor_operation_id = None
        if anchor_operation_id is None:
            for record in evidence_records.get("records", []) if isinstance(evidence_records.get("records"), list) else []:
                if isinstance(record, dict) and record.get("operation_id"):
                    try:
                        anchor_operation_id = UUID(str(record["operation_id"]))
                        break
                    except ValueError:
                        continue
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before refreshing runbook evidence readiness")
            anchor_operation_id = operations[0].id
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)

        readiness = await self.get_production_closed_loop_readiness(
            workspace_id=workspace_id,
            operation_id=anchor_operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        next_action = await self.get_production_closed_loop_next_action(
            workspace_id=workspace_id,
            operation_id=anchor_operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        selected_action_key = str(next_action.get("selected_action_key") or readiness.get("next_action") or "")
        readiness_status = str(readiness.get("readiness_status") or "unknown")
        current_stage_key = str(readiness.get("current_stage_key") or "") or None
        current_stage_status = None
        for stage in readiness.get("stages", []):
            if isinstance(stage, dict) and str(stage.get("stage_key") or "") == str(current_stage_key or ""):
                current_stage_status = str(stage.get("status") or "") or None
                break

        acceptance_summary_after = await self.get_production_closed_loop_acceptance_summary(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        clearance_plan_after = await self.get_production_closed_loop_delivery_audit_blocker_clearance_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        runbook_packages_after = await self.get_production_closed_loop_delivery_audit_blocker_runbook_packages(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        coverage_after = await self.get_production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
            evidence_limit=evidence_limit,
        )

        now = datetime.now(UTC)
        refresh_id = str(uuid4())
        refresh_status = (
            "no_runbook_evidence_required_readiness_refreshed"
            if not package_count
            else "resolved_runbook_evidence_readiness_refreshed"
        )
        refresh_record = self._json_safe_dict(
            {
                "refresh_id": refresh_id,
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "refresh_status": refresh_status,
                "coverage_status": str(coverage_after.get("coverage_status") or coverage_before.get("coverage_status") or "unknown"),
                "coverage_percent": int(coverage_after.get("coverage_percent") or 0),
                "package_count": int(coverage_after.get("package_count") or 0),
                "resolved_count": int(coverage_after.get("resolved_count") or 0),
                "missing_evidence_count": int(coverage_after.get("missing_evidence_count") or 0),
                "blocked_count": int(coverage_after.get("blocked_count") or 0),
                "needs_follow_up_count": int(coverage_after.get("needs_follow_up_count") or 0),
                "dismissed_count": int(coverage_after.get("dismissed_count") or 0),
                "readiness_status": readiness_status,
                "current_stage_key": current_stage_key,
                "current_stage_status": current_stage_status,
                "next_action_key": selected_action_key,
                "operator_confirmed": True,
                "refresh_notes": clean_notes,
                "refreshed_by": clean_refreshed_by,
                "refreshed_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "71L",
                    "contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refresh",
                    "source_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "readiness_contract": "production_closed_loop_e2e_readiness",
                    "next_action_contract": "production_closed_loop_next_action",
                    "platform": platform,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_audit_blocker_runbook_evidence_readiness_refresh_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_bypass_operator_approval",
                ],
            }
        )
        operation_metadata = dict(operation.operation_metadata or {})
        refresh_history = self._production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refresh_history(operation)
        refresh_history = [*refresh_history, refresh_record][-100:]
        operation_metadata["production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refreshes"] = refresh_history
        operation_metadata["production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refresh_latest"] = refresh_record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)

        return self._json_safe_dict(
            {
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "refresh_id": refresh_id,
                "refresh_status": refresh_status,
                "coverage_status": str(coverage_after.get("coverage_status") or "unknown"),
                "coverage_percent": int(coverage_after.get("coverage_percent") or 0),
                "package_count": int(coverage_after.get("package_count") or 0),
                "resolved_count": int(coverage_after.get("resolved_count") or 0),
                "next_focus": str(coverage_after.get("next_focus") or selected_action_key or "refresh_production_audit"),
                "coverage_before": coverage_before,
                "coverage_after": coverage_after,
                "acceptance_summary_after": acceptance_summary_after,
                "clearance_plan_after": clearance_plan_after,
                "runbook_packages_after": runbook_packages_after,
                "readiness": readiness,
                "next_action": next_action,
                "refresh_record": refresh_record,
                "operator_confirmed": True,
                "refresh_notes": clean_notes,
                "acceptance_gates": [
                    "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "all_runbook_evidence_resolved_before_refresh",
                    "operator_confirmation_required_before_runbook_readiness_refresh",
                    "readiness_refresh_uses_current_production_closed_loop_readiness",
                    "next_action_recomputed_after_runbook_evidence",
                ],
                "boundaries": [
                    "delivery_audit_blocker_runbook_evidence_readiness_refresh_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_bypass_operator_approval",
                ],
                "generated_at": now,
                "metadata": {
                    "phase": "71L",
                    "contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refresh",
                    "source_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "coverage_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "readiness_contract": "production_closed_loop_e2e_readiness",
                    "next_action_contract": "production_closed_loop_next_action",
                    "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
            }
        )

    async def get_production_closed_loop_delivery_audit_next_action_plan(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        evidence_limit: int = 200,
    ) -> dict[str, Any]:
        """Build an owner-routed action plan for the current production delivery audit blockers."""

        acceptance_summary = await self.get_production_closed_loop_acceptance_summary(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
        )
        clearance_plan = await self.get_production_closed_loop_delivery_audit_blocker_clearance_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
        )
        runbook_evidence_coverage = await self.get_production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
            evidence_limit=evidence_limit,
        )

        actions_by_key: dict[str, dict[str, Any]] = {}
        blocking_reasons: list[str] = []

        def append_action(
            *,
            action_key: str,
            title: str,
            owner: str,
            priority: int,
            source_blocker: str,
            target: str,
            target_console: str | None = None,
            required_endpoint: str | None = None,
            verification_commands: list[str] | None = None,
            evidence_requirements: list[str] | None = None,
            external_dependency_required: bool = False,
            can_be_resolved_by_ui: bool = False,
        ) -> None:
            if source_blocker:
                blocking_reasons.append(source_blocker)
            existing = actions_by_key.get(action_key)
            if existing:
                existing["source_blockers"] = self._dedupe_texts(
                    [*existing.get("source_blockers", []), source_blocker]
                )
                existing["verification_commands"] = self._dedupe_texts(
                    [*existing.get("verification_commands", []), *(verification_commands or [])]
                )
                existing["evidence_requirements"] = self._dedupe_texts(
                    [*existing.get("evidence_requirements", []), *(evidence_requirements or [])]
                )
                existing["priority"] = min(int(existing.get("priority") or priority), priority)
                existing["external_dependency_required"] = bool(
                    existing.get("external_dependency_required") or external_dependency_required
                )
                existing["can_be_resolved_by_ui"] = bool(
                    existing.get("can_be_resolved_by_ui") or can_be_resolved_by_ui
                )
                return
            actions_by_key[action_key] = self._json_safe_dict(
                {
                    "action_key": action_key,
                    "title": title,
                    "owner": owner,
                    "priority": priority,
                    "source_blockers": [source_blocker] if source_blocker else [],
                    "target": target,
                    "target_console": target_console,
                    "required_endpoint": required_endpoint,
                    "verification_commands": verification_commands or [],
                    "evidence_requirements": evidence_requirements or [],
                    "external_dependency_required": external_dependency_required,
                    "can_be_resolved_by_ui": can_be_resolved_by_ui,
                    "operator_approval_required": True,
                    "boundaries": [
                        "delivery_audit_next_action_plan_only_no_external_execution",
                        "does_not_execute_target_endpoint",
                        "does_not_run_openclaw_or_playwright_on_server",
                        "does_not_publish_or_control_real_accounts",
                        "does_not_submit_comfyui_prompt",
                        "does_not_store_or_print_secrets",
                        "does_not_bypass_operator_approval",
                    ],
                }
            )

        for item in clearance_plan.get("items", []) if isinstance(clearance_plan.get("items"), list) else []:
            if not isinstance(item, dict):
                continue
            blocker_key = str(item.get("blocker_key") or "").strip()
            source = str(item.get("source") or "").strip()
            gate_key = str(item.get("gate_key") or "").strip()
            title = str(item.get("title") or gate_key or blocker_key or "Production delivery audit blocker")
            owner = str(item.get("owner") or "operator")
            priority = int(item.get("priority") or 50)
            target_console = str(item.get("target_console") or "") or None
            target_endpoint = str(item.get("target_endpoint") or "") or None
            external_dependency_required = bool(item.get("external_dependency_required"))
            can_be_resolved_by_ui = bool(item.get("can_be_resolved_by_ui"))
            verification_commands = [
                str(command)
                for command in item.get("runbook_references", [])
                if isinstance(command, str) and command.startswith("scripts/")
            ]
            evidence_requirements = self._dedupe_texts(
                [
                    str(item.get("recommended_action") or ""),
                    str(item.get("current_state") or ""),
                    f"gate:{gate_key}" if gate_key else "",
                ]
            )
            if source in {"production_config", "openclaw_provider"} or "openclaw" in blocker_key.lower():
                append_action(
                    action_key="configure_real_openclaw_provider",
                    title="Configure and verify the real OpenClaw publish provider",
                    owner="server_operator",
                    priority=10,
                    source_blocker=blocker_key,
                    target="production server and customer-machine worker",
                    target_console=target_console or "server_operator_console",
                    required_endpoint="/openclaw/provider-diagnostics",
                    verification_commands=self._dedupe_texts(
                        [*verification_commands, "python scripts/check_production_config.py --require-production", "python scripts/check_openclaw_provider.py"]
                    ),
                    evidence_requirements=evidence_requirements,
                    external_dependency_required=True,
                    can_be_resolved_by_ui=False,
                )
            elif source == "remaining_gate":
                append_action(
                    action_key=f"clear_acceptance_gate:{gate_key or blocker_key}",
                    title=f"Clear acceptance gate: {gate_key or blocker_key}",
                    owner=owner or "operation_owner",
                    priority=priority or 40,
                    source_blocker=blocker_key,
                    target="production closed-loop acceptance summary",
                    target_console=target_console,
                    required_endpoint=target_endpoint or "/api/v1/commercial-operations/production-closed-loop/acceptance-summary",
                    verification_commands=verification_commands or ["python scripts/check_production_closed_loop.py --report-only"],
                    evidence_requirements=evidence_requirements,
                    external_dependency_required=external_dependency_required,
                    can_be_resolved_by_ui=can_be_resolved_by_ui,
                )
            elif source == "operation_blocker":
                append_action(
                    action_key="clear_operation_project_blockers",
                    title="Open the blocked operation project and clear stale or missing project records",
                    owner="operation_owner",
                    priority=45,
                    source_blocker=blocker_key,
                    target="commercial operation project workbench",
                    target_console=target_console or "customer_machine_console",
                    required_endpoint=target_endpoint or "/api/v1/commercial-operations/production-closed-loop/acceptance-summary",
                    verification_commands=verification_commands or ["python scripts/check_production_closed_loop.py --report-only"],
                    evidence_requirements=evidence_requirements,
                    external_dependency_required=external_dependency_required,
                    can_be_resolved_by_ui=True,
                )
            else:
                append_action(
                    action_key="review_delivery_audit_blocker",
                    title="Review production delivery audit blocker",
                    owner=owner,
                    priority=priority or 80,
                    source_blocker=blocker_key,
                    target=str(item.get("recommended_action") or "production delivery audit"),
                    target_console=target_console,
                    required_endpoint=target_endpoint,
                    verification_commands=verification_commands,
                    evidence_requirements=evidence_requirements,
                    external_dependency_required=external_dependency_required,
                    can_be_resolved_by_ui=can_be_resolved_by_ui,
                )

        package_count = int(runbook_evidence_coverage.get("package_count") or 0)
        resolved_count = int(runbook_evidence_coverage.get("resolved_count") or 0)
        missing_evidence_count = int(runbook_evidence_coverage.get("missing_evidence_count") or 0)
        blocked_count = int(runbook_evidence_coverage.get("blocked_count") or 0)
        needs_follow_up_count = int(runbook_evidence_coverage.get("needs_follow_up_count") or 0)
        dismissed_count = int(runbook_evidence_coverage.get("dismissed_count") or 0)
        evidenced_count = int(runbook_evidence_coverage.get("evidenced_count") or 0)
        submitted_or_review_count = max(
            0,
            evidenced_count - resolved_count - blocked_count - needs_follow_up_count - dismissed_count,
        )
        coverage_status = str(runbook_evidence_coverage.get("coverage_status") or "unknown")
        coverage_ready = (
            coverage_status in {"runbook_evidence_resolved", "no_runbook_evidence_required"}
            and missing_evidence_count == 0
            and blocked_count == 0
            and needs_follow_up_count == 0
            and dismissed_count == 0
            and (package_count == 0 or resolved_count >= package_count)
        )
        runbook_blockers = []
        if missing_evidence_count:
            runbook_blockers.append(f"runbook_evidence_coverage:missing_evidence_count={missing_evidence_count}")
        if blocked_count:
            runbook_blockers.append(f"runbook_evidence_coverage:blocked_count={blocked_count}")
        if needs_follow_up_count:
            runbook_blockers.append(f"runbook_evidence_coverage:needs_follow_up_count={needs_follow_up_count}")
        if dismissed_count:
            runbook_blockers.append(f"runbook_evidence_coverage:dismissed_count={dismissed_count}")
        if submitted_or_review_count:
            runbook_blockers.append(f"runbook_evidence_coverage:submitted_or_review_count={submitted_or_review_count}")
        if package_count and resolved_count < package_count:
            runbook_blockers.append(f"runbook_evidence_coverage:resolved_count={resolved_count}/{package_count}")
        if not coverage_ready:
            runbook_blockers.append(f"runbook_evidence_coverage_status:{coverage_status}")

        runbook_items = [
            item
            for item in [
                *(
                    runbook_evidence_coverage.get("missing_items", [])
                    if isinstance(runbook_evidence_coverage.get("missing_items"), list)
                    else []
                ),
                *(
                    runbook_evidence_coverage.get("blocked_items", [])
                    if isinstance(runbook_evidence_coverage.get("blocked_items"), list)
                    else []
                ),
            ]
            if isinstance(item, dict)
        ]
        runbook_external_dependency_required = any(bool(item.get("external_dependency_required")) for item in runbook_items)
        for blocker in runbook_blockers:
            append_action(
                action_key="resolve_runbook_evidence_coverage",
                title="Record or resolve Phase 71J evidence for every Phase 71I runbook package",
                owner="delivery_operator",
                priority=35,
                source_blocker=blocker,
                target=str(runbook_evidence_coverage.get("next_focus") or "record_runbook_evidence"),
                target_console="server_operator_console",
                required_endpoint="/api/v1/commercial-operations/production-closed-loop/delivery-audit/blocker-runbook-packages/evidence-records",
                verification_commands=["python scripts/check_production_closed_loop.py --report-only"],
                evidence_requirements=[
                    "latest Phase 71J evidence for every Phase 71I runbook package",
                    "operator evidence status must be resolved before readiness refresh",
                ],
                external_dependency_required=runbook_external_dependency_required,
                can_be_resolved_by_ui=True,
            )

        runbook_evidence_readiness_refresh_required = False
        if package_count and coverage_ready:
            evidence_records = runbook_evidence_coverage.get("evidence_records")
            records = evidence_records.get("records", []) if isinstance(evidence_records, dict) else []
            operation_ids = self._dedupe_texts(
                [
                    str(record.get("operation_id") or "")
                    for record in records
                    if isinstance(record, dict) and str(record.get("operation_id") or "").strip()
                ]
            )
            refresh_satisfied = False
            for operation_id in operation_ids[:10]:
                try:
                    operation = await self.require_operation(workspace_id=workspace_id, operation_id=UUID(operation_id))
                except ValueError:
                    continue
                metadata = operation.operation_metadata if isinstance(operation.operation_metadata, dict) else {}
                latest_refresh = metadata.get("production_closed_loop_delivery_audit_blocker_runbook_evidence_readiness_refresh_latest")
                if not isinstance(latest_refresh, dict):
                    continue
                latest_package_count = int(latest_refresh.get("package_count") or 0)
                latest_resolved_count = int(latest_refresh.get("resolved_count") or 0)
                latest_status = str(latest_refresh.get("refresh_status") or "")
                if (
                    latest_status in {"resolved_runbook_evidence_readiness_refreshed", "no_runbook_evidence_required_readiness_refreshed"}
                    and latest_package_count == package_count
                    and latest_resolved_count >= package_count
                ):
                    refresh_satisfied = True
                    break
            runbook_evidence_readiness_refresh_required = not refresh_satisfied
            if runbook_evidence_readiness_refresh_required:
                append_action(
                    action_key="refresh_runbook_evidence_readiness",
                    title="Run the Phase 71L readiness refresh after resolved runbook evidence",
                    owner="delivery_operator",
                    priority=30,
                    source_blocker="runbook_evidence_readiness_refresh_required",
                    target="production delivery audit runbook evidence",
                    target_console="server_operator_console",
                    required_endpoint="/api/v1/commercial-operations/production-closed-loop/delivery-audit/blocker-runbook-packages/evidence-coverage/readiness-refresh",
                    verification_commands=["python scripts/check_production_closed_loop.py --report-only"],
                    evidence_requirements=["all Phase 71K packages resolved before refresh", "operator_confirmed=true"],
                    can_be_resolved_by_ui=True,
                )

        next_actions = sorted(actions_by_key.values(), key=lambda item: (int(item.get("priority") or 999), str(item.get("action_key") or "")))
        blocking_reasons = self._dedupe_texts(blocking_reasons)
        audit_status = "audit_action_plan_clear" if not next_actions and coverage_ready else "audit_action_plan_blocked"
        first_action = next_actions[0] if next_actions else None

        return self._json_safe_dict(
            {
                "workspace_id": workspace_id,
                "audit_status": audit_status,
                "acceptance_status": str(acceptance_summary.get("acceptance_status") or "unknown"),
                "completion_percent": int(acceptance_summary.get("completion_percent") or 0),
                "next_focus": str((first_action or {}).get("action_key") or runbook_evidence_coverage.get("next_focus") or acceptance_summary.get("next_focus") or "production_closed_loop_audit"),
                "blocker_count": len(blocking_reasons),
                "next_action_count": len(next_actions),
                "runbook_evidence_coverage_ready": coverage_ready,
                "runbook_evidence_readiness_refresh_required": runbook_evidence_readiness_refresh_required,
                "blocking_reasons": blocking_reasons,
                "next_actions": next_actions,
                "first_action": first_action,
                "acceptance_summary": acceptance_summary,
                "clearance_plan": clearance_plan,
                "runbook_evidence_coverage": runbook_evidence_coverage,
                "acceptance_gates": [
                    "production_closed_loop_delivery_audit",
                    "production_closed_loop_delivery_audit_blocker_clearance_plan",
                    "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "operator_visible_audit_next_actions_required_before_100_percent_claim",
                ],
                "boundaries": [
                    "delivery_audit_next_action_plan_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_bypass_operator_approval",
                ],
                "generated_at": datetime.now(UTC),
                "metadata": {
                    "phase": "71O",
                    "contract": "production_closed_loop_delivery_audit_next_action_plan",
                    "source_contract": "production_closed_loop_delivery_audit_blocker_clearance_plan",
                    "runbook_coverage_contract": "production_closed_loop_delivery_audit_blocker_runbook_evidence_coverage",
                    "acceptance_contract": "production_closed_loop_acceptance_summary",
                    "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
            }
        )

    async def get_production_closed_loop_delivery_audit_operator_queue(
        self,
        *,
        workspace_id: str,
        platform: str | None = None,
        force_metric_due: bool = False,
        limit: int = 25,
        scan_limit: int = 50,
        work_order_limit: int = 200,
        evidence_limit: int = 200,
    ) -> dict[str, Any]:
        """Group production delivery audit next actions into an owner-routed operator queue."""

        source_plan = await self.get_production_closed_loop_delivery_audit_next_action_plan(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
            limit=limit,
            scan_limit=scan_limit,
            work_order_limit=work_order_limit,
            evidence_limit=evidence_limit,
        )
        queue_record_list = await self.list_production_closed_loop_delivery_audit_operator_queue_records(
            workspace_id=workspace_id,
            limit=500,
        )
        queue_records = [
            item
            for item in queue_record_list.get("records", [])
            if isinstance(item, dict)
        ]
        records_by_queue_key: dict[str, list[dict[str, Any]]] = {}
        records_by_action_key: dict[str, list[dict[str, Any]]] = {}
        for record in queue_records:
            record_queue_key = str(record.get("queue_key") or "").strip()
            record_action_key = str(record.get("action_key") or "").strip()
            if record_queue_key:
                records_by_queue_key.setdefault(record_queue_key, []).append(record)
            if record_action_key:
                records_by_action_key.setdefault(record_action_key, []).append(record)

        owner_labels = {
            "server_operator": "Server operator",
            "delivery_operator": "Delivery operator",
            "operation_owner": "Operation owner",
            "operation_manager": "Operation manager",
            "customer_machine_operator": "Customer-machine operator",
        }
        owner_console_defaults = {
            "server_operator": "admin_dashboard",
            "delivery_operator": "admin_dashboard",
            "operation_owner": "worker_console",
            "operation_manager": "worker_console",
            "customer_machine_operator": "worker_console",
        }

        def resolution_profile(action: dict[str, Any]) -> dict[str, Any]:
            action_key = str(action.get("action_key") or "")
            required_endpoint = str(action.get("required_endpoint") or "").strip()
            owner = str(action.get("owner") or "operator")
            target_console = str(action.get("target_console") or "").strip()
            external_dependency_required = bool(action.get("external_dependency_required"))
            can_be_resolved_by_ui = bool(action.get("can_be_resolved_by_ui"))

            endpoint_method = "GET"
            resolution_mode = "manual_review"
            primary_label = "Review action"
            ui_anchor = "commercial-delivery-audit-next-action-plan"
            operator_next_step = "Review the blocker, gather evidence, then use the referenced workflow control."

            if action_key == "configure_real_openclaw_provider":
                resolution_mode = "external_provider_configuration"
                primary_label = "Open provider diagnostics"
                ui_anchor = "client-openclaw-provider-diagnostics"
                operator_next_step = (
                    "Configure the real customer-machine OpenClaw provider and verify diagnostics; "
                    "this cannot be resolved by the server UI alone."
                )
            elif action_key == "resolve_runbook_evidence_coverage":
                endpoint_method = "POST"
                resolution_mode = "record_runbook_evidence"
                primary_label = "Record runbook evidence"
                ui_anchor = "commercial-delivery-audit-runbooks"
                operator_next_step = "Record or resolve Phase 71J evidence for every Phase 71I runbook package."
            elif action_key == "refresh_runbook_evidence_readiness":
                endpoint_method = "POST"
                resolution_mode = "refresh_runbook_readiness"
                primary_label = "Refresh runbook readiness"
                ui_anchor = "commercial-delivery-audit-runbook-coverage-list"
                operator_next_step = "Run the Phase 71L readiness refresh after all runbook packages are resolved."
            elif action_key == "clear_operation_project_blockers":
                resolution_mode = "open_operation_project"
                primary_label = "Open project workbench"
                ui_anchor = "client-project-workbench"
                operator_next_step = "Open the blocked operation project and complete the next controlled project action."
            elif action_key.startswith("clear_acceptance_gate:"):
                resolution_mode = "clear_acceptance_gate"
                primary_label = "Open acceptance gate"
                ui_anchor = "commercial-acceptance-summary-panel"
                operator_next_step = "Clear the named acceptance gate through the existing review-gated project workflow."

            if required_endpoint.endswith("/evidence-records") or required_endpoint.endswith("/readiness-refresh"):
                endpoint_method = "POST"
            elif "/next-action" in required_endpoint or required_endpoint.endswith("/provider-diagnostics"):
                endpoint_method = "GET"

            primary_console = target_console or owner_console_defaults.get(owner, "operator_console")
            resolution_status = "external_dependency_required" if external_dependency_required and not can_be_resolved_by_ui else "operator_action_required"
            if not action_key:
                resolution_status = "unknown"

            return {
                "resolution_mode": resolution_mode,
                "resolution_status": resolution_status,
                "primary_console": primary_console,
                "primary_label": primary_label,
                "ui_anchor": ui_anchor,
                "endpoint_method": endpoint_method,
                "endpoint_path": required_endpoint or None,
                "operator_next_step": operator_next_step,
                "blocked_by_external_dependency": external_dependency_required and not can_be_resolved_by_ui,
            }

        queue_items: list[dict[str, Any]] = []
        for index, action in enumerate(source_plan.get("next_actions", []), start=1):
            if not isinstance(action, dict):
                continue
            action_key = str(action.get("action_key") or f"action_{index}")
            owner = str(action.get("owner") or "operator")
            queue_key = f"{owner}:{action_key}"
            profile = resolution_profile(action)
            matching_records = records_by_queue_key.get(queue_key, [])
            if not matching_records:
                matching_records = records_by_action_key.get(action_key, [])
            latest_record = matching_records[0] if matching_records else None
            queue_items.append(
                self._json_safe_dict(
                    {
                        "queue_key": queue_key,
                        "action_key": action_key,
                        "title": str(action.get("title") or action_key),
                        "owner": owner,
                        "priority": int(action.get("priority") or 999),
                        **profile,
                        "source_blockers": [
                            str(item)
                            for item in action.get("source_blockers", [])
                            if isinstance(item, str) and item.strip()
                        ],
                        "evidence_requirements": [
                            str(item)
                            for item in action.get("evidence_requirements", [])
                            if isinstance(item, str) and item.strip()
                        ],
                        "verification_commands": [
                            str(item)
                            for item in action.get("verification_commands", [])
                            if isinstance(item, str) and item.strip()
                        ],
                        "external_dependency_required": bool(action.get("external_dependency_required")),
                        "can_be_resolved_by_ui": bool(action.get("can_be_resolved_by_ui")),
                        "operator_approval_required": bool(action.get("operator_approval_required", True)),
                        "record_count": len(matching_records),
                        "latest_record_id": latest_record.get("record_id") if latest_record else None,
                        "latest_record_status": latest_record.get("record_status") if latest_record else None,
                        "latest_record_summary": latest_record.get("evidence_summary") if latest_record else None,
                        "latest_record_created_at": latest_record.get("created_at") if latest_record else None,
                        "latest_record_operator_confirmed": bool(latest_record.get("operator_confirmed")) if latest_record else False,
                        "boundaries": self._dedupe_texts(
                            [
                                *[
                                    str(item)
                                    for item in action.get("boundaries", [])
                                    if isinstance(item, str) and item.strip()
                                ],
                                "delivery_audit_operator_queue_only_no_external_execution",
                                "does_not_execute_target_endpoint",
                                "does_not_bypass_operator_approval",
                            ]
                        ),
                    }
                )
            )

        grouped: dict[str, list[dict[str, Any]]] = {}
        for item in queue_items:
            grouped.setdefault(str(item.get("owner") or "operator"), []).append(item)

        owner_groups: list[dict[str, Any]] = []
        for owner, items in grouped.items():
            sorted_items = sorted(items, key=lambda item: (int(item.get("priority") or 999), str(item.get("action_key") or "")))
            ui_resolvable_count = sum(1 for item in sorted_items if bool(item.get("can_be_resolved_by_ui")))
            external_dependency_count = sum(1 for item in sorted_items if bool(item.get("external_dependency_required")))
            queue_status = (
                "external_dependency_required"
                if external_dependency_count and external_dependency_count >= len(sorted_items) and not ui_resolvable_count
                else "operator_action_required"
            )
            owner_groups.append(
                self._json_safe_dict(
                    {
                        "owner": owner,
                        "owner_label": owner_labels.get(owner, owner.replace("_", " ").title()),
                        "queue_status": queue_status,
                        "top_priority": int(sorted_items[0].get("priority") or 999) if sorted_items else 999,
                        "action_count": len(sorted_items),
                        "ui_resolvable_count": ui_resolvable_count,
                        "external_dependency_count": external_dependency_count,
                        "items": sorted_items,
                    }
                )
            )
        owner_groups = sorted(owner_groups, key=lambda group: (int(group.get("top_priority") or 999), str(group.get("owner") or "")))
        first_item = owner_groups[0]["items"][0] if owner_groups and owner_groups[0].get("items") else None
        external_dependency_count = sum(1 for item in queue_items if bool(item.get("external_dependency_required")))
        ui_resolvable_count = sum(1 for item in queue_items if bool(item.get("can_be_resolved_by_ui")))
        queue_status = "operator_queue_clear" if not queue_items else "operator_action_required"

        return self._json_safe_dict(
            {
                "workspace_id": workspace_id,
                "queue_status": queue_status,
                "audit_status": str(source_plan.get("audit_status") or "unknown"),
                "acceptance_status": str(source_plan.get("acceptance_status") or "unknown"),
                "completion_percent": int(source_plan.get("completion_percent") or 0),
                "owner_count": len(owner_groups),
                "action_count": len(queue_items),
                "ui_resolvable_count": ui_resolvable_count,
                "external_dependency_count": external_dependency_count,
                "next_owner": str((first_item or {}).get("owner") or "") or None,
                "first_item": first_item,
                "owner_groups": owner_groups,
                "source_plan": source_plan,
                "acceptance_gates": [
                    "production_closed_loop_delivery_audit_next_action_plan",
                    "operator_queue_visible_before_100_percent_claim",
                    "operator_approval_required_before_resolution_actions",
                ],
                "boundaries": [
                    "delivery_audit_operator_queue_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_bypass_operator_approval",
                ],
                "generated_at": datetime.now(UTC),
                "metadata": {
                    "phase": "71P",
                    "contract": "production_closed_loop_delivery_audit_operator_queue",
                    "source_contract": "production_closed_loop_delivery_audit_next_action_plan",
                    "record_contract": "production_closed_loop_delivery_audit_operator_queue_record_list",
                    "platform_filter": platform.strip().lower() if platform and platform.strip() else None,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
            }
        )

    async def record_production_closed_loop_delivery_audit_operator_queue_record(
        self,
        *,
        workspace_id: str,
        action_key: str,
        queue_key: str | None = None,
        owner: str | None = None,
        operation_id: UUID | None = None,
        record_status: str = "in_progress",
        operator_confirmed: bool = False,
        evidence_links: list[dict[str, Any]] | None = None,
        evidence_summary: str | None = None,
        operator_notes: str | None = None,
        platform: str | None = None,
        force_metric_due: bool = False,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Record operator status/evidence for a delivery audit queue item."""

        clean_action_key = str(action_key or "").strip()
        clean_queue_key = str(queue_key or "").strip() or None
        clean_owner = str(owner or "").strip() or None
        if not clean_action_key:
            raise ValueError("action_key is required")
        clean_status = str(record_status or "in_progress").strip().lower()
        allowed_statuses = {"queued", "in_progress", "blocked", "resolved", "needs_follow_up", "dismissed"}
        if clean_status not in allowed_statuses:
            raise ValueError("record_status must be queued, in_progress, blocked, resolved, needs_follow_up, or dismissed")
        clean_evidence_links = [dict(item) for item in evidence_links or [] if isinstance(item, dict)]
        clean_summary = str(evidence_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        if clean_status == "resolved" and not operator_confirmed:
            raise ValueError("operator_confirmed is required for resolved operator queue records")
        if clean_status == "resolved" and not clean_evidence_links and not clean_summary:
            raise ValueError("evidence_links or evidence_summary is required when resolving an operator queue item")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"operator queue record payload contains sensitive key or value: {sensitive_paths[0]}")

        queue = await self.get_production_closed_loop_delivery_audit_operator_queue(
            workspace_id=workspace_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        queue_items = [
            item
            for group in queue.get("owner_groups", [])
            if isinstance(group, dict)
            for item in group.get("items", [])
            if isinstance(item, dict)
        ]
        queue_item = next(
            (
                item
                for item in queue_items
                if str(item.get("action_key") or "") == clean_action_key
                and (not clean_queue_key or str(item.get("queue_key") or "") == clean_queue_key)
                and (not clean_owner or str(item.get("owner") or "") == clean_owner)
            ),
            None,
        )
        if queue_item is None:
            raise ValueError("action_key is not present in the current delivery audit operator queue")
        clean_queue_key = str(queue_item.get("queue_key") or clean_queue_key or "")
        clean_owner = str(queue_item.get("owner") or clean_owner or "operator")

        anchor_operation_id = operation_id
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before recording an operator queue item")
            anchor_operation_id = operations[0].id
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)

        now = datetime.now(UTC)
        record = self._json_safe_dict(
            {
                "record_id": str(uuid4()),
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "queue_key": clean_queue_key,
                "action_key": clean_action_key,
                "owner": clean_owner,
                "record_status": clean_status,
                "operator_confirmed": operator_confirmed,
                "resolution_mode": str(queue_item.get("resolution_mode") or "manual_review"),
                "resolution_status": str(queue_item.get("resolution_status") or "operator_action_required"),
                "primary_console": str(queue_item.get("primary_console") or "operator_console"),
                "primary_label": str(queue_item.get("primary_label") or "Review queue"),
                "endpoint_method": queue_item.get("endpoint_method"),
                "endpoint_path": queue_item.get("endpoint_path"),
                "blocked_by_external_dependency": bool(queue_item.get("blocked_by_external_dependency")),
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "verification_commands": [
                    str(item)
                    for item in queue_item.get("verification_commands", [])
                    if isinstance(item, str) and item.strip()
                ],
                "evidence_requirements": [
                    str(item)
                    for item in queue_item.get("evidence_requirements", [])
                    if isinstance(item, str) and item.strip()
                ],
                "contract_snapshot": {
                    "contract": "production_closed_loop_delivery_audit_operator_queue",
                    "queue_status": queue.get("queue_status"),
                    "audit_status": queue.get("audit_status"),
                    "acceptance_status": queue.get("acceptance_status"),
                    "completion_percent": queue.get("completion_percent"),
                    "queue_item": {
                        "queue_key": queue_item.get("queue_key"),
                        "action_key": queue_item.get("action_key"),
                        "title": queue_item.get("title"),
                        "owner": queue_item.get("owner"),
                        "resolution_mode": queue_item.get("resolution_mode"),
                        "resolution_status": queue_item.get("resolution_status"),
                        "primary_console": queue_item.get("primary_console"),
                        "endpoint_method": queue_item.get("endpoint_method"),
                        "endpoint_path": queue_item.get("endpoint_path"),
                        "source_blockers": queue_item.get("source_blockers", []),
                    },
                },
                "boundary_checks": [
                    "delivery_audit_operator_queue_contract_matched",
                    "server_side_external_execution_false",
                    "operator_approval_boundary_preserved",
                    "target_endpoint_not_executed",
                    "secret_values_not_required_or_stored",
                ],
                "created_by": created_by,
                "created_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "71Q",
                    "contract": "production_closed_loop_delivery_audit_operator_queue_record",
                    "source_contract": "production_closed_loop_delivery_audit_operator_queue",
                    "workspace_queue_record": operation_id is None,
                    "platform": platform,
                    "force_metric_due": force_metric_due,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_audit_operator_queue_records_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_submit_comfyui_prompt",
                    "does_not_store_or_print_secrets",
                    "does_not_configure_provider_or_secrets",
                    "does_not_bypass_operator_approval",
                ],
            }
        )

        operation_metadata = dict(operation.operation_metadata or {})
        history = self._production_closed_loop_delivery_audit_operator_queue_record_history(operation)
        history = [*history, record][-150:]
        operation_metadata["production_closed_loop_delivery_audit_operator_queue_records"] = history
        operation_metadata["production_closed_loop_delivery_audit_operator_queue_latest_record"] = record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)
        return record

    async def list_production_closed_loop_delivery_audit_operator_queue_records(
        self,
        *,
        workspace_id: str,
        queue_key: str | None = None,
        action_key: str | None = None,
        owner: str | None = None,
        operation_id: UUID | None = None,
        record_status: str | None = None,
        limit: int = 50,
    ) -> dict[str, Any]:
        """List recorded delivery audit operator queue records across a workspace."""

        clean_queue_key = str(queue_key or "").strip() or None
        clean_action_key = str(action_key or "").strip() or None
        clean_owner = str(owner or "").strip() or None
        clean_status = str(record_status or "").strip().lower() or None
        clean_limit = max(1, min(int(limit or 50), 200))
        if operation_id is not None:
            operations = [await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)]
        else:
            operations = await self.list_operations(workspace_id=workspace_id, limit=500)

        records: list[dict[str, Any]] = []
        for operation in operations:
            for record in self._production_closed_loop_delivery_audit_operator_queue_record_history(operation):
                if clean_queue_key and str(record.get("queue_key") or "") != clean_queue_key:
                    continue
                if clean_action_key and str(record.get("action_key") or "") != clean_action_key:
                    continue
                if clean_owner and str(record.get("owner") or "") != clean_owner:
                    continue
                if clean_status and str(record.get("record_status") or "").lower() != clean_status:
                    continue
                records.append(record)

        records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
        records = records[:clean_limit]
        latest_record = records[0] if records else None
        status_counts: dict[str, int] = {}
        operator_confirmed_count = 0
        for record in records:
            status = str(record.get("record_status") or "unknown")
            status_counts[status] = status_counts.get(status, 0) + 1
            if bool(record.get("operator_confirmed")):
                operator_confirmed_count += 1

        return {
            "workspace_id": workspace_id,
            "record_count": len(records),
            "latest_record": latest_record,
            "records": records,
            "status_counts": status_counts,
            "operator_confirmed_count": operator_confirmed_count,
            "acceptance_gates": [
                "production_closed_loop_delivery_audit_operator_queue",
                "operator_queue_records_are_operator_supplied",
                "operator_confirmation_required_for_resolved_queue_records",
                "queue_records_do_not_execute_resolution_endpoint",
            ],
            "boundaries": [
                "delivery_audit_operator_queue_records_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_submit_comfyui_prompt",
                "does_not_store_or_print_secrets",
                "does_not_configure_provider_or_secrets",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "71Q",
                "contract": "production_closed_loop_delivery_audit_operator_queue_record_list",
                "source_contract": "production_closed_loop_delivery_audit_operator_queue_record",
                "storage": (
                    "commercial_operations.operation_metadata."
                    "production_closed_loop_delivery_audit_operator_queue_records"
                ),
                "queue_key_filter": clean_queue_key,
                "action_key_filter": clean_action_key,
                "owner_filter": clean_owner,
                "operation_filter": str(operation_id) if operation_id else None,
                "status_filter": clean_status,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    async def get_production_closed_loop_delivery_audit_openclaw_provider_handoff(
        self,
        *,
        workspace_id: str,
    ) -> dict[str, Any]:
        """Build a sanitized operator handoff for configuring the real OpenClaw provider."""

        settings = get_settings()
        provider_readiness = await self._get_server_acceptance_openclaw_provider_readiness(
            workspace_id=workspace_id,
        )
        config_findings = settings.production_config_findings(require_production=True)
        finding_by_key = {
            str(item.get("key") or ""): item
            for item in config_findings
            if isinstance(item, dict) and str(item.get("key") or "").strip()
        }

        def secret_state(value: str) -> str:
            return "<set>" if settings._secret_state(value) == "<set>" else settings._secret_state(value)

        def config_item(
            *,
            key: str,
            required_state: str,
            current_state: str,
            configured: bool,
            secret: bool,
            operator_action: str,
            evidence_requirement: str,
            verification_command: str | None = None,
        ) -> dict[str, Any]:
            finding = finding_by_key.get(key)
            blocking = bool(finding and finding.get("severity") == "error") or not configured
            return self._json_safe_dict(
                {
                    "config_key": key,
                    "required_state": required_state,
                    "current_state": current_state,
                    "configured": configured,
                    "secret": secret,
                    "blocking": blocking,
                    "operator_action": operator_action,
                    "evidence_requirement": evidence_requirement,
                    "verification_command": verification_command,
                    "boundaries": [
                        "openclaw_provider_handoff_only_no_secret_storage",
                        "does_not_mutate_environment",
                        "does_not_restart_services",
                        "does_not_execute_openclaw_or_playwright",
                        "does_not_publish_or_control_real_accounts",
                    ],
                }
            )

        openclaw_provider = str(settings.openclaw_provider or "").strip()
        worker_provider = str(settings.worker_client_openclaw_provider or "").strip()
        worker_base_url = str(settings.worker_client_openclaw_base_url or "").strip()
        worker_api_key = str(settings.worker_client_openclaw_api_key or "")
        config_items = [
            config_item(
                key="OPENCLAW_PROVIDER",
                required_state="worker_runtime",
                current_state=settings._safe_actual(openclaw_provider),
                configured=openclaw_provider.lower() not in {"", "mock", "disabled"},
                secret=False,
                operator_action="Set OPENCLAW_PROVIDER to worker_runtime on the AI server.",
                evidence_requirement="Sanitized production config output showing OPENCLAW_PROVIDER is no longer mock or disabled.",
                verification_command="python scripts/check_production_config.py --require-production",
            ),
            config_item(
                key="WORKER_CLIENT_OPENCLAW_ENABLED",
                required_state="true",
                current_state=str(bool(settings.worker_client_openclaw_enabled)).lower(),
                configured=bool(settings.worker_client_openclaw_enabled),
                secret=False,
                operator_action="Enable the customer-machine OpenClaw provider in the worker runtime.",
                evidence_requirement="Worker runtime diagnostics showing OpenClaw is enabled.",
                verification_command="python scripts/check_openclaw_provider.py --base-url http://127.0.0.1:9100 --report-only",
            ),
            config_item(
                key="WORKER_CLIENT_OPENCLAW_PROVIDER",
                required_state="openclaw_http",
                current_state=settings._safe_actual(worker_provider),
                configured=worker_provider.lower() in {"openclaw_http", "http", "openclaw"},
                secret=False,
                operator_action="Set WORKER_CLIENT_OPENCLAW_PROVIDER to openclaw_http on the customer-machine worker.",
                evidence_requirement="Provider diagnostics showing provider=openclaw_http and mock=false.",
                verification_command="python scripts/check_openclaw_provider.py --base-url http://127.0.0.1:9100 --report-only",
            ),
            config_item(
                key="WORKER_CLIENT_OPENCLAW_BASE_URL",
                required_state="real OpenClaw adapter base URL",
                current_state="<set>" if worker_base_url else "<empty>",
                configured=bool(worker_base_url),
                secret=False,
                operator_action="Configure WORKER_CLIENT_OPENCLAW_BASE_URL to the real local or LAN OpenClaw HTTP adapter.",
                evidence_requirement="Provider diagnostics showing base_url_configured=true; do not include the full URL if it is sensitive.",
                verification_command="python scripts/check_openclaw_provider.py --base-url http://127.0.0.1:9100 --report-only",
            ),
            config_item(
                key="WORKER_CLIENT_OPENCLAW_API_KEY",
                required_state="non-placeholder adapter API key",
                current_state=secret_state(worker_api_key),
                configured=settings._secret_state(worker_api_key) == "<set>",
                secret=True,
                operator_action="Configure WORKER_CLIENT_OPENCLAW_API_KEY in the worker environment or service secret store.",
                evidence_requirement="Provider diagnostics showing api_key_configured=true; never paste the key into the evidence record.",
                verification_command="python scripts/check_openclaw_provider.py --base-url http://127.0.0.1:9100 --report-only",
            ),
        ]

        missing_config_count = sum(1 for item in config_items if item.get("blocking"))
        ready = bool(provider_readiness.get("ready"))
        verification_commands = [
            "python scripts/check_production_config.py --require-production",
            "python scripts/check_openclaw_provider.py --base-url http://127.0.0.1:9100",
            "python scripts/check_production_closed_loop.py --api-base-url http://127.0.0.1:8000 --worker-base-url http://127.0.0.1:9100 --workspace-id production-workspace --platform douyin --force-metric-due --report-only",
        ]
        manual_steps = [
            "Set the server and customer-machine OpenClaw provider environment variables outside the application UI.",
            "Restart only the affected API and worker processes after the operator has saved the environment changes.",
            "Run the provider diagnostics and smoke checks without clicking publish or controlling a real account.",
            "Record sanitized Phase 71J runbook evidence after the provider reports mock=false and real_publish_submit=true.",
            "Run the production closed-loop audit again and continue with remaining acceptance gates only after the provider gate is ready.",
        ]
        evidence_requirements = [
            "Sanitized production config output with no OPENCLAW_PROVIDER or WORKER_CLIENT_OPENCLAW_PROVIDER errors.",
            "OpenClaw provider diagnostics showing configured=true and mock=false.",
            "OpenClaw health showing reachable=true, enabled=true, and mock=false.",
            "OpenClaw capabilities showing real_publish_submit=true and publish_submit_guarded=true.",
            "No secrets, cookies, verification codes, or full API keys in evidence.",
        ]
        if ready:
            handoff_status = "openclaw_provider_handoff_ready_for_evidence"
            next_focus = "record_resolved_provider_runbook_evidence"
        elif missing_config_count:
            handoff_status = "openclaw_provider_handoff_configuration_required"
            next_focus = next(
                str(item.get("operator_action") or "")
                for item in config_items
                if item.get("blocking")
            )
        else:
            handoff_status = "openclaw_provider_handoff_smoke_verification_required"
            next_focus = "run_openclaw_provider_readiness_smoke"

        return self._json_safe_dict(
            {
                "workspace_id": workspace_id,
                "handoff_status": handoff_status,
                "readiness_status": str(provider_readiness.get("readiness_status") or "unknown"),
                "ready": ready,
                "provider": str(provider_readiness.get("provider") or openclaw_provider or "unknown"),
                "mock": bool(provider_readiness.get("mock", True)),
                "worker_id": provider_readiness.get("worker_id"),
                "worker_name": provider_readiness.get("worker_name"),
                "required_config_count": len(config_items),
                "missing_config_count": missing_config_count,
                "verification_count": len(verification_commands),
                "next_focus": next_focus,
                "config_items": config_items,
                "verification_commands": verification_commands,
                "manual_steps": manual_steps,
                "evidence_requirements": evidence_requirements,
                "restart_boundaries": [
                    "operator_must_restart_affected_runtime_after_environment_change",
                    "server_does_not_restart_services_from_this_endpoint",
                    "do_not_restart_comfyui_or_model_download_processes_for_openclaw_config_only",
                ],
                "provider_readiness": provider_readiness,
                "production_config_findings": config_findings,
                "acceptance_gates": [
                    "server_acceptance_openclaw_provider_readiness_gate",
                    "production_config_openclaw_findings_are_mapped_to_operator_handoff",
                    "real_provider_requires_external_operator_configuration",
                    "sanitized_evidence_required_before_gate_clearance",
                ],
                "boundaries": [
                    "openclaw_provider_handoff_only_no_secret_storage",
                    "does_not_mutate_environment",
                    "does_not_restart_services",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_collect_credentials_or_verification_codes",
                    "does_not_bypass_operator_approval",
                ],
                "generated_at": datetime.now(UTC),
                "metadata": {
                    "phase": "71R",
                    "contract": "production_closed_loop_delivery_audit_openclaw_provider_handoff",
                    "source_contract": "server_acceptance_openclaw_provider_readiness_gate",
                    "config_contract": "production_config_guard",
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                    "secret_values_redacted": True,
                },
            }
        )

    async def record_production_closed_loop_delivery_action_evidence(
        self,
        *,
        workspace_id: str,
        gate_key: str,
        action_key: str | None = None,
        operation_id: UUID | None = None,
        evidence_status: str = "submitted",
        operator_confirmed: bool = False,
        evidence_links: list[dict[str, Any]] | None = None,
        evidence_summary: str | None = None,
        operator_notes: str | None = None,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Record manual evidence for a delivery action package without executing the target action."""

        clean_gate_key = str(gate_key or "").strip()
        if not clean_gate_key:
            raise ValueError("gate_key is required")
        clean_status = str(evidence_status or "submitted").strip().lower()
        allowed_statuses = {"submitted", "blocked", "resolved", "needs_follow_up", "dismissed"}
        if clean_status not in allowed_statuses:
            raise ValueError("evidence_status must be submitted, blocked, resolved, needs_follow_up, or dismissed")
        if clean_status in {"submitted", "resolved"} and not operator_confirmed:
            raise ValueError("operator_confirmed is required for submitted and resolved delivery evidence")

        clean_evidence_links = [dict(item) for item in evidence_links or [] if isinstance(item, dict)]
        clean_summary = str(evidence_summary or "").strip() or None
        clean_notes = str(operator_notes or "").strip() or None
        if clean_status == "resolved" and not clean_evidence_links and not clean_summary:
            raise ValueError("evidence_links or evidence_summary is required when resolving a delivery action package")
        sensitive_paths = self._sensitive_action_audit_paths(
            {
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "metadata": metadata or {},
            }
        )
        if sensitive_paths:
            raise ValueError(f"delivery evidence payload contains sensitive key or value: {sensitive_paths[0]}")

        delivery_packages = await self.get_production_closed_loop_delivery_action_packages(
            workspace_id=workspace_id,
            platform=(metadata or {}).get("platform") if isinstance((metadata or {}).get("platform"), str) else None,
            force_metric_due=bool((metadata or {}).get("force_metric_due", False)),
        )
        gate_package = next(
            (
                package
                for package in delivery_packages.get("gate_packages", [])
                if isinstance(package, dict) and str(package.get("gate_key") or "") == clean_gate_key
            ),
            None,
        )
        if gate_package is None:
            raise ValueError("gate_key is not present in the current delivery action package contract")
        action_steps = [step for step in gate_package.get("action_steps", []) if isinstance(step, dict)]
        clean_action_key = str(action_key or gate_package.get("recommended_action_key") or "").strip()
        if not clean_action_key and action_steps:
            clean_action_key = str(action_steps[0].get("action_key") or "").strip()
        if not clean_action_key:
            clean_action_key = f"{clean_gate_key}:workspace"
        matched_step = next((step for step in action_steps if str(step.get("action_key") or "") == clean_action_key), None)
        if matched_step is None and action_steps:
            raise ValueError("action_key is not present in the current delivery action package contract")

        anchor_operation_id = operation_id
        if anchor_operation_id is None and matched_step and matched_step.get("operation_id"):
            anchor_operation_id = UUID(str(matched_step["operation_id"]))
        if anchor_operation_id is None:
            operations = await self.list_operations(workspace_id=workspace_id, limit=1)
            if not operations:
                raise ValueError("At least one operation is required before recording delivery evidence")
            anchor_operation_id = operations[0].id
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=anchor_operation_id)
        if operation_id is not None and matched_step and matched_step.get("operation_id"):
            if str(matched_step["operation_id"]) != str(operation_id):
                raise ValueError("operation_id must match the delivery action step operation_id")

        now = datetime.now(UTC)
        record = self._json_safe_dict(
            {
                "evidence_record_id": str(uuid4()),
                "workspace_id": workspace_id,
                "operation_id": str(anchor_operation_id),
                "gate_key": clean_gate_key,
                "action_key": clean_action_key,
                "evidence_status": clean_status,
                "operator_confirmed": operator_confirmed,
                "target_console": str(gate_package.get("target_console") or "server_operator_console"),
                "action_status": str(gate_package.get("action_status") or "ready_for_operator_review"),
                "evidence_links": clean_evidence_links,
                "evidence_summary": clean_summary,
                "operator_notes": clean_notes,
                "contract_snapshot": {
                    "contract": "production_closed_loop_delivery_action_packages",
                    "delivery_status": delivery_packages.get("delivery_status"),
                    "action_package_status": delivery_packages.get("action_package_status"),
                    "next_focus": delivery_packages.get("next_focus"),
                    "gate_package": {
                        "gate_key": gate_package.get("gate_key"),
                        "gate_status": gate_package.get("gate_status"),
                        "title": gate_package.get("title"),
                        "owner": gate_package.get("owner"),
                        "target_console": gate_package.get("target_console"),
                        "action_status": gate_package.get("action_status"),
                        "blocking_reasons": gate_package.get("blocking_reasons", []),
                    },
                    "action_step": matched_step or {},
                },
                "boundary_checks": [
                    "delivery_action_package_contract_matched",
                    "server_side_external_execution_false",
                    "operator_approval_boundary_preserved",
                    "external_execution_not_performed",
                ],
                "created_by": created_by,
                "created_at": now.isoformat(),
                "metadata": {
                    **(metadata or {}),
                    "phase": "70X",
                    "contract": "production_closed_loop_delivery_action_evidence",
                    "source_contract": "production_closed_loop_delivery_action_packages",
                    "workspace_gate_record": operation_id is None,
                    "server_side_external_execution": False,
                    "actual_publish_performed": False,
                },
                "boundaries": [
                    "delivery_action_evidence_only_no_external_execution",
                    "does_not_execute_target_endpoint",
                    "does_not_run_openclaw_or_playwright_on_server",
                    "does_not_publish_or_control_real_accounts",
                    "does_not_bypass_operator_approval",
                ],
            }
        )

        operation_metadata = dict(operation.operation_metadata or {})
        history = self._production_closed_loop_delivery_action_evidence_history(operation)
        history = [*history, record][-100:]
        operation_metadata["production_closed_loop_delivery_action_evidence_records"] = history
        operation_metadata["production_closed_loop_delivery_action_evidence_latest"] = record
        operation.operation_metadata = operation_metadata
        await self.session.commit()
        await self.session.refresh(operation)
        return record

    async def list_production_closed_loop_delivery_action_evidence(
        self,
        *,
        workspace_id: str,
        gate_key: str | None = None,
        operation_id: UUID | None = None,
        limit: int = 50,
    ) -> dict[str, Any]:
        """List recorded delivery action package evidence across a workspace."""

        clean_gate_key = str(gate_key or "").strip() or None
        clean_limit = max(1, min(int(limit or 50), 200))
        if operation_id is not None:
            operations = [await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)]
        else:
            operations = await self.list_operations(workspace_id=workspace_id, limit=500)
        records: list[dict[str, Any]] = []
        for operation in operations:
            for record in self._production_closed_loop_delivery_action_evidence_history(operation):
                if clean_gate_key and str(record.get("gate_key") or "") != clean_gate_key:
                    continue
                records.append(record)
        records.sort(key=lambda item: str(item.get("created_at") or ""), reverse=True)
        records = records[:clean_limit]
        latest_record = records[0] if records else None
        return {
            "workspace_id": workspace_id,
            "record_count": len(records),
            "latest_record": latest_record,
            "records": records,
            "acceptance_gates": [
                "production_closed_loop_delivery_action_packages",
                "delivery_action_evidence_is_operator_supplied",
                "operator_confirmation_required_for_resolved_status",
            ],
            "boundaries": [
                "delivery_action_evidence_only_no_external_execution",
                "does_not_execute_target_endpoint",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_publish_or_control_real_accounts",
                "does_not_bypass_operator_approval",
            ],
            "generated_at": datetime.now(UTC),
            "metadata": {
                "phase": "70X",
                "contract": "production_closed_loop_delivery_action_evidence_list",
                "source_contract": "production_closed_loop_delivery_action_evidence",
                "storage": "commercial_operations.operation_metadata.production_closed_loop_delivery_action_evidence_records",
                "gate_filter": clean_gate_key,
                "operation_filter": str(operation_id) if operation_id else None,
                "server_side_external_execution": False,
                "actual_publish_performed": False,
            },
        }

    @classmethod
    def _production_closed_loop_delivery_action_package(
        cls,
        *,
        workspace_id: str,
        gate: dict[str, Any],
        immediate: bool,
    ) -> dict[str, Any]:
        gate_key = str(gate.get("gate_key") or "unknown_gate")
        gate_status = str(gate.get("gate_status") or "open")
        related_operation_ids = [
            str(item)
            for item in gate.get("related_operation_ids", [])
            if str(item or "").strip()
        ]
        action_targets = related_operation_ids or [None]
        action_steps = [
            cls._production_closed_loop_delivery_action_step(
                workspace_id=workspace_id,
                gate=gate,
                operation_id=operation_id,
            )
            for operation_id in action_targets
        ]
        action_status = cls._production_closed_loop_delivery_action_status(
            gate_status=gate_status,
            owner=str(gate.get("owner") or "operation_manager"),
        )
        return {
            "gate_key": gate_key,
            "gate_status": gate_status,
            "title": str(gate.get("title") or gate_key),
            "owner": str(gate.get("owner") or "operation_manager"),
            "priority": int(gate.get("priority") or 0),
            "target_console": cls._production_closed_loop_delivery_target_console(gate),
            "action_status": "complete" if gate_status == "complete" else action_status,
            "action_count": 0 if gate_status == "complete" else len(action_steps),
            "related_operation_ids": related_operation_ids,
            "blocking_reasons": [
                str(item)
                for item in gate.get("blocking_reasons", [])
                if str(item or "").strip()
            ],
            "recommended_action_key": action_steps[0]["action_key"] if gate_status != "complete" and action_steps else None,
            "action_steps": [] if gate_status == "complete" else action_steps,
            "external_execution_allowed": False,
            "immediate": immediate,
        }

    @classmethod
    def _production_closed_loop_delivery_action_step(
        cls,
        *,
        workspace_id: str,
        gate: dict[str, Any],
        operation_id: str | None,
    ) -> dict[str, Any]:
        gate_key = str(gate.get("gate_key") or "unknown_gate")
        owner = str(gate.get("owner") or "operation_manager")
        method = str(gate.get("action_method") or "GET")
        endpoint = str(gate.get("action_endpoint") or "")
        if operation_id:
            endpoint = endpoint.replace("{operation_id}", operation_id)
        blocked_by = [
            str(item)
            for item in gate.get("blocking_reasons", [])
            if str(item or "").strip()
        ]
        action_key = f"{gate_key}:{operation_id or 'workspace'}"
        return {
            "action_key": action_key,
            "gate_key": gate_key,
            "operation_id": operation_id,
            "target_console": cls._production_closed_loop_delivery_target_console(gate),
            "action_status": cls._production_closed_loop_delivery_action_status(
                gate_status=str(gate.get("gate_status") or "open"),
                owner=owner,
            ),
            "title": str(gate.get("title") or gate_key),
            "owner": owner,
            "method": method,
            "endpoint": endpoint or None,
            "requires_operator_confirmation": True,
            "external_execution_allowed": False,
            "server_side_external_execution": False,
            "blocked_by": blocked_by,
            "evidence_requirements": [
                str(item)
                for item in gate.get("evidence_requirements", [])
                if str(item or "").strip()
            ],
            "operator_next_actions": [
                str(item)
                for item in gate.get("operator_next_actions", [])
                if str(item or "").strip()
            ],
            "server_next_actions": [
                str(item)
                for item in gate.get("server_next_actions", [])
                if str(item or "").strip()
            ],
            "client_next_actions": [
                str(item)
                for item in gate.get("client_next_actions", [])
                if str(item or "").strip()
            ],
            "payload_template": {
                "workspace_id": workspace_id,
                "operation_id": operation_id,
                "gate_key": gate_key,
                "operator_confirmed": False,
                "operator_note": "",
                "evidence_links": [],
            },
            "guardrails": [
                "operator_confirmation_required_before_mutation",
                "server_side_external_execution=false",
                "external_execution_allowed=false",
                "customer_machine_executes_openclaw_playwright_after_approval",
            ],
        }

    @staticmethod
    def _production_closed_loop_delivery_target_console(gate: dict[str, Any]) -> str:
        owner = str(gate.get("owner") or "").strip().lower()
        if owner == "customer_machine_operator":
            return "customer_machine_console"
        if owner == "technical_operator":
            return "technical_operator_console"
        return "server_operator_console"

    @staticmethod
    def _production_closed_loop_delivery_action_status(*, gate_status: str, owner: str) -> str:
        if gate_status == "complete":
            return "complete"
        if gate_status == "critical":
            return "blocked_requires_operator_action"
        if owner == "customer_machine_operator":
            return "customer_machine_action_required"
        if owner == "technical_operator":
            return "technical_configuration_required"
        return "ready_for_operator_review"

    @classmethod
    def _production_closed_loop_delivery_remediation(
        cls,
        *,
        package: dict[str, Any],
        latest_evidence: dict[str, Any] | None,
    ) -> dict[str, Any]:
        gate_key = str(package.get("gate_key") or "unknown_gate")
        action_steps = [step for step in package.get("action_steps", []) if isinstance(step, dict)]
        first_step = action_steps[0] if action_steps else {}
        target_console = str(package.get("target_console") or first_step.get("target_console") or "server_operator_console")
        owner = str(package.get("owner") or first_step.get("owner") or "operation_manager")
        related_operation_ids = [
            str(item)
            for item in package.get("related_operation_ids", [])
            if str(item or "").strip()
        ]
        override = cls._production_closed_loop_delivery_remediation_overrides(
            gate_key=gate_key,
            operation_id=related_operation_ids[0] if related_operation_ids else None,
        )
        operator_actions = [
            str(item)
            for step in action_steps
            for item in step.get("operator_next_actions", [])
            if str(item or "").strip()
        ]
        server_actions = [
            str(item)
            for step in action_steps
            for item in step.get("server_next_actions", [])
            if str(item or "").strip()
        ]
        client_actions = [
            str(item)
            for step in action_steps
            for item in step.get("client_next_actions", [])
            if str(item or "").strip()
        ]
        recommended_sequence = cls._dedupe_texts(
            [
                *operator_actions,
                *server_actions,
                *client_actions,
                *override.get("recommended_sequence", []),
            ]
        )
        expected_evidence = cls._dedupe_texts(
            [
                *[
                    str(item)
                    for item in package.get("blocking_reasons", [])
                    if str(item or "").strip()
                ],
                *[
                    str(item)
                    for step in action_steps
                    for item in step.get("evidence_requirements", [])
                    if str(item or "").strip()
                ],
                *override.get("expected_evidence", []),
            ]
        )
        latest_evidence_id = None
        if latest_evidence and latest_evidence.get("evidence_record_id"):
            latest_evidence_id = str(latest_evidence.get("evidence_record_id"))
        return {
            "remediation_key": f"remediate:{gate_key}",
            "gate_key": gate_key,
            "gate_status": str(package.get("gate_status") or "open"),
            "title": str(package.get("title") or gate_key),
            "owner": owner,
            "priority": int(package.get("priority") or 0),
            "target_console": target_console,
            "action_status": str(package.get("action_status") or "ready_for_operator_review"),
            "related_operation_ids": related_operation_ids,
            "blocking_reasons": [
                str(item)
                for item in package.get("blocking_reasons", [])
                if str(item or "").strip()
            ],
            "recommended_sequence": recommended_sequence,
            "primary_method": str(override.get("primary_method") or first_step.get("method") or "GET"),
            "primary_endpoint": str(override.get("primary_endpoint") or first_step.get("endpoint") or ""),
            "secondary_endpoints": override.get("secondary_endpoints", []),
            "expected_evidence": expected_evidence,
            "existing_records_needed": override.get("existing_records_needed", []),
            "completion_gate": str(override.get("completion_gate") or f"{gate_key}_evidence_resolved"),
            "current_evidence_status": (
                str(latest_evidence.get("evidence_status"))
                if latest_evidence and latest_evidence.get("evidence_status")
                else "no_evidence_record"
            ),
            "latest_evidence_record_id": latest_evidence_id,
            "latest_evidence_summary": (
                str(latest_evidence.get("evidence_summary"))
                if latest_evidence and latest_evidence.get("evidence_summary")
                else None
            ),
            "source_action_key": str(first_step.get("action_key") or package.get("recommended_action_key") or "") or None,
            "requires_operator_confirmation": True,
            "can_be_started_from_server": target_console == "server_operator_console",
            "can_be_started_from_customer_machine": target_console in {"customer_machine_console", "technical_operator_console"},
            "automation_allowed": False,
            "external_execution_allowed": False,
            "runbook_references": override.get("runbook_references", []),
            "handoff_notes": cls._dedupe_texts(
                [
                    f"target_console={target_console}",
                    "use existing production workflow UI or API; do not call the mapped endpoint automatically",
                    *override.get("handoff_notes", []),
                ]
            ),
            "guardrails": cls._dedupe_texts(
                [
                    "operator_confirmation_required_before_mutation",
                    "server_side_external_execution=false",
                    "external_execution_allowed=false",
                    "delivery_remediation_map_only_no_external_execution",
                    *override.get("guardrails", []),
                ]
            ),
        }

