    @staticmethod
    def _dedupe_texts(values: list[Any]) -> list[str]:
        seen: set[str] = set()
        result: list[str] = []
        for value in values:
            clean = str(value or "").strip()
            if clean and clean not in seen:
                seen.add(clean)
                result.append(clean)
        return result

