    async def create_production_task(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        operation_plan_id: UUID | None = None,
        task_type: str,
        media_subtype: str | None = None,
        channel: str,
        title: str,
        brief: str | None = None,
        source_material_ids: list[str] | None = None,
        output_requirements: list[dict[str, Any]] | None = None,
        target_specs: dict[str, Any] | None = None,
        workflow_selection_required: bool = True,
        assigned_agent: str | None = None,
        created_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> CommercialOperationProductionTask:
        await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        if operation_plan_id is not None:
            await self._require_project_record(
                CommercialOperationPlan,
                workspace_id=workspace_id,
                operation_id=operation_id,
                record_id=operation_plan_id,
                not_found_message="Commercial operation plan not found in workspace",
            )
        clean_task_type = self._clean_required_text(task_type, "task_type")
        if clean_task_type == "media" and not media_subtype:
            raise ValueError("media_subtype is required for media production tasks")
        task = CommercialOperationProductionTask(
            workspace_id=workspace_id,
            operation_id=operation_id,
            operation_plan_id=operation_plan_id,
            task_type=clean_task_type,
            media_subtype=media_subtype.strip() if media_subtype and media_subtype.strip() else None,
            channel=self._clean_required_text(channel, "channel"),
            title=self._clean_required_text(title, "title"),
            task_status=CommercialOperationProductionTaskStatus.DRAFT.value,
            brief=brief.strip() if brief and brief.strip() else None,
            source_material_ids=self._clean_list(source_material_ids),
            output_requirements=self._clean_json_records(output_requirements),
            target_specs=target_specs or {},
            workflow_selection_required=workflow_selection_required,
            assigned_agent=assigned_agent.strip() if assigned_agent and assigned_agent.strip() else None,
            created_by=created_by,
            updated_by=created_by,
            task_metadata=metadata or {},
        )
        self.session.add(task)
        await self.session.commit()
        await self.session.refresh(task)
        return task

