    async def prepare_next_operation_cycle(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None = None,
        operator_confirmed: bool = False,
        source_decision_id: UUID | None = None,
        create_tasks: bool = True,
        operator_note: str | None = None,
        metadata: dict[str, Any] | None = None,
        routing_decision: dict[str, Any] | None = None,
        platform: str | None = None,
        force_metric_due: bool = True,
    ) -> dict[str, Any]:
        """Create a reviewable next-cycle plan package from an approved optimization decision."""

        if not operator_confirmed:
            raise ValueError("operator_confirmed is required before preparing the next operation cycle")

        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        readiness_before = await self.get_production_closed_loop_readiness(
            workspace_id=workspace_id,
            operation_id=operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        if not readiness_before.get("ready_for_next_cycle"):
            raise ValueError("Production closed loop is not ready for the next operation cycle")

        next_action_before = await self.get_production_closed_loop_next_action(
            workspace_id=workspace_id,
            operation_id=operation_id,
            platform=platform,
            force_metric_due=force_metric_due,
        )
        decision = await self._select_next_cycle_source_decision(
            workspace_id=workspace_id,
            operation_id=operation_id,
            source_decision_id=source_decision_id,
        )
        route = routing_decision or self._next_cycle_routing_decision(operation=operation, decision=decision)
        existing_plan = await self._find_next_cycle_operation_plan(
            workspace_id=workspace_id,
            operation_id=operation_id,
            source_decision_id=decision.id,
        )

        draft_status = "reused"
        if existing_plan is None:
            plan = await self.create_operation_plan(
                workspace_id=workspace_id,
                operation_id=operation_id,
                plan_version=self._next_operation_plan_version(
                    await self.list_operation_plans(workspace_id=workspace_id, operation_id=operation_id, limit=500)
                ),
                title=f"Next-cycle operation plan: {operation.title}"[:255],
                objective_summary=self._next_cycle_objective_summary(operation=operation, decision=decision),
                audience_strategy=self._next_cycle_audience_strategy(operation=operation, decision=decision),
                channel_strategy=self._next_cycle_channel_strategy(operation=operation, decision=decision),
                content_strategy=self._next_cycle_content_strategy(operation=operation, decision=decision),
                production_scope=self._next_cycle_production_scope(operation=operation, decision=decision),
                material_requirements=self._next_cycle_material_requirements(operation=operation, decision=decision),
                kpis=self._next_cycle_kpis(operation=operation, decision=decision),
                publish_schedule=self._next_cycle_publish_schedule(operation=operation, decision=decision),
                risk_notes=self._next_cycle_risk_notes(operation=operation, decision=decision),
                source_goal=operation.objective,
                created_by=actor_user_id,
                metadata=self._next_cycle_metadata(
                    operation=operation,
                    decision=decision,
                    routing_decision=route,
                    operator_note=operator_note,
                    metadata=metadata or {},
                    project_object="OperationPlan",
                ),
            )
            existing_plan = await self.set_operation_plan_status(
                workspace_id=workspace_id,
                operation_id=operation_id,
                plan_id=plan.id,
                status=CommercialOperationPlanStatus.READY_FOR_REVIEW.value,
                actor_user_id=actor_user_id,
                reviewer_notes="Next-cycle operation plan generated from an approved optimization decision.",
            )
            draft_status = "created"
        elif existing_plan.plan_status == CommercialOperationPlanStatus.DRAFT.value:
            existing_plan = await self.set_operation_plan_status(
                workspace_id=workspace_id,
                operation_id=operation_id,
                plan_id=existing_plan.id,
                status=CommercialOperationPlanStatus.READY_FOR_REVIEW.value,
                actor_user_id=actor_user_id,
                reviewer_notes="Existing next-cycle operation plan prepared for human review.",
            )

        production_tasks = [
            task
            for task in await self.list_production_tasks(workspace_id=workspace_id, operation_id=operation_id, limit=500)
            if task.operation_plan_id == existing_plan.id
            and task.task_status
            not in {
                CommercialOperationProductionTaskStatus.REJECTED.value,
                CommercialOperationProductionTaskStatus.ARCHIVED.value,
            }
        ]
        if create_tasks and not production_tasks:
            production_tasks = []
            for task_scope in self._production_scope_from_plan(existing_plan, operation):
                task = await self.create_production_task(
                    workspace_id=workspace_id,
                    operation_id=operation_id,
                    operation_plan_id=existing_plan.id,
                    task_type=str(task_scope["task_type"]),
                    media_subtype=task_scope.get("media_subtype"),
                    channel=str(task_scope["channel"]),
                    title=str(task_scope["title"])[:255],
                    brief=str(task_scope["brief"]),
                    source_material_ids=list(task_scope.get("source_material_ids") or []),
                    output_requirements=list(task_scope.get("output_requirements") or []),
                    target_specs=dict(task_scope.get("target_specs") or {}),
                    workflow_selection_required=bool(task_scope.get("workflow_selection_required", True)),
                    assigned_agent=task_scope.get("assigned_agent"),
                    created_by=actor_user_id,
                    metadata=self._next_cycle_metadata(
                        operation=operation,
                        decision=decision,
                        routing_decision=route,
                        operator_note=operator_note,
                        metadata=metadata or {},
                        project_object="ProductionTask",
                        extra={"operation_plan_id": str(existing_plan.id)},
                    ),
                )
                ready_task = await self.set_production_task_status(
                    workspace_id=workspace_id,
                    operation_id=operation_id,
                    production_task_id=task.id,
                    status=CommercialOperationProductionTaskStatus.READY_FOR_REVIEW.value,
                    actor_user_id=actor_user_id,
                    reviewer_notes="Next-cycle production task generated from the approved optimization decision.",
                )
                production_tasks.append(ready_task)
            draft_status = "created"

        return {
            "operation_id": operation_id,
            "workspace_id": workspace_id,
            "draft_status": draft_status,
            "source_decision": decision,
            "operation_plan": existing_plan,
            "production_tasks": production_tasks,
            "readiness_status_before": readiness_before.get("readiness_status"),
            "next_action_key_before": next_action_before.get("selected_action_key"),
            "operator_next_actions": [
                "Review and approve the next-cycle operation plan before starting the new production cycle.",
                "Review the generated copy, image, and media tasks; reject or revise any task that does not match the approved decision.",
            ],
            "server_next_actions": [
                "Keep the next-cycle package in ready_for_review until an operator approves it.",
                "Do not submit ComfyUI, publish, or run customer-machine actions from this endpoint.",
            ],
            "client_next_actions": [
                "Show the next-cycle plan and tasks in the customer-machine approval queue.",
                "After approval, continue through workflow selection, output preview, publish package, and metric feedback again.",
            ],
            "boundaries": [
                "next_cycle_draft_only_no_external_execution",
                "does_not_approve_operation_plan_or_tasks",
                "does_not_submit_comfyui_prompts",
                "does_not_publish_or_control_accounts",
                "does_not_run_openclaw_or_playwright_on_server",
                "does_not_bypass_operator_approval",
            ],
            "metadata": {
                "phase": "68Z8",
                "contract": "production_closed_loop_next_cycle_draft",
                "source_decision_id": str(decision.id),
                "source_decision_status": decision.decision_status,
                "operator_confirmed": operator_confirmed,
                "create_tasks": create_tasks,
                "server_side_external_execution": False,
            },
            "generated_at": datetime.now(UTC),
        }

