    async def list_workflow_candidates(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        production_task_id: UUID,
        limit: int = 8,
    ) -> dict[str, Any]:
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        task = await self.require_production_task(
            workspace_id=workspace_id,
            operation_id=operation_id,
            production_task_id=production_task_id,
        )
        knowledge = ComfyUIWorkflowKnowledge()
        documents = knowledge.load_documents()
        query = self._workflow_candidate_query(operation=operation, task=task)
        required_capabilities = self._workflow_candidate_required_capabilities(operation=operation, task=task)
        preferred_terms = self._workflow_candidate_preferred_terms(operation=operation, task=task)
        ranked = knowledge.rank(
            documents=documents,
            query=query,
            required_capabilities=tuple(required_capabilities),
            preferred_terms=tuple(preferred_terms),
            limit=limit,
        )
        items = [
            self._workflow_candidate_response(
                operation=operation,
                task=task,
                candidate=candidate,
                knowledge_path=str(knowledge.knowledge_path),
            )
            for candidate in ranked
        ]
        return {
            "operation_id": operation_id,
            "production_task_id": production_task_id,
            "query": query,
            "required_capabilities": required_capabilities,
            "preferred_terms": preferred_terms,
            "items": items,
            "library_metadata": {
                "knowledge_path": str(knowledge.knowledge_path),
                "default_knowledge_path": str(DEFAULT_WORKFLOW_KNOWLEDGE),
                "document_count": len(documents),
                "capability_counts": knowledge.capability_counts(documents),
                "selection_boundary": "candidate_only_no_comfyui_submission",
            },
        }

