    async def create_final_selection(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        production_task_id: UUID | None = None,
        output_candidate_id: UUID,
        final_type: str,
        title: str,
        selection_reason: str | None = None,
        platform_targets: list[str] | None = None,
        selected_by: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> CommercialOperationFinalSelection:
        await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        if production_task_id is not None:
            await self.require_production_task(
                workspace_id=workspace_id,
                operation_id=operation_id,
                production_task_id=production_task_id,
            )
        await self._require_project_record(
            CommercialOperationOutputCandidate,
            workspace_id=workspace_id,
            operation_id=operation_id,
            record_id=output_candidate_id,
            not_found_message="Commercial operation output candidate not found in workspace",
        )
        selection = CommercialOperationFinalSelection(
            workspace_id=workspace_id,
            operation_id=operation_id,
            production_task_id=production_task_id,
            output_candidate_id=output_candidate_id,
            final_type=self._clean_required_text(final_type, "final_type"),
            title=self._clean_required_text(title, "title"),
            selection_status=CommercialOperationFinalSelectionStatus.DRAFT.value,
            selection_reason=selection_reason.strip() if selection_reason and selection_reason.strip() else None,
            platform_targets=self._clean_list(platform_targets),
            selected_by=selected_by,
            selection_metadata=metadata or {},
        )
        self.session.add(selection)
        await self.session.commit()
        await self.session.refresh(selection)
        return selection

