    async def get_publish_prep_package(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        final_selection_id: UUID,
    ) -> dict[str, Any]:
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        final_selection = await self._require_project_record(
            CommercialOperationFinalSelection,
            workspace_id=workspace_id,
            operation_id=operation_id,
            record_id=final_selection_id,
            not_found_message="Commercial operation final selection not found in workspace",
        )
        selected_output_candidate = await self._require_project_record(
            CommercialOperationOutputCandidate,
            workspace_id=workspace_id,
            operation_id=operation_id,
            record_id=final_selection.output_candidate_id,
            not_found_message="Commercial operation output candidate not found in workspace",
        )
        existing_publish_packages = (
            await self.session.scalars(
                select(CommercialOperationPublishPackage)
                .where(
                    CommercialOperationPublishPackage.workspace_id == workspace_id,
                    CommercialOperationPublishPackage.operation_id == operation_id,
                    CommercialOperationPublishPackage.final_selection_id == final_selection_id,
                )
                .order_by(CommercialOperationPublishPackage.created_at.desc())
            )
        ).all()
        platform_targets = self._publish_prep_target_platforms(operation=operation, final_selection=final_selection)
        blocking_reasons = self._publish_prep_blocking_reasons(
            final_selection=final_selection,
            selected_output_candidate=selected_output_candidate,
        )
        package_blueprints = [
            self._publish_prep_blueprint(
                operation=operation,
                final_selection=final_selection,
                selected_output_candidate=selected_output_candidate,
                platform=platform,
            )
            for platform in platform_targets
        ]
        return {
            "operation_id": operation_id,
            "final_selection_id": final_selection_id,
            "readiness_status": "ready_for_publish_package_registration" if not blocking_reasons else "blocked",
            "blocking_reasons": blocking_reasons,
            "final_selection_status": final_selection.selection_status,
            "platform_targets": platform_targets,
            "final_selection": self._final_selection_dict(final_selection),
            "selected_output_candidate": self._output_candidate_dict(selected_output_candidate),
            "package_blueprints": package_blueprints,
            "copy_guidance": self._publish_prep_copy_guidance(operation=operation, final_selection=final_selection),
            "review_gates": [
                "final_selection_must_be_approved",
                "selected_output_candidate_must_remain_selected",
                "operator_must_review_platform_copy",
                "publish_package_must_be_ready_and_approved_before_client_execution",
                "openclaw_playwright_execution_requires_separate_customer_machine_handoff",
                "platform_metrics_must_return_after_publish",
            ],
            "existing_publish_packages": [
                self._publish_package_dict(package) for package in existing_publish_packages
            ],
            "platform_policy": {
                platform: self._publish_prep_platform_policy(platform) for platform in platform_targets
            },
            "metadata": {
                "phase": "68G",
                "contract": "approved_final_selection_to_publish_package",
                "existing_publish_package_count": len(existing_publish_packages),
                "selection_boundary": "operator_must_approve_publish_package_before_client_execution",
                "does_not_execute_openclaw_or_playwright": True,
            },
        }

