        ready = await self.mark_asset_request_ready(
            workspace_id=workspace_id,
            operation_id=operation_id,
            asset_request_id=asset_request.id,
            updated_by=actor_user_id,
            reviewer_notes="Main Agent prepared this asset/workflow brief for human review; no generation occurred.",
        )
        return self._created_main_agent_advance(
            record=ready,
            kind="asset_request",
            status_attr="request_status",
            track=track,
            operator_next_action="Review the asset/workflow brief and verify runtime/model readiness before approval.",
            server_next_action="Keep ComfyUI and workflow execution behind the existing guarded runtime gates.",
            client_next_action="No customer-machine action is available until a packaged deliverable exists.",
        )

