    async def _advance_client_execution(
        self,
        *,
        operation: CommercialOperation,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        deliverables = await self.list_deliverables(workspace_id=workspace_id, operation_id=operation_id)
        pending_deliverable = self._first_record(
            deliverables,
            lambda item: item.deliverable_status
            in {
                CommercialOperationDeliverableStatus.DRAFT.value,
                CommercialOperationDeliverableStatus.READY_FOR_REVIEW.value,
            },
        )
        if pending_deliverable is not None:
            return self._reused_main_agent_advance(
                record=pending_deliverable,
                kind="deliverable",
                status_attr="deliverable_status",
                track="client_execution",
                next_action="Approve and package the existing deliverable before execution handoff.",
            )
        approved_deliverable = self._first_record(
            deliverables,
            lambda item: item.deliverable_status == CommercialOperationDeliverableStatus.APPROVED.value,
        )
        if approved_deliverable is not None:
            packaged = await self.package_deliverable(
                workspace_id=workspace_id,
                operation_id=operation_id,
                deliverable_id=approved_deliverable.id,
                packaged_by=actor_user_id,
                result_summary="Main Agent packaged approved deliverable; no external execution occurred.",
            )
            return self._updated_main_agent_advance(
                record=packaged,
                kind="deliverable",
                status_attr="deliverable_status",
                track="client_execution",
                operator_next_action="Run advance again to create the execution request from the packaged deliverable.",
                server_next_action="Use the packaged deliverable as the only execution-request source.",
                client_next_action="No customer-machine action is available until execution request approval.",
            )
        packaged_deliverable = self._first_record(
            deliverables,
            lambda item: item.deliverable_status == CommercialOperationDeliverableStatus.PACKAGED.value,
        )
        if packaged_deliverable is None:
            return await self._create_deliverable_for_main_agent(
                operation=operation,
                workspace_id=workspace_id,
                operation_id=operation_id,
                actor_user_id=actor_user_id,
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            )

        execution_requests = await self.list_execution_requests(
            workspace_id=workspace_id,
            operation_id=operation_id,
            deliverable_id=packaged_deliverable.id,
        )
        pending_request = self._first_record(
            execution_requests,
            lambda item: item.request_status
            in {
                CommercialOperationExecutionRequestStatus.DRAFT.value,
                CommercialOperationExecutionRequestStatus.READY_FOR_REVIEW.value,
            },
        )
        if pending_request is not None:
            return self._reused_main_agent_advance(
                record=pending_request,
                kind="execution_request",
                status_attr="request_status",
                track="client_execution",
                next_action="Approve and prepare the existing execution request before queueing a run.",
            )
        approved_request = self._first_record(
            execution_requests,
            lambda item: item.request_status == CommercialOperationExecutionRequestStatus.APPROVED.value,
        )
        if approved_request is not None:
            prepared = await self.prepare_execution_request(
                workspace_id=workspace_id,
                operation_id=operation_id,
                execution_request_id=approved_request.id,
                prepared_by=actor_user_id,
                result_summary="Main Agent prepared approved execution request; no OpenClaw or Playwright action occurred.",
            )
            return self._updated_main_agent_advance(
                record=prepared,
                kind="execution_request",
                status_attr="request_status",
                track="client_execution",
                operator_next_action="Run advance again to queue a metadata-only execution run.",
                server_next_action="Keep runtime handoff metadata ready for the customer-machine console.",
                client_next_action="Wait for a queued execution run before customer-machine execution.",
            )
        prepared_request = self._first_record(
            execution_requests,
            lambda item: item.request_status == CommercialOperationExecutionRequestStatus.PREPARED.value,
        )
        if prepared_request is None:
            return await self._create_execution_request_for_main_agent(
                operation=operation,
                workspace_id=workspace_id,
                operation_id=operation_id,
                deliverable=packaged_deliverable,
                actor_user_id=actor_user_id,
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            )
        execution_runs = await self.list_execution_runs(
            workspace_id=workspace_id,
            operation_id=operation_id,
            execution_request_id=prepared_request.id,
        )
        active_run = self._first_record(
            execution_runs,
            lambda item: item.run_status
            in {
                CommercialOperationExecutionRunStatus.QUEUED.value,
                CommercialOperationExecutionRunStatus.RUNNING.value,
                CommercialOperationExecutionRunStatus.RETRYING.value,
            },
        )
        if active_run is not None:
            return self._reused_main_agent_advance(
                record=active_run,
                kind="execution_run",
                status_attr="run_status",
                track="client_execution",
                next_action="Operate the existing execution run from the customer-machine console and record its terminal outcome.",
            )
        run = await self.create_execution_run(
            workspace_id=workspace_id,
            operation_id=operation_id,
            execution_request_id=prepared_request.id,
            title=f"Customer-machine run: {prepared_request.title}"[:255],
            execution_target=prepared_request.execution_target,
            input_payload={
                "source": "main_agent_advance",
                "execution_request_id": str(prepared_request.id),
                "runtime_boundary": "metadata_only_queue_record",
            },
            max_retries=0,
            operator_notes=operator_note,
            queued_by=actor_user_id,
            metadata=self._main_agent_metadata(
                track="client_execution",
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            ),
        )
        return self._created_main_agent_advance(
            record=run,
            kind="execution_run",
            status_attr="run_status",
            track="client_execution",
            operator_next_action="Start and complete or fail the queued run from the customer-machine console.",
            server_next_action="Only monitor the run record and wait for operator-reported outcome.",
            client_next_action="Use OpenClaw/Playwright only after the operator starts the approved run.",
        )

    async def _create_deliverable_for_main_agent(
        self,
        *,
        operation: CommercialOperation,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        draft = self._first_record(
            await self.list_content_drafts(workspace_id=workspace_id, operation_id=operation_id),
            lambda item: item.draft_status == CommercialOperationContentDraftStatus.APPROVED.value,
        )
        if draft is None:
            return self._main_agent_advance_blocked_action(
                track="client_execution",
                blockers=["approved_content_draft_required"],
                routing_decision=routing_decision,
            )
        asset_ids = [
            item.id
            for item in await self.list_asset_requests(
                workspace_id=workspace_id,
                operation_id=operation_id,
                content_draft_id=draft.id,
            )
            if item.request_status
            in {
                CommercialOperationAssetRequestStatus.APPROVED.value,
                CommercialOperationAssetRequestStatus.PREPARED.value,
            }
        ]
        deliverable = await self.create_deliverable(
            workspace_id=workspace_id,
            operation_id=operation_id,
            step_key=draft.step_key,
            content_draft_id=draft.id,
            asset_request_ids=asset_ids,
            deliverable_type=self._main_agent_deliverable_type(draft),
            title=f"Delivery package: {draft.title}"[:255],
            summary=draft.summary,
            delivery_notes="Main Agent created a reviewable package from approved content; no execution occurred.",
            quality_checks=[
                "approved content draft",
                "linked assets reviewed when present",
                "Output Library artifact generated",
                "no external publishing",
                "no customer-machine execution",
            ],
            created_by=actor_user_id,
            metadata=self._main_agent_metadata(
                track="client_execution",
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            ),
        )
        ready = await self.mark_deliverable_ready(
            workspace_id=workspace_id,
            operation_id=operation_id,
            deliverable_id=deliverable.id,
            updated_by=actor_user_id,
            reviewer_notes="Main Agent packaged this deliverable for review; it is not approved or executed.",
        )
        return self._created_main_agent_advance(
            record=ready,
            kind="deliverable",
            status_attr="deliverable_status",
            track="client_execution",
            operator_next_action="Approve and package the deliverable before execution handoff.",
            server_next_action="Wait for approval before creating an execution request.",
            client_next_action="No customer-machine action is available until the execution request exists.",
        )

    async def _create_execution_request_for_main_agent(
        self,
        *,
        operation: CommercialOperation,
        workspace_id: str,
        operation_id: UUID,
        deliverable: CommercialOperationDeliverable,
        actor_user_id: str | None,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        approved_snapshots = [
            snapshot.id
            for snapshot in await self.list_evidence_snapshots(
                workspace_id=workspace_id,
                operation_id=operation_id,
                deliverable_id=deliverable.id,
            )
            if snapshot.snapshot_status == CommercialOperationEvidenceSnapshotStatus.APPROVED.value
        ]
        request = await self.create_execution_request(
            workspace_id=workspace_id,
            operation_id=operation_id,
            deliverable_id=deliverable.id,
            execution_type="openclaw" if self._main_agent_channel_is_social(deliverable.channel) else "manual_handoff",
            execution_mode="approval_handoff",
            title=f"Execution handoff: {deliverable.title}"[:255],
            execution_target=deliverable.channel,
            input_summary=deliverable.summary,
            runbook=[
                {"step": "open customer-machine console", "status": "pending"},
                {"step": "confirm account, target channel, and operator readiness", "status": "pending"},
                {"step": "run approved OpenClaw/Playwright handoff only from the customer machine", "status": "pending"},
                {"step": "record terminal outcome and evidence after execution", "status": "pending"},
            ],
            readiness_checks=[
                "packaged deliverable is available in Output Library",
                "human approval required before runtime execution",
                "customer-machine operator controls account session",
                "server does not publish or control accounts",
            ],
            expected_outputs=[
                "approved execution request",
                "metadata-only execution run record",
                "operator-recorded result after terminal execution",
            ],
            evidence_snapshot_ids=approved_snapshots,
            operator_checklist=[
                {"item": "confirm customer account/session is operator-controlled", "status": "pending"},
                {"item": "confirm no captcha/proxy/fingerprint bypass is requested", "status": "pending"},
                {"item": "confirm rollback and failure note owner", "status": "pending"},
            ],
            requested_by=actor_user_id,
            metadata=self._main_agent_metadata(
                track="client_execution",
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            ),
        )
        ready = await self.mark_execution_request_ready(
            workspace_id=workspace_id,
            operation_id=operation_id,
            execution_request_id=request.id,
            updated_by=actor_user_id,
            reviewer_notes="Main Agent created this execution request for review; no runtime action occurred.",
        )
        return self._created_main_agent_advance(
            record=ready,
            kind="execution_request",
            status_attr="request_status",
            track="client_execution",
            operator_next_action="Approve and prepare the execution request before queueing a run.",
            server_next_action="Expose the handoff to the customer-machine console after approval.",
            client_next_action="Wait for a prepared request and queued run before OpenClaw/Playwright action.",
        )

    async def _advance_result_recording(
        self,
        *,
        operation: CommercialOperation,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        run = self._first_record(
            await self.list_execution_runs(workspace_id=workspace_id, operation_id=operation_id),
            lambda item: item.run_status
            in {
                CommercialOperationExecutionRunStatus.SUCCEEDED.value,
                CommercialOperationExecutionRunStatus.FAILED.value,
                CommercialOperationExecutionRunStatus.CANCELLED.value,
            },
        )
        if run is None:
            return self._main_agent_advance_blocked_action(
                track="result_recording",
                blockers=["terminal_execution_run_required"],
                routing_decision=routing_decision,
            )
        existing = self._first_record(
            await self.list_results(workspace_id=workspace_id, operation_id=operation_id, execution_run_id=run.id),
            lambda item: item.result_status
            in {
                CommercialOperationResultStatus.DRAFT.value,
                CommercialOperationResultStatus.READY_FOR_REVIEW.value,
                CommercialOperationResultStatus.APPROVED.value,
            },
        )
        if existing is not None:
            return self._reused_main_agent_advance(
                record=existing,
                kind="result",
                status_attr="result_status",
                track="result_recording",
                next_action="Review or approve the existing result record before monitoring.",
            )
        result = await self.create_result(
            workspace_id=workspace_id,
            operation_id=operation_id,
            execution_run_id=run.id,
            result_type="operator_report",
            title=f"Result: {run.title}"[:255],
            summary=run.result_summary or "Execution run reached a terminal state; operator review is required.",
            outcome_summary=run.result_summary,
            observed_metrics=[],
            commercial_signals=[
                f"execution_run_status={run.run_status}",
                "operator outcome review required",
            ],
            evidence_links=[],
            follow_up_actions=["approve result before monitoring", "attach evidence if available"],
            result_payload=run.result_payload or {},
            recommendation_payload={},
            created_by=actor_user_id,
            metadata=self._main_agent_metadata(
                track="result_recording",
                routing_decision=routing_decision,
                operator_note=operator_note,
                metadata=metadata,
            ),
        )
        ready = await self.mark_result_ready(
            workspace_id=workspace_id,
            operation_id=operation_id,
            result_id=result.id,
            updated_by=actor_user_id,
            reviewer_notes="Main Agent created this result record for review from a terminal run.",
        )
        return self._created_main_agent_advance(
            record=ready,
            kind="result",
            status_attr="result_status",
            track="result_recording",
            operator_next_action="Review and approve or reject the result record.",
            server_next_action="Use approved results only as inputs to monitoring observations.",
            client_next_action="Attach customer-machine evidence or notes if needed.",
        )

