    async def _advance_next_cycle_content(
        self,
        *,
        operation: CommercialOperation,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> dict[str, Any]:
        decision = self._first_record(
            await self.list_optimization_decisions(workspace_id=workspace_id, operation_id=operation_id),
            lambda item: item.decision_status == CommercialOperationOptimizationDecisionStatus.APPROVED.value,
        )
        if decision is None:
            return self._main_agent_advance_blocked_action(
                track="next_cycle_content",
                blockers=["approved_optimization_decision_required"],
            routing_decision=routing_decision,
        )
        next_cycle = await self.prepare_next_operation_cycle(
            workspace_id=workspace_id,
            operation_id=operation_id,
            actor_user_id=actor_user_id,
            operator_confirmed=True,
            source_decision_id=decision.id,
            create_tasks=True,
            operator_note=operator_note,
            metadata=metadata,
            routing_decision=routing_decision,
        )
        plan = next_cycle["operation_plan"]
        tasks = list(next_cycle.get("production_tasks") or [])
        records = [self._main_agent_record_ref(plan, "operation_plan", "plan_status")]
        records.extend(self._main_agent_record_ref(task, "production_task", "task_status") for task in tasks)
        status = "reused" if next_cycle["draft_status"] == "reused" else "created"
        return {
            "advance_status": status,
            "created_records": records if status == "created" else [],
            "updated_records": [],
            "reused_records": records if status == "reused" else [],
            "blocked_by": [],
            "operator_next_actions": next_cycle["operator_next_actions"],
            "server_next_actions": next_cycle["server_next_actions"],
            "client_next_actions": next_cycle["client_next_actions"],
            "track": "next_cycle_content",
        }

    def _created_main_agent_advance(
        self,
        *,
        record: Any,
        kind: str,
        status_attr: str,
        track: str,
        operator_next_action: str,
        server_next_action: str,
        client_next_action: str,
    ) -> dict[str, Any]:
        return {
            "advance_status": "created",
            "created_records": [self._main_agent_record_ref(record, kind, status_attr)],
            "updated_records": [],
            "reused_records": [],
            "blocked_by": [],
            "operator_next_actions": [operator_next_action],
            "server_next_actions": [server_next_action],
            "client_next_actions": [client_next_action],
            "track": track,
        }

