    def _reused_main_agent_advance(
        self,
        *,
        record: Any,
        kind: str,
        status_attr: str,
        track: str,
        next_action: str,
    ) -> dict[str, Any]:
        return {
            "advance_status": "reused",
            "created_records": [],
            "updated_records": [],
            "reused_records": [self._main_agent_record_ref(record, kind, status_attr)],
            "blocked_by": [],
            "operator_next_actions": [next_action],
            "server_next_actions": ["Reuse the existing record instead of creating a duplicate."],
            "client_next_actions": ["Wait for the current review or execution record to move forward."],
            "track": track,
        }

    @staticmethod
    def _noop_main_agent_advance(*, track: str, message: str) -> dict[str, Any]:
        return {
            "advance_status": "noop",
            "created_records": [],
            "updated_records": [],
            "reused_records": [],
            "blocked_by": [],
            "operator_next_actions": [message],
            "server_next_actions": ["No new record was needed for this route."],
            "client_next_actions": ["No customer-machine action is available from this no-op route."],
            "track": track,
        }

    @staticmethod
    def _first_record(records: list[Any], predicate: Any) -> Any | None:
        for record in records:
            if predicate(record):
                return record
        return None

    async def _pending_production_task_for_track(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        track: str,
    ) -> CommercialOperationProductionTask | None:
        task_type_by_track = {
            "content_strategy": "copy",
            "text_content": "copy",
            "visual_asset": "image",
            "video_content": "media",
            "workflow_selection": "media",
        }
        expected_type = task_type_by_track.get(track)
        pending_statuses = {
            CommercialOperationProductionTaskStatus.DRAFT.value,
            CommercialOperationProductionTaskStatus.READY_FOR_REVIEW.value,
        }
        tasks = await self.list_production_tasks(workspace_id=workspace_id, operation_id=operation_id)
        matching = [
            task
            for task in tasks
            if task.task_status in pending_statuses and (expected_type is None or task.task_type == expected_type)
        ]
        if matching:
            return matching[0]
        fallback = [task for task in tasks if task.task_status in pending_statuses]
        return fallback[0] if fallback else None

    async def _review_pending_production_task(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        actor_user_id: str | None,
        task: CommercialOperationProductionTask,
        track: str,
    ) -> dict[str, Any]:
        if task.task_status == CommercialOperationProductionTaskStatus.DRAFT.value:
            ready_task = await self.set_production_task_status(
                workspace_id=workspace_id,
                operation_id=operation_id,
                production_task_id=task.id,
                status=CommercialOperationProductionTaskStatus.READY_FOR_REVIEW.value,
                actor_user_id=actor_user_id,
                reviewer_notes="Main Agent prepared this production task for human review.",
            )
            return self._updated_main_agent_advance(
                record=ready_task,
                kind="production_task",
                status_attr="task_status",
                track=track,
                operator_next_action="Review and approve the production task before output generation.",
                server_next_action="Keep production execution behind the approved task and workflow-selection gates.",
                client_next_action="Show the production task in the customer-machine approval queue.",
            )
        return self._reused_main_agent_advance(
            record=task,
            kind="production_task",
            status_attr="task_status",
            track=track,
            next_action="Approve, reject, or revise the pending production task before output generation.",
        )

    def _main_agent_record_ref(self, record: Any, kind: str, status_attr: str) -> dict[str, Any]:
        ref = self._record_ref(record, kind, status_attr)
        ref["review_boundary"] = "human review required before downstream execution"
        return ref

    def _planned_main_agent_record(
        self,
        *,
        operation: CommercialOperation,
        track: str,
        routing_decision: dict[str, Any],
    ) -> dict[str, Any]:
        kind_by_track = {
            "operation_strategy": "operation_plan",
            "knowledge_retrieval": "approval",
            "content_strategy": "content_draft",
            "text_content": "content_draft",
            "visual_asset": "asset_request",
            "video_content": "asset_request",
            "workflow_selection": "asset_request",
            "production_intervention": "intervention_recommendation",
            "production_delivery": "delivery_plan_gate",
            "review_gate": "approval",
            "client_execution": "deliverable_or_execution_record",
            "result_recording": "result",
            "analytics_observation": "monitoring_observation",
            "analytics_optimization": "optimization_decision",
            "next_cycle_content": "operation_plan",
        }
        return {
            "kind": kind_by_track.get(track, "operation_note"),
            "id": "dry_run",
            "status": "planned",
            "title": f"Planned {track}: {operation.title}",
            "track": track,
            "requested_outputs": list((routing_decision.get("next_executable_contract") or {}).get("requested_outputs", [])),
            "review_boundary": "dry-run only; no database record created",
        }

    def _main_agent_metadata(
        self,
        *,
        track: str,
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
        extra: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        note = operator_note.strip() if operator_note and operator_note.strip() else None
        return {
            **(metadata or {}),
            "main_agent_advance": {
                "track": track,
                "decision_key": routing_decision.get("decision_key"),
                "selected_skill_key": routing_decision.get("selected_skill_key"),
                "reason_codes": routing_decision.get("reason_codes", []),
                "blocked_by": routing_decision.get("blocked_by", []),
                "operator_note": note,
                "created_at": datetime.now(UTC).isoformat(),
                **(extra or {}),
            },
        }

    @staticmethod
    def _blocker_next_action(blocker: str) -> str:
        mapping = {
            "knowledge_source_missing": "Attach or configure a knowledge collection before source review.",
            "knowledge_evidence_not_approved": "Approve knowledge coverage before content or asset production.",
            "human_approval_required": "Complete human approval before customer-machine execution handoff.",
            "completed_execution_run_required": "Complete or fail an execution run before result recording.",
            "approved_result_required": "Approve the result record before monitoring.",
            "approved_observation_required": "Approve monitoring observation before optimization.",
            "approved_optimization_decision_required": "Approve optimization decision before next-cycle content.",
            "approved_content_draft_required": "Approve a content draft before packaging a deliverable.",
            "terminal_execution_run_required": "Record a terminal execution run before result creation.",
        }
        return mapping.get(blocker, f"Resolve blocker: {blocker}.")

    @staticmethod
    def _next_operation_plan_version(plans: list[CommercialOperationPlan]) -> int:
        versions = [int(getattr(plan, "plan_version", 0) or 0) for plan in plans]
        return (max(versions) if versions else 0) + 1

    async def _main_agent_operation_plan_payload(
        self,
        *,
        operation: CommercialOperation,
        plans: list[CommercialOperationPlan],
        routing_decision: dict[str, Any],
        operator_note: str | None,
        metadata: dict[str, Any],
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        fallback_payload = self._main_agent_default_operation_plan_payload(operation=operation, plans=plans)
        regeneration_attempt = self._main_agent_operation_plan_regeneration_attempt(plans)
        rejected_plan_count = sum(
            1 for plan in plans if plan.plan_status == CommercialOperationPlanStatus.REJECTED.value
        )
        rag_context_status = (
            "collection_name_only_no_retrieved_chunks"
            if operation.knowledge_collection
            else "not_configured"
        )
        base_metadata: dict[str, Any] = {
            "plan_generation_contract": "main_agent_llm_structured_json_with_template_fallback",
            "plan_generation_source": "fallback",
            "llm_generation_status": "not_started",
            "regeneration_attempt": regeneration_attempt,
            "previous_rejected_plan_count": rejected_plan_count,
            "rag_context_status": rag_context_status,
        }
        try:
            llm_client = LLMClient(settings=get_settings())
            health = await llm_client.health_check()
            base_metadata.update(
                {
                    "llm_provider": health.provider,
                    "llm_model": health.model,
                    "llm_reachable": health.reachable,
                }
            )
            if not health.reachable:
                base_metadata.update(
                    {
                        "llm_generation_status": "unreachable",
                        "llm_error": health.error,
                    }
                )
                return fallback_payload, base_metadata

            response = await llm_client.generate(
                LLMRequest(
                    system_prompt=self._main_agent_operation_plan_system_prompt(),
                    user_prompt=self._main_agent_operation_plan_user_prompt(
                        operation=operation,
                        plans=plans,
                        routing_decision=routing_decision,
                        operator_note=operator_note,
                        metadata=metadata,
                        fallback_payload=fallback_payload,
                        regeneration_attempt=regeneration_attempt,
                    ),
                    temperature=0.75 if regeneration_attempt > 1 else 0.35,
                    max_tokens=3000,
                )
            )
            base_metadata.update(
                {
                    "llm_provider": response.provider,
                    "llm_model": response.model,
                    "llm_generation_status": "generated",
                    "llm_usage": response.usage,
                    "llm_response_chars": len(response.content),
                }
            )
            parsed = self._extract_json_object(response.content)
            if parsed is None:
                base_metadata["llm_generation_status"] = "unparseable_json"
                return fallback_payload, base_metadata
            payload = self._sanitize_llm_operation_plan_payload(
                operation=operation,
                raw_payload=parsed,
                fallback_payload=fallback_payload,
            )
            base_metadata.update(
                {
                    "plan_generation_source": "llm",
                    "llm_generation_status": "parsed",
                    "llm_json_fields": sorted(str(key) for key in parsed.keys()),
                }
            )
            return payload, base_metadata
        except Exception as exc:
            base_metadata.update(
                {
                    "plan_generation_source": "fallback",
                    "llm_generation_status": "failed",
                    "llm_error": str(exc)[:500],
                }
            )
            return fallback_payload, base_metadata

    def _main_agent_default_operation_plan_payload(
        self,
        *,
        operation: CommercialOperation,
        plans: list[CommercialOperationPlan],
    ) -> dict[str, Any]:
        regeneration_attempt = self._main_agent_operation_plan_regeneration_attempt(plans)
        payload = {
            "title": f"Operation plan: {operation.title}"[:255],
            "objective_summary": self._main_agent_objective_summary(operation),
            "audience_strategy": operation.target_audience or "",
            "channel_strategy": self._main_agent_channel_strategy(operation),
            "content_strategy": self._main_agent_content_strategy(operation),
            "production_scope": self._main_agent_default_production_scope(operation),
            "material_requirements": self._main_agent_material_requirements(operation),
            "kpis": self._main_agent_kpis(operation),
            "publish_schedule": self._main_agent_publish_schedule(operation),
            "risk_notes": self._main_agent_plan_risk_notes(operation),
        }
        if regeneration_attempt > 1:
            focus = self._main_agent_operation_plan_regeneration_focus(regeneration_attempt)
            payload["content_strategy"] = {
                **payload["content_strategy"],
                "regeneration_focus": focus,
                "regeneration_attempt": regeneration_attempt,
            }
            payload["objective_summary"] = (
                f"{payload['objective_summary']}\nRegeneration attempt {regeneration_attempt}: {focus}."
            )
        return payload

    @staticmethod
    def _main_agent_operation_plan_regeneration_attempt(plans: list[CommercialOperationPlan]) -> int:
        rejected_count = sum(1 for plan in plans if plan.plan_status == CommercialOperationPlanStatus.REJECTED.value)
        return rejected_count + 1

    @staticmethod
    def _main_agent_operation_plan_regeneration_focus(regeneration_attempt: int) -> str:
        focuses = [
            "tighten the conversion path and approval handoff",
            "strengthen visual and video production specificity",
            "improve channel-fit copy, hooks, and measurable KPIs",
            "reduce runtime risk and clarify material readiness",
        ]
        return focuses[(max(regeneration_attempt, 1) - 1) % len(focuses)]

    @staticmethod
    def _main_agent_operation_plan_system_prompt() -> str:
        return (
            "You are the Main Agent of an AI operations platform. "
            "Create a concrete, reviewable commercial operation plan. "
            "Return valid JSON only, without markdown fences or commentary. "
            "All human-facing string values must be written in Simplified Chinese. "
            "Do not claim that production, ComfyUI generation, publishing, account control, or analytics collection has started. "
            "The plan must keep human approval gates explicit."
        )

