    @staticmethod
    def _publish_prep_blocking_reasons(
        *,
        final_selection: CommercialOperationFinalSelection,
        selected_output_candidate: CommercialOperationOutputCandidate,
    ) -> list[str]:
        blocking: list[str] = []
        if final_selection.selection_status != CommercialOperationFinalSelectionStatus.APPROVED.value:
            blocking.append("final_selection_not_approved")
        if selected_output_candidate.candidate_status != CommercialOperationOutputCandidateStatus.SELECTED.value:
            blocking.append("output_candidate_not_selected")
        return blocking

    @staticmethod
    def _publish_prep_target_platforms(
        *,
        operation: CommercialOperation,
        final_selection: CommercialOperationFinalSelection,
    ) -> list[str]:
        candidates = final_selection.platform_targets or operation.channels or ["manual_review"]
        clean = [str(item).strip().lower() for item in candidates if str(item).strip()]
        return list(dict.fromkeys(clean)) or ["manual_review"]

    @staticmethod
    def _publish_prep_platform_policy(platform: str) -> dict[str, Any]:
        clean = platform.lower()
        if clean in {"douyin", "tiktok"}:
            return {
                "title_max_chars": 55,
                "body_max_chars": 2200,
                "recommended_hashtag_count": "3-6",
                "requires_video_or_image_asset": True,
                "requires_manual_account_confirmation": True,
                "metric_pull_targets": ["plays", "likes", "comments", "shares", "saves", "follows"],
            }
        if clean in {"xiaohongshu", "rednote"}:
            return {
                "title_max_chars": 20,
                "body_max_chars": 1000,
                "recommended_hashtag_count": "5-10",
                "requires_video_or_image_asset": True,
                "requires_manual_account_confirmation": True,
                "metric_pull_targets": ["views", "likes", "collects", "comments", "shares"],
            }
        if clean in {"wechat", "wechat_channels"}:
            return {
                "title_max_chars": 64,
                "body_max_chars": 2000,
                "recommended_hashtag_count": "0-3",
                "requires_video_or_image_asset": False,
                "requires_manual_account_confirmation": True,
                "metric_pull_targets": ["views", "likes", "shares", "follows"],
            }
        return {
            "title_max_chars": 80,
            "body_max_chars": 2000,
            "recommended_hashtag_count": "0-6",
            "requires_video_or_image_asset": False,
            "requires_manual_account_confirmation": True,
            "metric_pull_targets": ["reach", "engagement", "conversion"],
        }

    @staticmethod
    def _publish_prep_copy_guidance(
        *,
        operation: CommercialOperation,
        final_selection: CommercialOperationFinalSelection,
    ) -> dict[str, Any]:
        return {
            "objective": operation.objective,
            "target_audience": operation.target_audience,
            "success_metrics": operation.success_metrics,
            "constraints": operation.constraints,
            "selection_reason": final_selection.selection_reason,
            "editing_boundary": "operator_must_review_copy_before_publish_package_approval",
        }

    def _publish_prep_blueprint(
        self,
        *,
        operation: CommercialOperation,
        final_selection: CommercialOperationFinalSelection,
        selected_output_candidate: CommercialOperationOutputCandidate,
        platform: str,
    ) -> dict[str, Any]:
        hashtags = self._publish_prep_hashtags(operation=operation, platform=platform)
        body = self._publish_prep_default_body(
            operation=operation,
            final_selection=final_selection,
            selected_output_candidate=selected_output_candidate,
            platform=platform,
        )
        return {
            "platform": platform,
            "account_ref": None,
            "title": self._publish_prep_default_title(operation=operation, final_selection=final_selection, platform=platform),
            "body": body,
            "hashtags": hashtags,
            "cover_candidate_id": str(selected_output_candidate.id)
            if self._publish_prep_candidate_can_be_cover(selected_output_candidate)
            else None,
            "publish_payload": {
                "operation_id": str(operation.id),
                "final_selection_id": str(final_selection.id),
                "output_candidate_id": str(selected_output_candidate.id),
                "output_type": final_selection.final_type,
                "preview_uri": selected_output_candidate.preview_uri,
                "source_uri": selected_output_candidate.source_uri,
                "thumbnail_uri": selected_output_candidate.thumbnail_uri,
                "platform": platform,
                "client_execution_required": True,
                "openclaw_playwright_execution_not_included": True,
            },
            "risk_notes": "Must be approved by an operator before customer-machine OpenClaw/Playwright execution.",
            "metadata": {
                "source": "phase_68g_publish_prep_package",
                "phase": "68G",
                "operation_id": str(operation.id),
                "final_selection_id": str(final_selection.id),
                "output_candidate_id": str(selected_output_candidate.id),
            },
        }

    @staticmethod
    def _publish_prep_default_title(
        *,
        operation: CommercialOperation,
        final_selection: CommercialOperationFinalSelection,
        platform: str,
    ) -> str:
        prefix = final_selection.title or operation.title
        if platform.lower() in {"douyin", "tiktok"}:
            return f"{prefix} | {operation.title}"[:55]
        if platform.lower() in {"xiaohongshu", "rednote"}:
            return prefix[:20]
        return prefix[:80]

    @staticmethod
    def _publish_prep_default_body(
        *,
        operation: CommercialOperation,
        final_selection: CommercialOperationFinalSelection,
        selected_output_candidate: CommercialOperationOutputCandidate,
        platform: str,
    ) -> str:
        cta = f"Focus metric: {operation.success_metrics[0]}" if operation.success_metrics else "Leave room for operator CTA."
        lines = [
            operation.objective.strip(),
            final_selection.selection_reason or selected_output_candidate.generation_summary or final_selection.title,
            cta,
            "Operator must edit this copy for the real account before approval.",
        ]
        text = "\n".join(line for line in lines if line)
        max_chars = int(CommercialOperationService._publish_prep_platform_policy(platform)["body_max_chars"])
        return text[:max_chars]

    @staticmethod
    def _publish_prep_hashtags(*, operation: CommercialOperation, platform: str) -> list[str]:
        source_terms = [operation.title, *(operation.success_metrics or []), *(operation.channels or [])]
        hashtags: list[str] = []
        for item in source_terms:
            clean = "".join(ch for ch in str(item).strip() if ch.isalnum() or ch in {"_", "-"})
            if clean:
                hashtags.append(clean[:32])
        if platform.lower() in {"douyin", "tiktok"}:
            hashtags.append("AI运营")
        return list(dict.fromkeys(hashtags))[:6]

    @staticmethod
    def _publish_prep_candidate_can_be_cover(candidate: CommercialOperationOutputCandidate) -> bool:
        text = " ".join(
            str(value or "")
            for value in (candidate.candidate_type, candidate.mime_type, candidate.thumbnail_uri, candidate.preview_uri)
        ).lower()
        return any(token in text for token in ("image", "poster", "cover", ".png", ".jpg", ".jpeg", ".webp"))

