    def _metric_dispatch_claim_history(self, operation: CommercialOperation) -> list[dict[str, Any]]:
        metadata = dict(operation.operation_metadata or {})
        history = metadata.get("metric_analysis_dispatch_claim_history")
        return [dict(item) for item in history if isinstance(item, dict)] if isinstance(history, list) else []

    async def _metric_dispatch_active_claims_by_key(
        self,
        *,
        workspace_id: str,
        now: datetime,
    ) -> dict[str, dict[str, Any]]:
        active: dict[str, dict[str, Any]] = {}
        for operation in await self.list_operations(workspace_id=workspace_id, limit=500):
            for claim in self._metric_dispatch_claim_history(operation):
                computed = self._metric_dispatch_claim_with_computed_status(claim=claim, now=now)
                if computed.get("computed_claim_status") not in {"claimed", "running"}:
                    continue
                key = str(computed.get("dispatch_idempotency_key") or "")
                if key:
                    active[key] = computed
        return active

    async def _metric_dispatch_find_claim_operation(
        self,
        *,
        workspace_id: str,
        claim_id: UUID,
    ) -> tuple[CommercialOperation, list[dict[str, Any]], int]:
        for operation in await self.list_operations(workspace_id=workspace_id, limit=500):
            history = self._metric_dispatch_claim_history(operation)
            for index, claim in enumerate(history):
                if str(claim.get("claim_id")) == str(claim_id):
                    return operation, history, index
        raise ValueError("Metric dispatch claim not found in workspace")

