    @staticmethod
    def _publish_execution_published_url(package: CommercialOperationPublishPackage | None) -> str | None:
        if package is None:
            return None
        metadata = package.package_metadata or {}
        result = metadata.get("publish_execution_result")
        if isinstance(result, dict):
            value = result.get("published_url")
            if isinstance(value, str) and value.strip():
                return value.strip()
        payload = package.publish_payload if isinstance(package.publish_payload, dict) else {}
        for key in ("published_url", "content_url", "target_url"):
            value = payload.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return None

    @staticmethod
    def _publish_execution_blocking_reasons(
        *,
        package: CommercialOperationPublishPackage,
        final_selection: CommercialOperationFinalSelection | None,
    ) -> list[str]:
        blocking: list[str] = []
        if package.package_status not in {
            CommercialOperationPublishPackageStatus.APPROVED.value,
            CommercialOperationPublishPackageStatus.PREPARED.value,
        }:
            blocking.append("publish_package_not_approved_or_prepared")
        if package.final_selection_id is not None and final_selection is None:
            blocking.append("final_selection_missing")
        if final_selection and final_selection.selection_status != CommercialOperationFinalSelectionStatus.APPROVED.value:
            blocking.append("final_selection_not_approved")
        return blocking

    @staticmethod
    def _publish_execution_latest_status(package: CommercialOperationPublishPackage) -> dict[str, Any]:
        metadata = package.package_metadata or {}
        status = metadata.get("publish_execution_status")
        return dict(status) if isinstance(status, dict) else {}

    @staticmethod
    def _publish_execution_status_history(package: CommercialOperationPublishPackage) -> list[dict[str, Any]]:
        metadata = package.package_metadata or {}
        history = metadata.get("publish_execution_status_history")
        if not isinstance(history, list):
            return []
        return [dict(item) for item in history if isinstance(item, dict)]

    @staticmethod
    def _publish_execution_client_dry_run_gate(package: CommercialOperationPublishPackage) -> dict[str, Any]:
        latest = CommercialOperationService._publish_execution_latest_status(package)
        history = CommercialOperationService._publish_execution_status_history(package)
        records = [*history]
        if latest:
            records.append(latest)

        latest_dry_run_attempt: dict[str, Any] | None = None
        for record in reversed(records):
            metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
            execution_log = record.get("execution_log") if isinstance(record.get("execution_log"), list) else []
            evidence_links = record.get("evidence_links") if isinstance(record.get("evidence_links"), list) else []

            marker_values = [
                metadata.get("contract"),
                metadata.get("source"),
                metadata.get("phase"),
                metadata.get("dry_run_contract"),
                metadata.get("action_type"),
                record.get("phase"),
                record.get("source"),
            ]
            for item in [*execution_log, *evidence_links]:
                if isinstance(item, dict):
                    marker_values.extend(
                        [
                            item.get("title"),
                            item.get("type"),
                            item.get("source"),
                            item.get("contract"),
                            item.get("phase"),
                            item.get("action_type"),
                        ]
                    )

            marker_text = " ".join(str(value) for value in marker_values if value is not None).lower()
            marks_client_dry_run = (
                "client_publish_execution_dry_run_bridge" in marker_text
                or "phase 70h client publish openclaw dry-run bridge" in marker_text
                or "phase 70h client publish openclaw dry run bridge" in marker_text
                or str(metadata.get("phase") or "").strip().upper() == "70H"
            )
            if not marks_client_dry_run:
                continue

            latest_dry_run_attempt = dict(record)
            execution_status = str(record.get("execution_status") or "").strip().lower()
            has_failure = bool(record.get("failure_reason")) or execution_status in {
                "needs_operator",
                "failed",
                "cancelled",
            }
            if execution_status in {"running", "succeeded"} and not has_failure:
                return {
                    "gate_status": "dry_run_verified",
                    "dry_run_required": False,
                    "dry_run_verified": True,
                    "blocking_reasons": [],
                    "latest_dry_run_attempt": latest_dry_run_attempt,
                    "contract": "client_publish_execution_dry_run_result_gate",
                    "required_marker": "client_publish_execution_dry_run_bridge",
                    "required_statuses": ["running", "succeeded"],
                    "server_side_external_execution": False,
                    "server_does_not_control_real_accounts": True,
                }
            return {
                "gate_status": "dry_run_required",
                "dry_run_required": True,
                "dry_run_verified": False,
                "blocking_reasons": [
                    "client_publish_openclaw_dry_run_required_before_result_capture",
                    "client_publish_openclaw_dry_run_not_successful",
                ],
                "latest_dry_run_attempt": latest_dry_run_attempt,
                "contract": "client_publish_execution_dry_run_result_gate",
                "required_marker": "client_publish_execution_dry_run_bridge",
                "required_statuses": ["running", "succeeded"],
                "server_side_external_execution": False,
                "server_does_not_control_real_accounts": True,
            }

        return {
            "gate_status": "dry_run_required",
            "dry_run_required": True,
            "dry_run_verified": False,
            "blocking_reasons": ["client_publish_openclaw_dry_run_required_before_result_capture"],
            "latest_dry_run_attempt": None,
            "contract": "client_publish_execution_dry_run_result_gate",
            "required_marker": "client_publish_execution_dry_run_bridge",
            "required_statuses": ["running", "succeeded"],
            "server_side_external_execution": False,
            "server_does_not_control_real_accounts": True,
        }

    @staticmethod
    def _publish_execution_client_submit_gate(package: CommercialOperationPublishPackage) -> dict[str, Any]:
        latest = CommercialOperationService._publish_execution_latest_status(package)
        history = CommercialOperationService._publish_execution_status_history(package)
        records = [*history]
        if latest:
            records.append(latest)

        latest_submit_attempt: dict[str, Any] | None = None
        for record in reversed(records):
            metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
            execution_log = record.get("execution_log") if isinstance(record.get("execution_log"), list) else []
            evidence_links = record.get("evidence_links") if isinstance(record.get("evidence_links"), list) else []

            marker_values = [
                metadata.get("contract"),
                metadata.get("source"),
                metadata.get("phase"),
                metadata.get("action_type"),
                record.get("phase"),
                record.get("source"),
            ]
            actual_publish_performed = metadata.get("actual_publish_performed") is True
            operator_final_submit_confirmed = metadata.get("operator_final_submit_confirmed") is True
            mock_detected = metadata.get("local_openclaw_mock") is True
            for item in [*execution_log, *evidence_links]:
                if not isinstance(item, dict):
                    continue
                marker_values.extend(
                    [
                        item.get("title"),
                        item.get("type"),
                        item.get("source"),
                        item.get("contract"),
                        item.get("phase"),
                        item.get("action_type"),
                    ]
                )
                output_payload = item.get("output_payload")
                if isinstance(output_payload, dict):
                    actual_publish_performed = actual_publish_performed or output_payload.get(
                        "actual_publish_performed"
                    ) is True
                    actual_publish_performed = actual_publish_performed or output_payload.get(
                        "real_openclaw_called"
                    ) is True
                    mock_detected = mock_detected or output_payload.get("mock") is True
                if item.get("actual_publish_performed") is True:
                    actual_publish_performed = True
                if item.get("operator_final_submit_confirmed") is True:
                    operator_final_submit_confirmed = True
                if item.get("mock") is True:
                    mock_detected = True

            marker_text = " ".join(str(value) for value in marker_values if value is not None).lower()
            marks_client_submit = (
                "client_publish_execution_submit_bridge" in marker_text
                or "phase 70j client publish submit bridge" in marker_text
                or str(metadata.get("phase") or "").strip().upper() == "70J"
            )
            if not marks_client_submit:
                continue

            latest_submit_attempt = dict(record)
            execution_status = str(record.get("execution_status") or "").strip().lower()
            has_failure = bool(record.get("failure_reason")) or execution_status in {
                "needs_operator",
                "failed",
                "cancelled",
            }
            if (
                execution_status == "succeeded"
                and not has_failure
                and actual_publish_performed
                and operator_final_submit_confirmed
                and not mock_detected
            ):
                return {
                    "gate_status": "submit_verified",
                    "submit_required": False,
                    "submit_verified": True,
                    "blocking_reasons": [],
                    "latest_submit_attempt": latest_submit_attempt,
                    "contract": "client_publish_execution_submit_result_gate",
                    "required_marker": "client_publish_execution_submit_bridge",
                    "required_statuses": ["succeeded"],
                    "requires_actual_publish_performed": True,
                    "rejects_mock_provider": True,
                    "server_side_external_execution": False,
                    "server_does_not_control_real_accounts": True,
                }
            return {
                "gate_status": "submit_evidence_required",
                "submit_required": True,
                "submit_verified": False,
                "blocking_reasons": [
                    "client_publish_submit_evidence_required_before_result_capture",
                    "client_publish_submit_evidence_not_successful",
                ],
                "latest_submit_attempt": latest_submit_attempt,
                "contract": "client_publish_execution_submit_result_gate",
                "required_marker": "client_publish_execution_submit_bridge",
                "required_statuses": ["succeeded"],
                "requires_actual_publish_performed": True,
                "rejects_mock_provider": True,
                "server_side_external_execution": False,
                "server_does_not_control_real_accounts": True,
            }

        return {
            "gate_status": "submit_evidence_required",
            "submit_required": True,
            "submit_verified": False,
            "blocking_reasons": ["client_publish_submit_evidence_required_before_result_capture"],
            "latest_submit_attempt": None,
            "contract": "client_publish_execution_submit_result_gate",
            "required_marker": "client_publish_execution_submit_bridge",
            "required_statuses": ["succeeded"],
            "requires_actual_publish_performed": True,
            "rejects_mock_provider": True,
            "server_side_external_execution": False,
            "server_does_not_control_real_accounts": True,
        }

    @staticmethod
    def _publish_execution_default_progress(execution_status: str, progress: int | None) -> int:
        if progress is not None:
            return max(0, min(int(progress), 100))
        return {
            "queued": 5,
            "running": 50,
            "needs_operator": 60,
            "succeeded": 95,
            "failed": 100,
            "cancelled": 100,
        }.get(execution_status, 0)

    @staticmethod
    def _publish_execution_status_retry_policy(
        *,
        execution_status: str,
        retry_after_seconds: int | None,
    ) -> dict[str, Any]:
        can_retry = execution_status in {"needs_operator", "failed", "cancelled"}
        return {
            "can_retry": can_retry,
            "retry_requires_operator_confirmation": can_retry,
            "retry_after_seconds": retry_after_seconds,
            "requires_operator_intervention": execution_status in {"needs_operator", "failed", "cancelled"},
            "result_capture_required": execution_status == "succeeded",
            "status_update_required_before_result_capture": execution_status in {"queued", "running", "needs_operator"},
        }

