    @staticmethod
    def _publish_execution_clean_records(
        values: list[dict[str, Any]] | None,
        *,
        default_type: str,
    ) -> list[dict[str, Any]]:
        records: list[dict[str, Any]] = []
        for item in values or []:
            if not isinstance(item, dict):
                continue
            label = str(item.get("title") or item.get("name") or item.get("step") or item.get("url") or "").strip()
            if not label:
                continue
            cleaned = dict(item)
            cleaned["title"] = label
            cleaned.setdefault("type", default_type)
            cleaned["evidence_boundary"] = "operator-reported; not fetched or verified automatically"
            records.append(cleaned)
        return records

