    @classmethod
    def _sensitive_action_audit_paths(cls, value: Any, *, path: str = "payload") -> list[str]:
        sensitive_key_parts = (
            "password",
            "passwd",
            "pwd",
            "token",
            "secret",
            "cookie",
            "authorization",
            "credential",
            "sessionid",
            "apikey",
            "api_key",
            "accesskey",
            "access_key",
            "refresh_token",
            "验证码",
            "短信验证码",
        )
        sensitive_value_markers = (
            "access_token=",
            "refresh_token=",
            "password=",
            "cookie=",
            "authorization:",
            "x-api-key=",
        )
        found: list[str] = []
        if isinstance(value, dict):
            for key, nested in value.items():
                key_text = str(key)
                key_lower = key_text.lower()
                normalized_key = key_lower.replace("-", "_").replace(" ", "_")
                current_path = f"{path}.{key_text}"
                if any(part in normalized_key for part in sensitive_key_parts):
                    found.append(current_path)
                found.extend(cls._sensitive_action_audit_paths(nested, path=current_path))
        elif isinstance(value, list):
            for index, item in enumerate(value):
                found.extend(cls._sensitive_action_audit_paths(item, path=f"{path}[{index}]"))
        elif isinstance(value, str):
            lower_value = value.lower()
            if any(marker in lower_value for marker in sensitive_value_markers):
                found.append(path)
        return found

    @staticmethod
    def _production_closed_loop_result_endpoint_matches(target_endpoint: str, result_endpoint: str) -> bool:
        clean_target = (target_endpoint or "").strip().rstrip("/")
        clean_result = (result_endpoint or "").strip().rstrip("/")
        if not clean_target or not clean_result:
            return True
        if clean_result == clean_target:
            return True
        return clean_result.startswith(f"{clean_target}/")

    async def _validate_production_closed_loop_result_record_reference(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        result_record_type: str,
        result_record_id: UUID,
        expected_result: dict[str, Any],
    ) -> dict[str, Any]:
        specs = self._production_closed_loop_result_record_specs()
        clean_type = self._normalize_result_record_type(result_record_type)
        spec = specs.get(clean_type)
        supported_record_types = sorted({item["canonical_type"] for item in specs.values()})
        if spec is None:
            return {
                "validation_status": "record_type_unsupported",
                "result_record_type": result_record_type,
                "result_record_id": str(result_record_id),
                "record_exists": False,
                "workspace_matches": False,
                "operation_matches": False,
                "status_matches": False,
                "status_field": None,
                "record_status": None,
                "expected_statuses": [],
                "record_summary": {},
                "supported_record_types": supported_record_types,
            }

        result = await self.session.execute(select(spec["model"]).where(spec["model"].id == result_record_id))
        record = result.scalar_one_or_none()
        expected_statuses = self._expected_result_statuses(expected_result=expected_result, status_field=spec["status_field"])
        if record is None:
            return {
                "validation_status": "record_missing",
                "result_record_type": spec["canonical_type"],
                "result_record_id": str(result_record_id),
                "record_exists": False,
                "workspace_matches": False,
                "operation_matches": False,
                "status_matches": False,
                "status_field": spec["status_field"],
                "record_status": None,
                "expected_statuses": sorted(expected_statuses),
                "record_summary": {},
                "supported_record_types": supported_record_types,
            }

        record_workspace_id = str(getattr(record, "workspace_id", "") or "")
        record_operation_id = getattr(record, "operation_id", None)
        workspace_matches = record_workspace_id == workspace_id
        operation_matches = str(record_operation_id or "") == str(operation_id)
        metadata_record: dict[str, Any] | None = None
        metadata_record_key = spec.get("metadata_record_key")
        if metadata_record_key:
            metadata_field = str(spec.get("metadata_field") or "")
            record_metadata = getattr(record, metadata_field, None)
            if isinstance(record_metadata, dict) and isinstance(record_metadata.get(metadata_record_key), dict):
                metadata_record = dict(record_metadata[metadata_record_key])
            if metadata_record is None:
                return {
                    "validation_status": "metadata_record_missing",
                    "result_record_type": spec["canonical_type"],
                    "result_record_id": str(result_record_id),
                    "record_exists": True,
                    "workspace_matches": workspace_matches,
                    "operation_matches": operation_matches,
                    "status_matches": False,
                    "status_field": spec["status_field"],
                    "record_status": None,
                    "expected_statuses": sorted(expected_statuses),
                    "record_summary": self._json_safe_dict(
                        {
                            "id": str(getattr(record, "id", result_record_id)),
                            "workspace_id": record_workspace_id,
                            "operation_id": str(record_operation_id) if record_operation_id else None,
                            "record_type": spec["canonical_type"],
                            "metadata_record_key": metadata_record_key,
                            "metadata_record_present": False,
                            "updated_at": getattr(record, "updated_at", None),
                        }
                    ),
                    "supported_record_types": supported_record_types,
                }
            record_status = str(metadata_record.get(spec["status_field"]) or "")
        else:
            record_status = str(getattr(record, spec["status_field"], "") or "")
        status_matches = record_status in expected_statuses if expected_statuses else record_status not in spec["terminal_statuses"]
        if not workspace_matches or not operation_matches:
            validation_status = "record_scope_mismatch"
        elif expected_statuses and not status_matches:
            validation_status = "record_status_mismatch"
        elif record_status in spec["terminal_statuses"] and not status_matches:
            validation_status = "record_status_terminal"
        else:
            validation_status = "record_verified"

        title_value = getattr(record, spec["title_field"], None) if spec.get("title_field") else None
        record_summary = {
            "id": str(getattr(record, "id", result_record_id)),
            "workspace_id": record_workspace_id,
            "operation_id": str(record_operation_id) if record_operation_id else None,
            "record_type": spec["canonical_type"],
            "title": title_value,
            "status": record_status,
            "status_field": spec["status_field"],
            "updated_at": getattr(record, "updated_at", None),
        }
        if metadata_record is not None:
            record_summary["metadata_record_key"] = str(metadata_record_key)
            record_summary["metadata_record"] = metadata_record
        return {
            "validation_status": validation_status,
            "result_record_type": spec["canonical_type"],
            "result_record_id": str(result_record_id),
            "record_exists": True,
            "workspace_matches": workspace_matches,
            "operation_matches": operation_matches,
            "status_matches": status_matches,
            "status_field": spec["status_field"],
            "record_status": record_status,
            "expected_statuses": sorted(expected_statuses),
            "record_summary": self._json_safe_dict(record_summary),
            "supported_record_types": supported_record_types,
        }

    @classmethod
    def _production_closed_loop_result_record_specs(cls) -> dict[str, dict[str, Any]]:
        base_specs: list[dict[str, Any]] = [
            {
                "canonical_type": "OperationPlan",
                "aliases": ["operationplan", "commercialoperationplan", "plan"],
                "model": CommercialOperationPlan,
                "status_field": "plan_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "ProjectMaterial",
                "aliases": ["projectmaterial", "commercialoperationprojectmaterial", "material"],
                "model": CommercialOperationProjectMaterial,
                "status_field": "material_status",
                "title_field": "name",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "ProductionTask",
                "aliases": ["productiontask", "commercialoperationproductiontask", "task"],
                "model": CommercialOperationProductionTask,
                "status_field": "task_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "WorkflowSelection",
                "aliases": ["workflowselection", "commercialoperationworkflowselection"],
                "model": CommercialOperationWorkflowSelection,
                "status_field": "selection_status",
                "title_field": "workflow_name",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "OutputCandidate",
                "aliases": ["outputcandidate", "commercialoperationoutputcandidate", "candidate"],
                "model": CommercialOperationOutputCandidate,
                "status_field": "candidate_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "FinalSelection",
                "aliases": ["finalselection", "commercialoperationfinalselection"],
                "model": CommercialOperationFinalSelection,
                "status_field": "selection_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "PublishPackage",
                "aliases": ["publishpackage", "commercialoperationpublishpackage"],
                "model": CommercialOperationPublishPackage,
                "status_field": "package_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived", "failed"},
            },
            {
                "canonical_type": "PublishExecutionStatus",
                "aliases": [
                    "publishexecutionstatus",
                    "commercialoperationpublishexecutionstatus",
                    "customer_machine_publish_execution_status",
                ],
                "model": CommercialOperationPublishPackage,
                "status_field": "execution_status",
                "title_field": "title",
                "terminal_statuses": {"failed", "cancelled"},
                "metadata_field": "package_metadata",
                "metadata_record_key": "publish_execution_status",
            },
            {
                "canonical_type": "PlatformMetricSnapshot",
                "aliases": ["platformmetricsnapshot", "metricSnapshot", "metricsnapshot", "commercialoperationplatformmetricsnapshot"],
                "model": CommercialOperationPlatformMetricSnapshot,
                "status_field": "snapshot_status",
                "title_field": None,
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "CommercialOperationResult",
                "aliases": ["commercialoperationresult", "operationresult", "result"],
                "model": CommercialOperationResult,
                "status_field": "result_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "MonitoringObservation",
                "aliases": ["monitoringobservation", "commercialoperationmonitoringobservation", "observation"],
                "model": CommercialOperationMonitoringObservation,
                "status_field": "observation_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
            {
                "canonical_type": "OptimizationDecision",
                "aliases": ["optimizationdecision", "commercialoperationoptimizationdecision", "decision"],
                "model": CommercialOperationOptimizationDecision,
                "status_field": "decision_status",
                "title_field": "title",
                "terminal_statuses": {"rejected", "archived"},
            },
        ]
        specs: dict[str, dict[str, Any]] = {}
        for spec in base_specs:
            keys = [spec["canonical_type"], *spec["aliases"]]
            for key in keys:
                specs[cls._normalize_result_record_type(str(key))] = spec
        return specs

    @staticmethod
    def _normalize_result_record_type(value: str) -> str:
        return "".join(ch for ch in str(value or "").lower() if ch.isalnum())

    @staticmethod
    def _expected_result_statuses(*, expected_result: dict[str, Any], status_field: str) -> set[str]:
        candidates: list[str] = []
        for key in ("status", status_field, "expected_status", "result_status"):
            value = expected_result.get(key) if isinstance(expected_result, dict) else None
            if isinstance(value, str) and value.strip():
                candidates.append(value.strip())
        statuses: set[str] = set()
        for candidate in candidates:
            normalized = candidate.lower().replace(" ", "_")
            if normalized in {"draft_or_ready_for_review", "draft_or_review"}:
                statuses.update({"draft", "ready_for_review"})
            elif normalized in {"approved_or_prepared"}:
                statuses.update({"approved", "prepared"})
            elif normalized in {"published_or_failed"}:
                statuses.update({"published", "failed"})
            elif normalized in {"captured_success_or_failure"}:
                statuses.update({"captured_success", "captured_failure"})
            else:
                statuses.add(normalized)
        return statuses

    @staticmethod
    def _main_agent_operation_text(operation: CommercialOperation) -> str:
        metadata = operation.operation_metadata if isinstance(operation.operation_metadata, dict) else {}
        metadata_text = " ".join(str(value) for value in metadata.values() if isinstance(value, str))
        return " ".join(
            [
                operation.title,
                operation.objective,
                operation.target_audience or "",
                " ".join(str(item) for item in operation.channels or []),
                " ".join(str(item) for item in operation.success_metrics or []),
                " ".join(str(item) for item in operation.constraints or []),
                metadata_text,
            ]
        ).lower()

    @staticmethod
    def _text_has_any(text: str, keywords: tuple[str, ...]) -> bool:
        return any(keyword.lower() in text for keyword in keywords)

    @staticmethod
    def _main_agent_channel(operation: CommercialOperation) -> str:
        channels = [item.strip() for item in operation.channels or [] if item and item.strip()]
        return channels[0] if channels else "general"

    @staticmethod
    def _main_agent_channel_is_social(channel: str | None) -> bool:
        clean = (channel or "").lower()
        return any(token in clean for token in ("douyin", "tiktok", "wechat", "xiaohongshu", "instagram", "social"))

    def _main_agent_content_format(self, *, channel: str, track: str) -> str:
        clean = channel.lower()
        if track == "text_content" and any(token in clean for token in ("newsletter", "email", "mail")):
            return "email"
        if track == "text_content" and any(token in clean for token in ("douyin", "tiktok", "video")):
            return "script"
        if any(token in clean for token in ("post", "social", "douyin", "tiktok", "wechat", "xiaohongshu")):
            return "post"
        return "copy"

    @staticmethod
    def _main_agent_content_title(*, operation: CommercialOperation, track: str) -> str:
        prefix = "Content strategy brief" if track == "content_strategy" else "Content draft"
        return f"{prefix}: {operation.title}"[:255]

    @staticmethod
    def _main_agent_content_summary(*, operation: CommercialOperation, track: str) -> str:
        if track == "content_strategy":
            return "Reviewable content direction, channel fit, and asset plan before production."
        return f"Reviewable content draft for {operation.objective[:180]}"

    def _main_agent_content_body(
        self,
        *,
        operation: CommercialOperation,
        track: str,
        routing_decision: dict[str, Any],
    ) -> str:
        if track == "content_strategy":
            mode = "text, visual, or video package should be selected by review based on channel constraints."
        else:
            mode = "text content is prepared as a reviewable draft; no publishing is performed."
        return "\n".join(
            [
                f"Objective: {operation.objective}",
                f"Audience: {operation.target_audience or 'to be confirmed'}",
                f"Channel: {self._main_agent_channel(operation)}",
                f"Content direction: {mode}",
                f"Evidence source: {operation.knowledge_collection or 'operator supplied knowledge'}",
                f"Main Agent rationale: {routing_decision.get('rationale')}",
                "Boundary: human review is required; this draft does not publish, execute OpenClaw, run Playwright, or call ComfyUI.",
            ]
        )

    @staticmethod
    def _main_agent_call_to_action(operation: CommercialOperation) -> str | None:
        metrics = [item for item in operation.success_metrics or [] if item]
        if metrics:
            return f"Optimize for {metrics[0]}"
        return None

    @staticmethod
    def _main_agent_source_materials(operation: CommercialOperation) -> list[str]:
        materials = []
        if operation.knowledge_collection:
            materials.append(f"collection:{operation.knowledge_collection}")
        return materials

    @staticmethod
    def _main_agent_asset_type(track: str) -> str:
        if track == "video_content":
            return "video"
        if track == "visual_asset":
            return "image"
        return "other"

    @staticmethod
    def _main_agent_asset_title(*, operation: CommercialOperation, track: str) -> str:
        prefixes = {
            "video_content": "Video brief",
            "visual_asset": "Visual asset brief",
            "workflow_selection": "Workflow selection brief",
        }
        return f"{prefixes.get(track, 'Asset brief')}: {operation.title}"[:255]

    @staticmethod
    def _main_agent_asset_purpose(*, operation: CommercialOperation, track: str) -> str:
        if track == "video_content":
            return "Prepare a digital-human or short-video production brief without rendering."
        if track == "workflow_selection":
            return "Rank suitable ComfyUI workflow candidates from approved workflow knowledge before runtime handoff."
        return "Prepare a visual asset brief without generating the asset."

    @staticmethod
    def _main_agent_asset_style_constraints(*, track: str) -> str:
        if track == "video_content":
            return "9:16 commercial short-video framing; virtual presenter must be AI-generated and reviewed."
        if track == "workflow_selection":
            return "Workflow choice must list required models, runtime blockers, and fallback workflow."
        return "Brand-safe commercial visual style; no unapproved logos or unreadable text."

    @staticmethod
    def _main_agent_asset_prompt(*, operation: CommercialOperation, track: str) -> str:
        if track == "video_content":
            return (
                "Create a reviewable short-video brief with scene, AI virtual presenter, shot list, "
                f"and approval gates for objective: {operation.objective}"
            )
        if track == "workflow_selection":
            return (
                "Rank ComfyUI workflow candidates for this operation, including required models, "
                f"input assets, runtime blockers, and fallback path: {operation.objective}"
            )
        return f"Create a reviewable visual asset brief for objective: {operation.objective}"

    @staticmethod
    def _main_agent_deliverable_type(draft: CommercialOperationContentDraft) -> str:
        if draft.content_format in {"email", "post", "script", "landing_page", "ad"}:
            return draft.content_format
        return "content_package"

    @staticmethod
    def _main_agent_next_cycle_body(
        *,
        operation: CommercialOperation,
        decision: CommercialOperationOptimizationDecision,
    ) -> str:
        content_actions = "\n".join(f"- {item}" for item in decision.content_actions or ["Prepare reviewed iteration."])
        risk_controls = "\n".join(f"- {item}" for item in decision.risk_controls or ["Human review remains required."])
        return "\n".join(
            [
                f"Objective: {operation.objective}",
                f"Approved optimization rationale: {decision.rationale or 'Use approved observation to improve the next cycle.'}",
                "Content actions:",
                content_actions,
                "Risk controls:",
                risk_controls,
                "Boundary: this is a next-cycle draft only; it does not publish, execute, or call external runtimes.",
            ]
        )

    @staticmethod
    def _agent_skill_status(loop_stage_status: str) -> str:
        status_map = {
            "complete": "complete",
            "in_progress": "active",
            "review_required": "needs_review",
            "blocked": "blocked",
            "missing": "waiting",
        }
        return status_map.get(loop_stage_status, "waiting")

    async def create_approval(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        step_key: str,
        title: str,
        requested_by: str | None = None,
        requested_action: str | None = None,
        risk_level: str = "medium",
        metadata: dict[str, Any] | None = None,
    ) -> CommercialOperationApproval:
        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        clean_step_key = self._clean_required_text(step_key, "step_key")
        if not self._plan_step(operation, clean_step_key):
            raise ValueError("step_key is not present in operation plan_outline")
        approval = CommercialOperationApproval(
            workspace_id=workspace_id,
            operation_id=operation_id,
            step_key=clean_step_key,
            title=self._clean_required_text(title, "title"),
            requested_action=requested_action.strip() if requested_action and requested_action.strip() else None,
            approval_status=CommercialOperationApprovalStatus.PENDING.value,
            risk_level=risk_level,
            requested_by=requested_by,
            approval_metadata=metadata or {},
        )
        self.session.add(approval)
        await self.session.flush()
        self._apply_approval_to_plan(operation, approval)
        await self.session.commit()
        await self.session.refresh(approval)
        return approval

    async def list_approvals(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        status: str | None = None,
        limit: int = 100,
    ) -> list[CommercialOperationApproval]:
        await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        statement = select(CommercialOperationApproval).where(
            CommercialOperationApproval.workspace_id == workspace_id,
            CommercialOperationApproval.operation_id == operation_id,
        )
        if status is not None:
            statement = statement.where(CommercialOperationApproval.approval_status == status)
        result = await self.session.execute(
            statement.order_by(CommercialOperationApproval.updated_at.desc()).limit(limit)
        )
        return list(result.scalars().all())

    async def require_approval(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        approval_id: UUID,
    ) -> CommercialOperationApproval:
        result = await self.session.execute(
            select(CommercialOperationApproval).where(
                CommercialOperationApproval.workspace_id == workspace_id,
                CommercialOperationApproval.operation_id == operation_id,
                CommercialOperationApproval.id == approval_id,
            )
        )
        approval = result.scalar_one_or_none()
        if approval is None:
            raise ValueError("Commercial operation approval not found in workspace")
        return approval

