    async def link_digital_human_delivery_asset(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        digital_human_video_job_id: UUID,
        delivery_asset_id: UUID | None = None,
        content_draft_id: UUID | None = None,
        step_key: str = "content_production",
        channel: str | None = None,
        title: str | None = None,
        purpose: str | None = None,
        actor_user_id: str | None = None,
        metadata: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        """Attach a generated digital-human video to the commercial deliverable loop."""

        operation = await self.require_operation(workspace_id=workspace_id, operation_id=operation_id)
        job = await self._require_digital_human_video_job(
            workspace_id=workspace_id,
            digital_human_video_job_id=digital_human_video_job_id,
        )
        if job.job_status != "completed":
            raise ValueError("Digital human video job must be completed before delivery linking")

        delivery_record = self._digital_human_delivery_output_from_job(job)
        resolved_delivery_asset_id = delivery_asset_id or self._digital_human_delivery_asset_id_from_record(delivery_record)
        if resolved_delivery_asset_id is None:
            raise ValueError("Digital human video job has no generated delivery asset to link")
        delivery_asset = await self._require_digital_human_asset(
            workspace_id=workspace_id,
            delivery_asset_id=resolved_delivery_asset_id,
        )
        if delivery_asset.asset_type != "video":
            raise ValueError("Digital human delivery asset must be a video asset")
        if not self._digital_human_asset_matches_job(
            job=job,
            delivery_asset=delivery_asset,
            delivery_record=delivery_record,
        ):
            raise ValueError("Digital human delivery asset is not linked to the requested video job")

        requested_step_key = self._clean_required_text(step_key, "step_key")
        content_draft: CommercialOperationContentDraft | None = None
        if content_draft_id is not None:
            content_draft = await self.require_content_draft(
                workspace_id=workspace_id,
                operation_id=operation_id,
                draft_id=content_draft_id,
            )
            if content_draft.step_key != requested_step_key:
                raise ValueError("step_key must match the content draft step_key")
        else:
            content_draft = self._first_record(
                await self.list_content_drafts(
                    workspace_id=workspace_id,
                    operation_id=operation_id,
                    status=CommercialOperationContentDraftStatus.APPROVED.value,
                ),
                lambda item: item.draft_status == CommercialOperationContentDraftStatus.APPROVED.value,
            )
        clean_step_key = content_draft.step_key if content_draft is not None else requested_step_key
        if not self._plan_step(operation, clean_step_key):
            raise ValueError("step_key is not present in operation plan_outline")

        channel_candidate = (
            channel
            or (content_draft.channel if content_draft is not None else None)
            or self._first_clean_string(job.target_channels or [])
            or self._first_clean_string(operation.channels or [])
            or "digital_human"
        )
        clean_channel = self._clean_required_text(str(channel_candidate), "channel")
        clean_title = (
            self._clean_required_text(title, "title")
            if title and title.strip()
            else f"Digital human video delivery: {delivery_asset.name}"
        )[:255]
        clean_purpose = (
            purpose.strip()
            if purpose and purpose.strip()
            else "Use the generated digital-human video as a reviewable commercial operation delivery asset."
        )
        delivery_output_count = self._digital_human_delivery_output_count(job=job, delivery_record=delivery_record)
        now = datetime.now(UTC)

        existing_request = await self._find_digital_human_delivery_asset_request(
            workspace_id=workspace_id,
            operation_id=operation_id,
            delivery_asset_id=delivery_asset.id,
            content_draft_id=content_draft.id if content_draft is not None else None,
        )
        if existing_request is not None:
            link_status = "reused"
            if content_draft is not None and existing_request.content_draft_id is None:
                existing_request.content_draft_id = content_draft.id
                existing_request.step_key = content_draft.step_key
                existing_request.channel = clean_channel
            existing_request.title = clean_title
            existing_request.asset_type = "video"
            existing_request.purpose = clean_purpose
            existing_request.source_materials = self._digital_human_delivery_source_materials(
                content_draft=content_draft,
                job=job,
                delivery_asset=delivery_asset,
            )
            existing_request.readiness_checks = self._digital_human_delivery_readiness_checks()
            existing_request.asset_metadata = self._digital_human_delivery_asset_request_metadata(
                operation=operation,
                job=job,
                delivery_asset=delivery_asset,
                delivery_record=delivery_record,
                delivery_output_count=delivery_output_count,
                metadata=metadata,
            )
            existing_request.handoff_payload = self._build_digital_human_delivery_handoff_payload(
                operation=operation,
                asset_request=existing_request,
                job=job,
                delivery_asset=delivery_asset,
                delivery_record=delivery_record,
                delivery_output_count=delivery_output_count,
            )
            existing_request.result_summary = "Generated digital-human video asset is linked and ready for deliverable packaging."
            existing_request.failure_reason = None
            existing_request.updated_by = actor_user_id
            if existing_request.request_status not in {
                CommercialOperationAssetRequestStatus.APPROVED.value,
                CommercialOperationAssetRequestStatus.PREPARED.value,
            }:
                existing_request.request_status = CommercialOperationAssetRequestStatus.PREPARED.value
                existing_request.prepared_by = actor_user_id
                existing_request.prepared_at = now
                existing_request.failed_at = None
                existing_request.archived_at = None
            self._apply_asset_request_to_plan(operation, existing_request)
            await self.session.commit()
            await self.session.refresh(existing_request)
            asset_request = existing_request
        else:
            link_status = "created"
            asset_request = CommercialOperationAssetRequest(
                workspace_id=workspace_id,
                operation_id=operation_id,
                content_draft_id=content_draft.id if content_draft is not None else None,
                step_key=clean_step_key,
                channel=clean_channel,
                asset_type="video",
                title=clean_title,
                request_status=CommercialOperationAssetRequestStatus.PREPARED.value,
                purpose=clean_purpose,
                dimensions="9:16" if job.aspect_ratio == "9:16" else job.aspect_ratio,
                style_constraints=None,
                generation_prompt=None,
                negative_prompt=None,
                source_materials=self._digital_human_delivery_source_materials(
                    content_draft=content_draft,
                    job=job,
                    delivery_asset=delivery_asset,
                ),
                readiness_checks=self._digital_human_delivery_readiness_checks(),
                result_summary="Generated digital-human video asset is linked and ready for deliverable packaging.",
                failure_reason=None,
                requested_by=actor_user_id,
                updated_by=actor_user_id,
                prepared_by=actor_user_id,
                prepared_at=now,
                asset_metadata=self._digital_human_delivery_asset_request_metadata(
                    operation=operation,
                    job=job,
                    delivery_asset=delivery_asset,
                    delivery_record=delivery_record,
                    delivery_output_count=delivery_output_count,
                    metadata=metadata,
                ),
            )
            asset_request.handoff_payload = self._build_digital_human_delivery_handoff_payload(
                operation=operation,
                asset_request=asset_request,
                job=job,
                delivery_asset=delivery_asset,
                delivery_record=delivery_record,
                delivery_output_count=delivery_output_count,
            )
            self.session.add(asset_request)
            await self.session.flush()
            self._apply_asset_request_to_plan(operation, asset_request)
            await self.session.commit()
            await self.session.refresh(asset_request)

        return {
            "operation_id": operation.id,
            "workspace_id": workspace_id,
            "link_status": link_status,
            "digital_human_video_job_id": job.id,
            "delivery_asset_id": delivery_asset.id,
            "deliverable_ready": content_draft is not None
            and content_draft.draft_status == CommercialOperationContentDraftStatus.APPROVED.value,
            "asset_request": asset_request,
            "next_actions": self._digital_human_delivery_next_actions(content_draft=content_draft),
            "boundaries": [
                "links an already generated digital-human video asset only",
                "does not alter ComfyUI workflows or resubmit prompts",
                "does not publish, control accounts, or run OpenClaw/Playwright",
                "does not bypass deliverable or execution approval",
            ],
        }

