    async def _require_digital_human_video_job(
        self,
        *,
        workspace_id: str,
        digital_human_video_job_id: UUID,
    ) -> DigitalHumanVideoJob:
        result = await self.session.execute(
            select(DigitalHumanVideoJob).where(
                DigitalHumanVideoJob.workspace_id == workspace_id,
                DigitalHumanVideoJob.id == digital_human_video_job_id,
            )
        )
        job = result.scalar_one_or_none()
        if job is None:
            raise ValueError("Digital human video job not found in workspace")
        return job

    async def _require_digital_human_asset(
        self,
        *,
        workspace_id: str,
        delivery_asset_id: UUID,
    ) -> DigitalHumanAsset:
        result = await self.session.execute(
            select(DigitalHumanAsset).where(
                DigitalHumanAsset.workspace_id == workspace_id,
                DigitalHumanAsset.id == delivery_asset_id,
            )
        )
        asset = result.scalar_one_or_none()
        if asset is None:
            raise ValueError("Digital human delivery asset not found in workspace")
        return asset

    def _digital_human_delivery_output_from_job(self, job: DigitalHumanVideoJob) -> dict[str, Any]:
        for item in reversed(job.outputs or []):
            if not isinstance(item, dict):
                continue
            if item.get("output_type") in {
                "digital_human_comfyui_delivery_asset",
                "digital_human_delivery_manifest",
            } and (item.get("asset_id") or item.get("source_uri")):
                return dict(item)
        return {}

    def _digital_human_delivery_asset_id_from_record(self, delivery_record: dict[str, Any]) -> UUID | None:
        raw_asset_id = delivery_record.get("asset_id") or delivery_record.get("delivery_asset_id")
        if not isinstance(raw_asset_id, str) or not raw_asset_id.strip():
            return None
        try:
            return UUID(raw_asset_id.strip())
        except ValueError:
            return None

    def _digital_human_asset_matches_job(
        self,
        *,
        job: DigitalHumanVideoJob,
        delivery_asset: DigitalHumanAsset,
        delivery_record: dict[str, Any],
    ) -> bool:
        delivery_asset_id = str(delivery_asset.id)
        job_id = str(job.id)
        record_asset_id = str(delivery_record.get("asset_id") or delivery_record.get("delivery_asset_id") or "")
        metadata = delivery_asset.asset_metadata or {}
        provider_response = job.provider_response or {}
        return (
            record_asset_id == delivery_asset_id
            or str(metadata.get("digital_human_video_job_id") or "") == job_id
            or str(provider_response.get("delivery_asset_id") or "") == delivery_asset_id
            or str(provider_response.get("output_asset_id") or "") == delivery_asset_id
        )

    def _digital_human_delivery_output_count(
        self,
        *,
        job: DigitalHumanVideoJob,
        delivery_record: dict[str, Any],
    ) -> int:
        record_count = delivery_record.get("output_count")
        if isinstance(record_count, int):
            return record_count
        record_outputs = delivery_record.get("outputs")
        if isinstance(record_outputs, list):
            return len(record_outputs)
        provider_count = (job.provider_response or {}).get("output_count")
        if isinstance(provider_count, int):
            return provider_count
        return 1 if delivery_record else 0

    async def _find_digital_human_delivery_asset_request(
        self,
        *,
        workspace_id: str,
        operation_id: UUID,
        delivery_asset_id: UUID,
        content_draft_id: UUID | None,
    ) -> CommercialOperationAssetRequest | None:
        requests = await self.list_asset_requests(
            workspace_id=workspace_id,
            operation_id=operation_id,
            limit=500,
        )
        target = str(delivery_asset_id)
        for asset_request in requests:
            if asset_request.request_status == CommercialOperationAssetRequestStatus.ARCHIVED.value:
                continue
            if content_draft_id is not None and asset_request.content_draft_id not in {None, content_draft_id}:
                continue
            metadata = asset_request.asset_metadata or {}
            handoff_payload = asset_request.handoff_payload or {}
            handoff_asset = handoff_payload.get("digital_human_delivery_asset")
            candidate_ids = {
                str(metadata.get("digital_human_delivery_asset_id") or ""),
                str(metadata.get("delivery_asset_id") or ""),
            }
            if isinstance(handoff_asset, dict):
                candidate_ids.add(str(handoff_asset.get("asset_id") or ""))
                candidate_ids.add(str(handoff_asset.get("delivery_asset_id") or ""))
            if target in candidate_ids:
                return asset_request
        return None

    def _digital_human_delivery_source_materials(
        self,
        *,
        content_draft: CommercialOperationContentDraft | None,
        job: DigitalHumanVideoJob,
        delivery_asset: DigitalHumanAsset,
    ) -> list[str]:
        candidates = [
            *(content_draft.source_materials if content_draft is not None else []),
            f"digital_human_video_job:{job.id}",
            f"digital_human_asset:{delivery_asset.id}",
            delivery_asset.source_uri,
        ]
        seen: set[str] = set()
        materials: list[str] = []
        for item in self._clean_list([str(candidate) for candidate in candidates if candidate]):
            if item not in seen:
                seen.add(item)
                materials.append(item)
        return materials

